CREATE OR REPLACE FUNCTION crm_api.acceptance_apply(f2p bytea, f2s bytea, f1p bytea, f1s bytea, q bytea)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare hf text[];tf text[];fields text[];a jsonb;p crm_private.b03_proposals;o crm_private.b03_opportunities;
 v crm_private.b03_proposal_versions;i crm_private.b03_offer_issuances;prior crm_private.b03_acceptance_operations;
 acc crm_private.b03_acceptances;com crm_private.b07_records;des crm_private.identity_designations;
 op uuid;aid uuid;root uuid;vid uuid;opp uuid;actor uuid;s text;action text;cov text;at_time timestamptz;
 fp text;res jsonb;norm jsonb;original jsonb;identified boolean;selectable boolean;valid boolean;proof_ok boolean;aspect text;
 stale_at timestamptz;reviewed boolean;destination text;
begin
 hf:=crm_f2.admit(f2p,f2s,q,'C03','write_evidence');tf:=crm_f1.verify_envelope(f1p,f1s,q,'C03','evidence','write_evidence');
 if hf[17] collate "C"<>tf[14] collate "C" then raise exception 'ACCEPTANCE_DENIED';end if;
 fields:=crm_f1.fields(q);if cardinality(fields)<>2 or fields[1]<>'CRM-H2-ACCEPTANCE1' then raise exception 'ACCEPTANCE_INPUT_INVALID';end if;a:=fields[2]::jsonb;
 if jsonb_typeof(a) is distinct from 'object' or a-array['action','operationId','acceptanceId','proposalId','opportunityId','versionId','expectedRevision','expectedOpportunityRevision','sourceRef','reason','coverage','at','accepterId','designationId','channel','terms','evidenceId','communicationId','authorityEvidenceId','reviewEvidence','won','humanReviewed','reevaluation','origin']<>'{}'::jsonb
 or not(a ?& array['action','operationId','acceptanceId','proposalId','opportunityId','versionId','expectedRevision','expectedOpportunityRevision','sourceRef','reason','coverage','at'])
 or a->>'action' not in ('candidate','register','verify','rectify')
 or jsonb_typeof(a->'expectedRevision') is distinct from 'number' or jsonb_typeof(a->'expectedOpportunityRevision') is distinct from 'number'
 or a->>'expectedRevision' !~ '^[0-9]+$' or a->>'expectedOpportunityRevision' !~ '^[0-9]+$'
 or exists(select 1 from jsonb_each(a) x where x.key in ('sourceRef','reason','coverage','at') and (jsonb_typeof(x.value)<>'string' or btrim(x.value#>>'{}')=''))
 or (a ? 'won' and jsonb_typeof(a->'won') is distinct from 'boolean')
 or (a ? 'humanReviewed' and jsonb_typeof(a->'humanReviewed') is distinct from 'boolean')
 or a->>'at' !~ '^\d{4}-\d\d-\d\dT\d\d:\d\d:\d\d(\.\d+)?(Z|[+-]\d\d:\d\d)$' then raise exception 'ACCEPTANCE_INPUT_INVALID';end if;
 op:=(a->>'operationId')::uuid;aid:=(a->>'acceptanceId')::uuid;root:=(a->>'proposalId')::uuid;vid:=(a->>'versionId')::uuid;opp:=(a->>'opportunityId')::uuid;
 actor:=hf[12]::uuid;s:=hf[17];action:=a->>'action';cov:=a->>'coverage';at_time:=(a->>'at')::timestamptz;
 if at_time>clock_timestamp() then raise exception 'ACCEPTANCE_FUTURE_FACT';end if;
 if coalesce(a->>'origin','manual')<>'manual' then raise exception 'ACCEPTANCE_HUMAN_REVIEW_REQUIRED:G3';end if;
 fp:=encode(crm_crypto.digest(convert_to(a::text,'UTF8'),'sha256'),'hex');
 perform pg_advisory_xact_lock(hashtextextended(op::text,0));
 select * into prior from crm_private.b03_acceptance_operations where operation_id=op;
 if found then
  if prior.admin_scope<>s or prior.actor_id<>actor or prior.fingerprint<>fp then raise exception 'ACCEPTANCE_REPLAY_CONFLICT';end if;
  res:=jsonb_build_object('id',op,'replayed',true,'result',prior.result);
 else
  perform pg_advisory_xact_lock(hashtextextended(opp::text,31));
  select * into o from crm_private.b03_opportunities where opportunity_id=opp and admin_scope=s for update;
  if not found then raise exception 'ACCEPTANCE_RELATION_INVALID';end if;
  perform pg_advisory_xact_lock(hashtextextended(root::text,33));
  select * into p from crm_private.b03_proposals where proposal_id=root and opportunity_id=opp and admin_scope=s for update;
  if not found then raise exception 'ACCEPTANCE_RELATION_INVALID';end if;
  select * into v from crm_private.b03_proposal_versions where version_id=vid and proposal_id=root and admin_scope=s;
  if not found then raise exception 'ACCEPTANCE_RELATION_INVALID';end if;
  if p.revision<>(a->>'expectedRevision')::bigint or o.revision<>(a->>'expectedOpportunityRevision')::bigint then raise exception 'ACCEPTANCE_REVISION_CONFLICT:G6';end if;
  original:=jsonb_build_object('proposalRevision',p.revision,'opportunity',to_jsonb(o));
  select * into acc from crm_private.b03_acceptances where acceptance_id=aid and admin_scope=s;
  if acc.acceptance_id is not null and (acc.proposal_id<>root or acc.version_id<>vid or acc.opportunity_id<>opp or acc.coverage<>cov) then raise exception 'ACCEPTANCE_EXACT_RELATION_REQUIRED';end if;
  if action in ('candidate','register') then
   if acc.acceptance_id is not null then raise exception 'ACCEPTANCE_IMMUTABLE:SM-FORB-02';end if;
   select * into des from crm_private.identity_designations where designation_id=nullif(a->>'designationId','')::uuid and admin_scope=s;
   identified:=a ?& array['accepterId','designationId','channel','terms','evidenceId','authorityEvidenceId']
    and a->'terms'=v.content->'terms' and nullif(btrim(a->>'channel'),'') is not null
    and des.party_id=nullif(a->>'accepterId','')::uuid and des.context_id=opp and des.role_kind='primary_contact' and des.verified
    and coalesce(des.effective_at,des.recorded_at)<=at_time and (des.ended_at is null or des.ended_at>at_time)
    and exists(select 1 from crm_private.identity_entities e where e.identity_id=des.party_id and e.admin_scope=s and e.identity_kind='contact' and e.identity_verified)
    and crm_private.offer_evidence(nullif(a->>'authorityEvidenceId','')::uuid,opp,s,'acceptance:authority:'||vid||':'||(a->>'accepterId')||':'||(a->>'designationId'),cov,'-infinity',at_time);
   selectable:=cov=v.scope or exists(select 1 from crm_private.b03_proposal_modalities m where m.version_id=vid and m.modality_id::text=cov and m.independent and m.selectable)
    or exists(select 1 from crm_private.b03_proposal_lines l where l.version_id=vid and l.line_id::text=cov and l.independent and l.selectable);
   if action='register' and coalesce(identified,false) and selectable then
    if not exists(select 1 from crm_private.b07_records e join crm_private.b07_links l using(record_id) where e.record_id=(a->>'evidenceId')::uuid and e.admin_scope=s and l.admin_scope=s and l.context_id=opp and l.context_kind='opportunity' and l.coverage=cov and e.record_kind='evidence') then raise exception 'ACCEPTANCE_EVIDENCE_REQUIRED';end if;
    insert into crm_private.b03_acceptances(acceptance_id,proposal_id,opportunity_id,version_id,admin_scope,accepter_id,designation_id,channel,coverage,terms,content_snapshot,evidence_id,authority_evidence_id,communication_id,occurred_at,actor_id,source_ref)
     values(aid,root,opp,vid,s,(a->>'accepterId')::uuid,des.designation_id,a->>'channel',cov,v.content->'terms',v.content,(a->>'evidenceId')::uuid,(a->>'authorityEvidenceId')::uuid,nullif(a->>'communicationId','')::uuid,at_time,actor,a->>'sourceRef');
    res:=jsonb_build_object('registered',true,'verified',false,'won',false,'acceptanceId',aid);norm:=jsonb_build_array('SM-AC-01','DM-INV-009','DM-INV-010');
   else
    if not exists(select 1 from crm_private.b07_records e join crm_private.b07_links l using(record_id) where e.record_id=nullif(a->>'evidenceId','')::uuid and e.admin_scope=s and l.admin_scope=s and l.context_id=opp and l.context_kind='opportunity' and l.coverage=cov) then raise exception 'ACCEPTANCE_CANDIDATE_SOURCE_REQUIRED';end if;
    res:=jsonb_build_object('registered',false,'verified',false,'won',false,'pendingReview',true,'requiresNewVersion',not selectable);norm:=jsonb_build_array('SM-AC-01','SPEC-FR-ACC-003','E7');
   end if;
  elsif action='verify' then
   if acc.acceptance_id is null then raise exception 'ACCEPTANCE_REGISTERED_REQUIRED:SM-AC-02';end if;
   if exists(select 1 from crm_private.b03_acceptance_verifications where acceptance_id=aid and (won or not coalesce((a->>'won')::boolean,false))) or exists(select 1 from crm_private.b03_acceptance_rectifications where acceptance_id=aid) then raise exception 'ACCEPTANCE_ALREADY_DECIDED';end if;
   if at_time<>acc.occurred_at then raise exception 'ACCEPTANCE_ACT_IMMUTABLE';end if;
   -- All verification facts refer to the immutable registration, not replacement request fields.
   if a ?| array['terms','accepterId','designationId','channel','evidenceId','authorityEvidenceId','communicationId'] then raise exception 'ACCEPTANCE_REGISTRATION_IMMUTABLE';end if;
   select * into i from crm_private.b03_offer_issuances where version_id=vid and admin_scope=s;
   select max(t) into stale_at from (
    select e.occurred_at t from crm_private.b03_offer_operations e where e.version_id=vid and e.action in ('reject','evaluate') and (e.action='reject' or e.result->'pending'='true') and e.occurred_at<=at_time and crm_private.offer_overlap(vid,e.coverage,cov)
    union all select z.recorded_at from crm_private.b03_proposal_versions z where z.replaces_version_id=vid and z.recorded_at<=at_time
   ) x;
   reviewed:=exists(select 1 from crm_private.b03_offer_operations e where e.version_id=vid and e.action='revalidate' and e.coverage=cov and e.event->>'actId'=aid::text and e.event->>'actKind'='accept' and e.occurred_at=at_time and e.occurred_at>=coalesce(stale_at,'-infinity') and not exists(select 1 from jsonb_each_text(e.event->'reviewEvidence') z left join crm_private.b07_records b on b.record_id=z.value::uuid where b.occurred_at>=at_time or b.record_id is null));
   valid:=i.version_id is not null and at_time>=i.issued_at and ((at_time<=i.effective_until and stale_at is null) or reviewed);
   proof_ok:=crm_private.offer_evidence(acc.evidence_id,opp,s,'acceptance:agree:'||vid||':'||aid||':'||acc.accepter_id||':'||acc.channel,cov,at_time,at_time);
   if acc.communication_id is not null then
    select * into com from crm_private.b07_records where record_id=acc.communication_id and admin_scope=s;
    proof_ok:=proof_ok and com.record_kind='communication' and com.material->>'direction'='incoming' and com.material->>'sender_ref'=acc.accepter_id::text and com.material->>'proposal_version_ref'=vid::text and com.material->>'coverage'=cov and com.material->>'channel'=acc.channel and com.occurred_at=at_time
     and exists(select 1 from crm_private.b07_links l where l.record_id=com.record_id and l.admin_scope=s and l.context_id=opp and l.context_kind='opportunity' and l.coverage=cov);
   elsif acc.channel not in ('phone','advance') then proof_ok:=false;
   end if;
   foreach aspect in array array['prices','availability','conditions','capacity'] loop
    proof_ok:=proof_ok and crm_private.offer_evidence((a->'reviewEvidence'->>aspect)::uuid,opp,s,'offer:review:'||vid||':'||aid||':accept:'||aspect,cov,coalesce(stale_at,i.issued_at),at_time);
   end loop;
   if not coalesce(valid,false) or not coalesce(proof_ok,false) then raise exception 'ACCEPTANCE_VERIFICATION_REQUIRED:SM-AC-02,SM-FORB-01';end if;
   if exists(select 1 from jsonb_array_elements(v.economics) e where (cov=v.scope or cov=e->>'modalityId' or exists(select 1 from crm_private.b03_proposal_lines l where l.version_id=vid and l.modality_id::text=e->>'modalityId' and l.line_id::text=cov)) and (e->'calculated'='null' or jsonb_array_length(e->'blockers')>0)) then raise exception 'ACCEPTANCE_MATERIAL_DATA_REQUIRED:G2';end if;
   if coalesce((a->>'won')::boolean,false) and o.state not in ('Nueva','En contacto','Necesidad definida','Propuesta en preparación','Propuesta enviada','Negociación / cambios') then raise exception 'ACCEPTANCE_ACTIVE_ORIGIN_REQUIRED:SM-OP-07';end if;
   insert into crm_private.b03_acceptance_verifications(verification_id,acceptance_id,admin_scope,actor_id,material,won,commercial_before) values(op,aid,s,actor,a,coalesce((a->>'won')::boolean,false),to_jsonb(o));
   if coalesce((a->>'won')::boolean,false) then
    insert into crm_private.b03_operations(operation_id,admin_scope,actor_id,fingerprint,result_ref) values(op,s,actor,fp,opp);
    insert into crm_private.b03_history(history_id,subject_id,admin_scope,before_state,after_state,event,normative_ids,reason,source_ref,actor_id,occurred_at)
     values(op,opp,s,to_jsonb(o),jsonb_set(jsonb_set(to_jsonb(o),'{state}','"Aceptada / Ganada"'),'{revision}',to_jsonb(o.revision+1)),a,'["SM-OP-07"]',a->>'reason',a->>'sourceRef',actor,at_time);
    update crm_private.b03_opportunities set state='Aceptada / Ganada',revision=revision+1,updated_at=clock_timestamp() where opportunity_id=opp;
   end if;
   res:=jsonb_build_object('registered',true,'verified',true,'won',coalesce((a->>'won')::boolean,false),'acceptanceId',aid,'coverage',cov,'terms',acc.terms);
   norm:=jsonb_build_array('SM-AC-02','SM-PV-07','SM-OP-07','PLAN-T02');
  else
   if acc.acceptance_id is null or a->'humanReviewed' is distinct from 'true'::jsonb or exists(select 1 from crm_private.b03_acceptance_rectifications where acceptance_id=aid)
    or not crm_private.offer_evidence((a->>'evidenceId')::uuid,opp,s,'acceptance:error:'||aid,cov,'-infinity',at_time)
    or jsonb_typeof(a->'reevaluation') is distinct from 'object' or (a->'reevaluation')-array['destination','evidenceId','dependentEffects']<>'{}'::jsonb
    or a->'reevaluation'->'dependentEffects' is distinct from '["verification","commercial"]'::jsonb then raise exception 'ACCEPTANCE_ERROR_REVIEW_REQUIRED:SM-AC-03';end if;
   destination:=a->'reevaluation'->>'destination';
   if destination not in ('Nueva','En contacto','Necesidad definida','Propuesta en preparación','Propuesta enviada','Negociación / cambios')
    or not crm_private.offer_evidence((a->'reevaluation'->>'evidenceId')::uuid,opp,s,'acceptance:reevaluate:'||aid||':'||destination,cov,'-infinity',at_time) then raise exception 'ACCEPTANCE_CURRENT_COMMERCIAL_REVIEW_REQUIRED';end if;
   insert into crm_private.b03_acceptance_rectifications(rectification_id,acceptance_id,admin_scope,actor_id,evidence_id,reason,reevaluation) values(op,aid,s,actor,(a->>'evidenceId')::uuid,a->>'reason',a->'reevaluation');
   if o.state='Aceptada / Ganada' and not exists(select 1 from crm_private.b03_acceptance_verifications z join crm_private.b03_acceptances b using(acceptance_id) where b.opportunity_id=opp and z.won and not exists(select 1 from crm_private.b03_acceptance_rectifications r where r.acceptance_id=b.acceptance_id)) then
    insert into crm_private.b03_operations(operation_id,admin_scope,actor_id,fingerprint,result_ref) values(op,s,actor,fp,opp);
    insert into crm_private.b03_history(history_id,subject_id,admin_scope,before_state,after_state,event,normative_ids,reason,source_ref,actor_id,occurred_at) values(op,opp,s,to_jsonb(o),jsonb_set(jsonb_set(to_jsonb(o),'{state}',to_jsonb(destination)),'{revision}',to_jsonb(o.revision+1)),a,'["SM-AC-03"]',a->>'reason',a->>'sourceRef',actor,at_time);
    update crm_private.b03_opportunities set state=destination,revision=revision+1,updated_at=clock_timestamp() where opportunity_id=opp;
   end if;
   res:=jsonb_build_object('rectified',true,'originalPreserved',true,'verificationUsable',false,'reevaluation',a->'reevaluation');norm:=jsonb_build_array('SM-AC-03','SM-FORB-02','SM-FORB-32','AC-075');
  end if;
  insert into crm_private.b03_acceptance_operations(operation_id,acceptance_id,proposal_id,version_id,admin_scope,actor_id,fingerprint,action,event,result,source_ref,reason) values(op,aid,root,vid,s,actor,fp,action,a,res,a->>'sourceRef',a->>'reason');
  insert into crm_private.b03_acceptance_history(history_id,admin_scope,before_data,after_data,normative_ids,actor_id) values(op,s,original,res,norm,actor);
  update crm_private.b03_proposals set revision=revision+1 where proposal_id=root;
  res:=jsonb_build_object('id',op,'replayed',false,'result',res);
 end if;
 perform crm_f2.verify(f2p,f2s,q,'C03','human_evidence','write_evidence');perform crm_f1.verify_envelope(f1p,f1s,q,'C03','evidence','write_evidence');return res;
end $function$

CREATE OR REPLACE FUNCTION crm_api.acceptance_read(f2p bytea, f2s bytea, f1p bytea, f1s bytea, q bytea)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare hf text[];tf text[];fields text[];a jsonb;res jsonb;begin
 hf:=crm_f2.admit(f2p,f2s,q,'C01','read_evidence');tf:=crm_f1.verify_envelope(f1p,f1s,q,'C01','evidence','read_evidence');
 if hf[17] collate "C"<>tf[14] collate "C" then raise exception 'ACCEPTANCE_DENIED';end if;
 fields:=crm_f1.fields(q);if cardinality(fields)<>2 or fields[1]<>'CRM-H2-ACCEPTANCE-READ1' then raise exception 'ACCEPTANCE_INPUT_INVALID';end if;a:=fields[2]::jsonb;
 if a-array['proposalId','versionId']<>'{}'::jsonb or not exists(select 1 from crm_private.b03_proposal_versions where version_id=(a->>'versionId')::uuid and proposal_id=(a->>'proposalId')::uuid and admin_scope=hf[17]) then raise exception 'ACCEPTANCE_DENIED';end if;
 select jsonb_build_object('facts',coalesce((select jsonb_agg(to_jsonb(z) order by z.recorded_at) from crm_private.b03_acceptances z where z.version_id=(a->>'versionId')::uuid and z.admin_scope=hf[17]),'[]'),
 'operations',coalesce((select jsonb_agg(to_jsonb(z) order by z.recorded_at) from crm_private.b03_acceptance_operations z where z.version_id=(a->>'versionId')::uuid and z.admin_scope=hf[17]),'[]')) into res;
 perform crm_f2.verify(f2p,f2s,q,'C01','human_evidence','read_evidence');perform crm_f1.verify_envelope(f1p,f1s,q,'C01','evidence','read_evidence');return res;
end $function$

CREATE OR REPLACE FUNCTION crm_api.allocation_apply(f2p bytea, f2s bytea, f1p bytea, f1s bytea, q bytea)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare cancel_bid uuid;cancel_opp uuid;hf text[];tf text[];fs text[];a jsonb;p jsonb;prev crm_private.b05_fund_operations;pid uuid;op uuid;actor uuid;s text;fp text;hash text;rev bigint;pr bigint;action text;r jsonb;old jsonb;state jsonb;item jsonb;calcp jsonb;partq jsonb;start_at numeric;amt numeric;at_time timestamptz;basis jsonb;basis_hash text;original crm_private.b05_fund_distributions;act record;results jsonb:='[]';
begin
 hf:=crm_f2.admit(f2p,f2s,q,'C03','write_evidence');tf:=crm_f1.verify_envelope(f1p,f1s,q,'C03','evidence','write_evidence');if hf[17] collate "C"<>tf[14] collate "C" then raise exception 'ALLOCATION_DENIED';end if;
 fs:=crm_f1.fields(q);if cardinality(fs)<>2 or fs[1]<>'CRM-H3-ALLOCATION1' then raise exception 'ALLOCATION_INPUT_INVALID';end if;a:=fs[2]::jsonb;action:=a->>'action';
 if jsonb_typeof(a) is distinct from 'object' or a-array['action','operationId','paymentId','expectedRevision','expectedPaymentRevision','sourceRef','reason','at','evidenceId','origin','cause','economicBasis','allocationId','originalAllocationId','originalActId','reconciliationId','expectedReconciliationRevision','destination','start','amount','expectedScheduleRevision','distributionId','total','parts','calculation']<>'{}'::jsonb
 or not(a ?& array['action','operationId','paymentId','expectedRevision','expectedPaymentRevision','sourceRef','reason','at','evidenceId']) or action not in ('plan','assign','verify','consume','reverse','rectify','distribute','reverse_distribution')
 or jsonb_typeof(a->'expectedRevision') is distinct from 'number' or a->>'expectedRevision'!~'^[0-9]+$' or jsonb_typeof(a->'expectedPaymentRevision') is distinct from 'number' or a->>'expectedPaymentRevision'!~'^[0-9]+$'
 or coalesce(a->>'origin','manual') not in ('manual','ai') or (coalesce(a->>'origin','manual')='ai' and action<>'plan')
 or coalesce(a->>'cause','ordinary') not in ('ordinary','correction','cancellation','refund','new_obligation','modification')
 or exists(select 1 from jsonb_each(a) x where x.key in ('sourceRef','reason','at') and (jsonb_typeof(x.value)<>'string' or btrim(x.value#>>'{}')=''))
 or a->>'at'!~'^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}(\.[0-9]+)?(Z|[+-][0-9]{2}:[0-9]{2})$' then raise exception 'ALLOCATION_INPUT_INVALID';end if;
 pid:=(a->>'paymentId')::uuid;op:=(a->>'operationId')::uuid;actor:=hf[12]::uuid;s:=hf[17];at_time:=(a->>'at')::timestamptz;
 if a->>'cause' in('cancellation','refund') then
  select d.booking_id,b.opportunity_id into cancel_bid,cancel_opp from crm_private.b06_cancellation_determinations d join crm_private.b04_bookings b using(booking_id) where d.determination_id=(a->'economicBasis'->>'originalRef')::uuid and d.admin_scope=s;
  if not found then raise exception 'ALLOCATION_D019_REQUIRED:E3';end if;
  perform pg_advisory_xact_lock(hashtextextended(cancel_opp::text,31));perform pg_advisory_xact_lock(hashtextextended(cancel_bid::text,52));
 end if;
 fp:=encode(crm_crypto.digest(convert_to(a::text,'UTF8'),'sha256'),'hex');perform pg_advisory_xact_lock(hashtextextended('allocation-op:'||op,0));
 select * into prev from crm_private.b05_fund_operations where operation_id=op;
 if found then if prev.admin_scope<>s or prev.actor_id<>actor or prev.fingerprint<>fp then raise exception 'ALLOCATION_REPLAY_CONFLICT:E2';end if;r:=prev.result||jsonb_build_object('replayed',true);
 else
  perform pg_advisory_xact_lock(hashtextextended('payment-root:'||pid,0));
  select revision,snapshot into pr,p from crm_private.b05_payment_revisions where payment_id=pid and admin_scope=s order by revision desc limit 1;if not found then raise exception 'ALLOCATION_CONTEXT_REQUIRED';end if;
  select coalesce(max(revision),0) into rev from crm_private.b05_fund_revisions where payment_id=pid and admin_scope=s;
  if rev<>(a->>'expectedRevision')::bigint or pr<>(a->>'expectedPaymentRevision')::bigint then raise exception 'ALLOCATION_REVISION_CONFLICT:E2';end if;
  hash:=encode(crm_crypto.digest(convert_to((a-array['operationId','evidenceId','calculation'])::text,'UTF8'),'sha256'),'hex');
  if not crm_private.payment_evidence((a->>'evidenceId')::uuid,pid,s,'allocation:'||action||':'||hash,at_time,action<>'plan') then raise exception 'ALLOCATION_EVIDENCE_REQUIRED';end if;
  if a->>'cause' in ('cancellation','refund','new_obligation','modification') then
   basis:=a->'economicBasis';basis_hash:=encode(crm_crypto.digest(convert_to((basis-'evidenceId')::text,'UTF8'),'sha256'),'hex');
   if jsonb_typeof(basis) is distinct from 'object' or basis-array['kind','amount','originalRef','sourceRef','version','evidenceId']<>'{}'::jsonb or not(basis ?& array['kind','amount','originalRef','sourceRef','version','evidenceId'])
   or exists(select 1 from unnest(array['kind','originalRef','sourceRef','version','evidenceId']) field where jsonb_typeof(basis->field) is distinct from 'string' or coalesce(btrim(basis->>field),'')='')
   or basis->>'kind' is distinct from a->>'cause' or not coalesce(crm_private.payment_amount(basis->'amount'),false) or btrim(basis->>'originalRef')='' or btrim(basis->>'sourceRef')='' or btrim(basis->>'version')=''
   or not crm_private.payment_evidence((basis->>'evidenceId')::uuid,pid,s,'fund-right:'||basis_hash,at_time,true) then raise exception 'ALLOCATION_D019_REQUIRED:E3';end if;
   if a?'amount' and abs((a->>'amount')::numeric)<>(basis->>'amount')::numeric or a?'total' and abs((a->>'total')::numeric)<>(basis->>'amount')::numeric then raise exception 'ALLOCATION_D019_REQUIRED:E3';end if;
   if a->>'cause' in('cancellation','refund') and crm_private.cancellation_fund_basis(basis,pid,s) is distinct from true then raise exception 'ALLOCATION_D019_REQUIRED:E3';end if;
  elsif a?'economicBasis' then raise exception 'ALLOCATION_INPUT_INVALID';end if;
  old:=crm_private.fund_summary(pid,s);
  if action in ('plan','assign','verify','rectify') then
   if action='rectify' then
    select act_id into op from crm_private.b05_allocation_acts where allocation_id=(a->>'originalAllocationId')::uuid and kind in ('assign','verify','distribute') order by recorded_at limit 1;
    if op is null then raise exception 'ALLOCATION_ORIGINAL_REQUIRED';end if;
    results:=jsonb_build_array(crm_private.fund_reverse(a||jsonb_build_object('originalActId',op),s,actor,(a->>'operationId')::uuid));op:=(a->>'operationId')::uuid;
   end if;
   state:=crm_private.fund_assign(a,p,s,actor,op,case when action='rectify' then 'assign' else action end,(a->>'originalAllocationId')::uuid);results:=results||jsonb_build_array(state);
  elsif action='consume' then
   select snapshot into state from crm_private.b05_allocation_revisions where allocation_id=(a->>'allocationId')::uuid and admin_scope=s order by revision desc limit 1;
   if state is null or state->>'paymentId'<>pid::text or state->>'status'<>'verified' or not coalesce(crm_private.payment_amount(a->'start'),false) or not coalesce(crm_private.payment_amount(a->'amount',true),false) or a->'destination' is distinct from state->'destination' then raise exception 'ALLOCATION_CONSUMPTION_REQUIRED';end if;
   start_at:=(a->>'start')::numeric;amt:=(a->>'amount')::numeric;
   if start_at<(state->>'start')::numeric or start_at+amt>(state->>'start')::numeric+(state->>'amount')::numeric or crm_private.fund_usable(state||jsonb_build_object('start',a->>'start','amount',a->>'amount'),p)<>amt
   or exists(select 1 from crm_private.b05_allocation_acts z where z.allocation_id=(state->>'id')::uuid and z.kind='consume' and z.start_amount<start_at+amt and z.start_amount-z.signed_amount>start_at and not exists(select 1 from crm_private.b05_allocation_acts correction where correction.original_act_id=z.act_id)) then raise exception 'ALLOCATION_CONSUMPTION_USED_OR_SUSPENDED';end if;
   insert into crm_private.b05_allocation_acts values(gen_random_uuid(),op,(state->>'id')::uuid,pid,s,action,start_at,-amt,null,state,state,actor,a->>'reason',a->>'sourceRef',(a->>'evidenceId')::uuid,at_time,clock_timestamp());results:=jsonb_build_array(jsonb_build_object('consumed',a->>'amount','purpose',state->'destination'->>'purpose','externalExecution',false));
  elsif action='reverse' then results:=jsonb_build_array(crm_private.fund_reverse(a,s,actor,op));
  elsif action in ('distribute','reverse_distribution') then
   if not coalesce(crm_private.fund_calculation_valid(a->'calculation'),false) or (a->'calculation'->'input'->>'total') is distinct from a->>'total' then raise exception 'ALLOCATION_CALCULATION_INVALID';end if;
   if action='distribute' then
    if not coalesce(crm_private.payment_amount(a->'total',true),false) or not coalesce(crm_private.payment_amount(a->'start'),false) or a->>'distributionId' is null or jsonb_array_length(a->'parts')<>jsonb_array_length(a->'calculation'->'output'->'parts') then raise exception 'ALLOCATION_DISTRIBUTION_REQUIRED';end if;
    insert into crm_private.b05_fund_distributions values((a->>'distributionId')::uuid,pid,s,op,null,a->'calculation',actor,clock_timestamp());start_at:=(a->>'start')::numeric;
    for calcp in select value from jsonb_array_elements(a->'calculation'->'output'->'parts') order by (value->>'order')::bigint loop
     select value into item from jsonb_array_elements(a->'parts') where value->>'id'=calcp->>'id';if item is null or item->>'weight'<>calcp->>'weight' or item->>'order'<>calcp->>'order' then raise exception 'ALLOCATION_DISTRIBUTION_REQUIRED';end if;
     if (calcp->>'amount')::numeric>0 then partq:=a||jsonb_build_object('allocationId',item->>'id','reconciliationId',item->>'reconciliationId','expectedReconciliationRevision',item->'expectedReconciliationRevision','destination',item->'destination','start',trunc(start_at,2)::text,'amount',calcp->>'amount');
      state:=crm_private.fund_assign(partq,p,s,actor,op,'distribute');results:=results||jsonb_build_array(state);end if;
     start_at:=start_at+(calcp->>'amount')::numeric;
    end loop;
   else
    select * into original from crm_private.b05_fund_distributions where distribution_id=(a->>'distributionId')::uuid and payment_id=pid and admin_scope=s;
    if not found or original.original_distribution_id is not null or (a->>'total')::numeric<>-(original.calculation->'output'->>'total')::numeric or a->'calculation'->'input'->'parts' is distinct from original.calculation->'input'->'parts' then raise exception 'ALLOCATION_ORIGINAL_REQUIRED';end if;
    for act in select z.act_id from crm_private.b05_allocation_acts z where z.operation_id=original.operation_id and z.kind='distribute' order by z.start_amount loop results:=results||jsonb_build_array(crm_private.fund_reverse(a||jsonb_build_object('originalActId',act.act_id),s,actor,op));end loop;
    insert into crm_private.b05_fund_distributions values(op,pid,s,op,original.distribution_id,a->'calculation',actor,clock_timestamp());
   end if;
  end if;
  rev:=crm_private.fund_refresh(pid,s,actor,'allocation_operation',op,null);
  r:=jsonb_build_object('id',pid,'replayed',false,'result',jsonb_build_object('revision',rev,'effects',results,'summary',crm_private.fund_summary(pid,s)));
  insert into crm_private.b05_fund_operations values(op,pid,s,actor,fp,a,r,clock_timestamp());
  insert into crm_private.b05_fund_history values(op,pid,s,old,r,actor,a->>'reason',a->>'sourceRef',(a->>'evidenceId')::uuid,at_time,clock_timestamp());
 end if;
 perform crm_f2.verify(f2p,f2s,q,'C03','human_evidence','write_evidence');perform crm_f1.verify_envelope(f1p,f1s,q,'C03','evidence','write_evidence');return r;
end$function$

CREATE OR REPLACE FUNCTION crm_api.allocation_read(f2p bytea, f2s bytea, f1p bytea, f1s bytea, q bytea)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare hf text[];tf text[];fs text[];a jsonb;pid uuid;s text;rev bigint;pr bigint;r jsonb;coverage jsonb:='[]';sid uuid;
begin
 hf:=crm_f2.admit(f2p,f2s,q,'C01','read_evidence');tf:=crm_f1.verify_envelope(f1p,f1s,q,'C01','evidence','read_evidence');if hf[17] collate "C"<>tf[14] collate "C" then raise exception 'ALLOCATION_DENIED';end if;
 fs:=crm_f1.fields(q);if cardinality(fs)<>2 or fs[1]<>'CRM-H3-ALLOCATION-READ1' then raise exception 'ALLOCATION_INPUT_INVALID';end if;a:=fs[2]::jsonb;
 if jsonb_typeof(a) is distinct from 'object' or a-'paymentId'<>'{}'::jsonb or not(a?'paymentId') then raise exception 'ALLOCATION_INPUT_INVALID';end if;pid:=(a->>'paymentId')::uuid;s:=hf[17];
 select revision into pr from crm_private.b05_payment_revisions where payment_id=pid and admin_scope=s order by revision desc limit 1;
 if found then
  select coalesce(max(revision),0) into rev from crm_private.b05_fund_revisions where payment_id=pid and admin_scope=s;
  for sid in select distinct schedule_id from crm_private.b05_reconciliations where payment_id=pid and admin_scope=s order by schedule_id loop coverage:=coverage||crm_private.fund_coverage(sid,s);end loop;
  r:=jsonb_build_object('revision',rev,'paymentRevision',pr,'summary',crm_private.fund_summary(pid,s),'allocations',crm_private.fund_allocations(pid,s),
   'acts',coalesce((select jsonb_agg(to_jsonb(z)||jsonb_build_object('signed_amount',trunc(z.signed_amount,2)::text,'start_amount',trunc(z.start_amount,2)::text) order by recorded_at,act_id) from crm_private.b05_allocation_acts z where z.payment_id=pid and z.admin_scope=s),'[]'),
   'coverage',coverage,'history',coalesce((select jsonb_agg(to_jsonb(z) order by recorded_at) from crm_private.b05_fund_history z where z.payment_id=pid and z.admin_scope=s),'[]'),
   'distributions',coalesce((select jsonb_agg(to_jsonb(z) order by recorded_at) from crm_private.b05_fund_distributions z where z.payment_id=pid and z.admin_scope=s),'[]'));
 end if;
 perform crm_f2.verify(f2p,f2s,q,'C01','human_evidence','read_evidence');perform crm_f1.verify_envelope(f1p,f1s,q,'C01','evidence','read_evidence');return r;
end$function$

CREATE OR REPLACE FUNCTION crm_api.apply_probe_batch(p bytea, s bytea, q bytea)
 RETURNS text[]
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare f text[]; qf text[]; i integer; result text[] := '{}';
begin
  f := crm_f1.verify(p,s,q,'C03'); qf := crm_f1.fields(q);
  insert into crm_f1.consumption values (f[5],f[6]::oid,f[8]::xid8,f[21],f[20]::bigint);
  perform set_config('crm.f1_payload',encode(p,'hex'),true),
    set_config('crm.f1_mac',encode(s,'hex'),true),set_config('crm.f1_input',encode(q,'hex'),true);
  i := 6;
  while i <= cardinality(qf) loop
    insert into crm_private.access_probe (probe_id,context_scope,public_value)
      values (qf[i+1],f[14],qf[i+2]);
    result := array_append(result,qf[i+1]); i := i+3;
  end loop;
  perform crm_f1.verify(p,s,q,'C03');
  perform set_config('crm.f1_payload','',true),set_config('crm.f1_mac','',true),set_config('crm.f1_input','',true);
  return result;
exception when others then raise exception 'F1_DENIED' using errcode='42501';
end $function$

CREATE OR REPLACE FUNCTION crm_api.availability_apply(f2p bytea, f2s bytea, f1p bytea, f1s bytea, q bytea, tf2p bytea, tf2s bytea, tf1p bytea, tf1s bytea, tq bytea)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare hf text[];tf text[];fs text[];a jsonb;op uuid;iid uuid;bid uuid;actor uuid;s text;action text;fp text;proofhash text;rev bigint;at_time timestamptz;
 prev crm_private.b04_availability_operations;root crm_private.b04_availability;old jsonb;state jsonb;r jsonb;data jsonb;response jsonb;record crm_private.b07_records;task jsonb;follow boolean:=false;task_id uuid;
begin
 hf:=crm_f2.admit(f2p,f2s,q,'C03','write_evidence');tf:=crm_f1.verify_envelope(f1p,f1s,q,'C03','evidence','write_evidence');
 if hf[17] collate "C" is distinct from tf[14] collate "C" then raise exception 'AVAILABILITY_DENIED';end if;
 fs:=crm_f1.fields(q);if cardinality(fs)<>2 or fs[1]<>'CRM-H4-AVAILABILITY1' then raise exception 'AVAILABILITY_INPUT_INVALID';end if;a:=fs[2]::jsonb;
 if jsonb_typeof(a) is distinct from 'object' or not(a ?& array['action','operationId','availabilityId','bookingId','expectedRevision','sourceRef','reason','at','evidenceId','data'])
 or a-array['action','operationId','availabilityId','bookingId','expectedRevision','sourceRef','reason','at','evidenceId','data','origin']<>'{}'::jsonb
 or exists(select 1 from unnest(array['action','operationId','availabilityId','bookingId','sourceRef','reason','evidenceId']) k where not coalesce(crm_private.invoice_text(a->k),false))
 or not coalesce(crm_private.availability_time(a->'at'),false) or jsonb_typeof(a->'data') is distinct from 'object'
 or coalesce(a->>'expectedRevision','') !~ '^(0|[1-9][0-9]*)$' or coalesce(a->>'origin','manual')<>'manual' then raise exception 'AVAILABILITY_INPUT_INVALID';end if;
 op:=(a->>'operationId')::uuid;iid:=(a->>'availabilityId')::uuid;bid:=(a->>'bookingId')::uuid;actor:=hf[12]::uuid;s:=hf[17];action:=a->>'action';data:=a->'data';at_time:=(a->>'at')::timestamptz;
 if action not in ('query','receive','verify','review') then raise exception 'AVAILABILITY_INPUT_INVALID';end if;
 if not exists(select 1 from crm_private.b04_bookings where booking_id=bid and admin_scope=s) then raise exception 'AVAILABILITY_DENIED';end if;
 perform pg_advisory_xact_lock(hashtextextended('availability-booking:'||bid,0));
 -- H2 parent is an immutable revision-1 baseline; advisory unit and version check protect its use.
 select * into root from crm_private.b04_availability where availability_id=iid;
 if root.availability_id is not null and (root.booking_id<>bid or root.admin_scope<>s) then raise exception 'AVAILABILITY_DENIED';end if;
 fp:=encode(crm_crypto.digest(convert_to(a::text,'UTF8'),'sha256'),'hex');perform pg_advisory_xact_lock(hashtextextended('availability-op:'||op,0));
 select * into prev from crm_private.b04_availability_operations where operation_id=op;
 if found then
  if prev.admin_scope<>s or prev.actor_id<>actor or prev.fingerprint<>fp then raise exception 'AVAILABILITY_REPLAY_CONFLICT:E2';end if;r:=prev.result||jsonb_build_object('replayed',true);
 else
  proofhash:=encode(crm_crypto.digest(convert_to((a-array['operationId','evidenceId'])::text,'UTF8'),'sha256'),'hex');
  if not crm_private.payment_evidence((a->>'evidenceId')::uuid,iid,s,'availability:'||action||':'||proofhash,at_time,true)
  or not exists(select 1 from crm_private.b07_records where record_id=(a->>'evidenceId')::uuid and recorded_by=actor) then raise exception 'AVAILABILITY_EVIDENCE_REQUIRED:E3';end if;
  if root.availability_id is not null then select revision,after_data into rev,old from crm_private.b04_availability_revisions where availability_id=iid order by revision desc limit 1;end if;
  -- Identity of the fact is the stable root/query or explicit response factId, never similar text.
  if action='receive' and exists(select 1 from crm_private.b04_availability_revisions where admin_scope=s and event->'data'->>'factId'=data->>'factId' and (availability_id<>iid or event->'data' is distinct from data)) then raise exception 'AVAILABILITY_FACT_CONFLICT:E2';end if;
  if (action='query' and old->'query'=data) or (action='receive' and exists(select 1 from crm_private.b04_availability_revisions where availability_id=iid and admin_scope=s and action_kind='receive' and event->'data'=data)) then state:=old;
  else
   if coalesce(rev,0)<>(a->>'expectedRevision')::bigint then raise exception 'AVAILABILITY_REVISION_CONFLICT:E2';end if;
   state:=coalesce(old,jsonb_build_object('id',iid,'bookingId',bid,'query',null,'response',null,'confirmed',null,'review',null));
   if action in ('query','receive') then
    if not coalesce(crm_private.availability_coverage(data->'coverage',bid,s),false) or not coalesce(crm_private.availability_source(data->'source',bid,(data->'coverage'->>'serviceId')::uuid,s),false)
    or not coalesce(crm_private.availability_time(data->'happenedAt'),false) or not coalesce(crm_private.invoice_text(data->'content'),false) then raise exception 'AVAILABILITY_FACT_REQUIRED:E3';end if;
    -- Service baseline is immutable; no UPDATE grant is introduced to lock it.
    if old is not null and (data->'coverage'->'serviceId' is distinct from coalesce(old->'query'->'coverage'->'serviceId',old->'response'->'coverage'->'serviceId')
    or data->'coverage'->'nightId' is distinct from coalesce(old->'query'->'coverage'->'nightId',old->'response'->'coverage'->'nightId')
    or data->'coverage'->'purpose' is distinct from coalesce(old->'query'->'coverage'->'purpose',old->'response'->'coverage'->'purpose')
    or data->'source' is distinct from coalesce(old->'query'->'source',old->'response'->'source')) then raise exception 'AVAILABILITY_SCOPE_CONFLICT:E2';end if;
    if action='query' then
     if old is not null or data-array['coverage','source','happenedAt','content']<>'{}'::jsonb then raise exception 'AVAILABILITY_QUERY_REQUIRED:E3';end if;
     state:=state||jsonb_build_object('query',data,'status','Consulta registrada','serviceAvailabilityState','Disponibilidad consultada');follow:=true;
    else
     if data-array['coverage','source','happenedAt','content','factId','recordId','certainty','conditions','validUntil']<>'{}'::jsonb
     or not(data ?& array['factId','recordId','certainty','conditions','validUntil']) or coalesce(data->>'certainty' not in ('communicated','negative','uncertain'),true)
     or not coalesce(crm_private.invoice_text(data->'conditions'),false) or not coalesce(crm_private.invoice_text(data->'factId'),false)
     or (data->'validUntil'<>'null'::jsonb and not coalesce(crm_private.availability_time(data->'validUntil'),false)) then raise exception 'AVAILABILITY_RESPONSE_REQUIRED:E3';end if;
     perform (data->>'factId')::uuid;
     select * into record from crm_private.b07_records where record_id=(data->>'recordId')::uuid and admin_scope=s;
     if record.record_id is null or not exists(select 1 from crm_private.b07_links where record_id=record.record_id and admin_scope=s and context_kind='booking' and context_id=bid) then raise exception 'AVAILABILITY_DENIED';end if;
     if exists(select 1 from crm_private.b04_availability_revisions where admin_scope=s and event->'data'->>'factId'=data->>'factId' and event->'data' is distinct from data) then raise exception 'AVAILABILITY_FACT_CONFLICT:E2';end if;
     state:=state||jsonb_build_object('response',data,'status',case data->>'certainty' when 'communicated' then 'Disponibilidad comunicada' when 'negative' then 'Negativa' else 'Incierta' end);
     if old->'confirmed'<>'null'::jsonb then state:=state||jsonb_build_object('review',jsonb_build_object('cause','Nueva comunicación pendiente de contraste','before',old->'confirmed','after',data,'dependencies',jsonb_build_array(data->'coverage'),'evidenceId',a->'evidenceId','result','pending'),'status','Pendiente de revalidación');follow:=true;end if;
     if data->>'certainty'<>'communicated' then follow:=true;state:=state||jsonb_build_object('review',jsonb_build_object('cause',data->>'content','before',old->'confirmed','after',data,'dependencies',jsonb_build_array(data->'coverage'),'evidenceId',a->'evidenceId','result','pending'));end if;
    end if;
   elsif action='verify' then
    response:=old->'response';
    if response is null or response='null'::jsonb or response->>'certainty'<>'communicated' or data-array['coverage','source','actionAt','actionUntil','authority','unequivocal','checks','precedence','basis','resolvedAspects']<>'{}'::jsonb
    or not(data ?& array['coverage','source','actionAt','actionUntil','authority','unequivocal','checks','precedence','basis','resolvedAspects'])
    or data->'coverage' is distinct from response->'coverage' or data->'source' is distinct from response->'source'
    or not coalesce(crm_private.availability_coverage(data->'coverage',bid,s),false) or not coalesce(crm_private.availability_source(data->'source',bid,(data->'coverage'->>'serviceId')::uuid,s),false)
    or data->'authority' is distinct from 'true'::jsonb or data->'unequivocal' is distinct from 'true'::jsonb
    or data->'checks' is distinct from '{"dates":true,"quantity":true,"unit":true,"variant":true,"conditions":true,"capacity":true,"validity":true}'::jsonb
    or not coalesce(crm_private.availability_time(data->'actionAt'),false) or not coalesce(crm_private.availability_time(data->'actionUntil'),false)
    or not coalesce(crm_private.invoice_text(data->'basis'),false) or jsonb_typeof(data->'resolvedAspects') is distinct from 'array'
    then raise exception 'AVAILABILITY_VERIFICATION_REQUIRED:E3';end if;
    if (response->>'happenedAt')::timestamptz>at_time or (response->>'happenedAt')::timestamptz>(data->>'actionAt')::timestamptz or at_time>(data->>'actionAt')::timestamptz then raise exception 'AVAILABILITY_CHRONOLOGY_REQUIRED:E3';end if;
    if (data->>'actionUntil')::timestamptz<(data->>'actionAt')::timestamptz or (response->'validUntil'<>'null'::jsonb and (data->>'actionUntil')::timestamptz>=(response->>'validUntil')::timestamptz) then raise exception 'AVAILABILITY_EXPIRED:E3';end if;
    if old->'confirmed'<>'null'::jsonb and not (
      data->>'precedence'='verified-newer' and (response->>'happenedAt')::timestamptz>(old->'confirmed'->'response'->>'happenedAt')::timestamptz
      or data->>'precedence'='ratified' and response=old->'confirmed'->'response' and a->'evidenceId' is distinct from old->'confirmed'->'evidenceId' and at_time>=(old->'confirmed'->>'at')::timestamptz
    ) then raise exception 'AVAILABILITY_DISCREPANCY:E8';end if;
    if old->'review'<>'null'::jsonb and not(data->'resolvedAspects' @> coalesce(old->'review'->'aspects','["dates","quantity","unit","variant","conditions","capacity","validity"]')) then raise exception 'AVAILABILITY_REVIEW_INCOMPLETE:E3';end if;
    state:=state||jsonb_build_object('status','Disponibilidad confirmada','confirmed',jsonb_build_object('response',response,'verification',data,'evidenceId',a->'evidenceId','actorId',actor,'at',at_time),'review',null);
   else
    if old is null or data-array['cause','before','after','dependencies','aspects','result']<>'{}'::jsonb or not(data ?& array['cause','before','after','dependencies','aspects','result'])
    or not coalesce(crm_private.invoice_text(data->'cause'),false) or jsonb_typeof(data->'dependencies') is distinct from 'array' or jsonb_array_length(data->'dependencies')=0
    or data->'before' is distinct from old->'confirmed' or jsonb_typeof(data->'aspects') is distinct from 'array' or jsonb_array_length(data->'aspects')=0
    or coalesce(data->>'result' not in ('pending','rejected','uncertain'),true) then raise exception 'AVAILABILITY_REVIEW_REQUIRED:E3';end if;
    if exists(select 1 from jsonb_array_elements(data->'dependencies') d where d is distinct from coalesce(old->'response'->'coverage',old->'query'->'coverage'))
    or exists(select 1 from jsonb_array_elements_text(data->'aspects') k where k not in ('dates','quantity','unit','variant','conditions','capacity','validity'))
    or jsonb_typeof(data->'after') is distinct from 'object' or (data->'after')-array['dates','quantity','unitRevisionId','variant','conditions','capacity','source','validUntil','schedule']<>'{}'::jsonb then raise exception 'AVAILABILITY_REVIEW_SCOPE_REQUIRED:E3';end if;
    state:=state||jsonb_build_object('status','Pendiente de revalidación','review',data||jsonb_build_object('evidenceId',a->'evidenceId','actorId',actor,'at',at_time));follow:=true;
   end if;
   rev:=coalesce(rev,0)+1;state:=state||jsonb_build_object('revision',rev);
  end if;
  r:=jsonb_build_object('id',iid,'replayed',false,'result',state);
  if root.availability_id is null then insert into crm_private.b04_availability values(iid,bid,s,op);end if;
  if old is distinct from state then insert into crm_private.b04_availability_revisions values(iid,rev,s,op,action,a,old,state,actor,(a->>'evidenceId')::uuid,a->>'sourceRef',a->>'reason',at_time,clock_timestamp());end if;
  if follow then
   fs:=crm_f1.fields(tq);task:=fs[2]::jsonb;
   if fs[1]<>'CRM-H1-TASK-1' or task->>'taskId'<>iid::text or task->>'operationId'<>op::text or task->'identity' is distinct from jsonb_build_object('causeKind','availability','causeId',iid,'contextKind','booking','contextId',bid,'scopeRef',iid,'effect','availability-review')
   or task->'material' is distinct from '{"title":"Revisar disponibilidad del alcance","deadline":{"kind":"unknown","reason":"No consta plazo informado para el seguimiento"},"priority":{"kind":"pending","reason":"Prioridad no configurada"},"sourceRef":"SM-AV-04","sourceVersion":"1","triggerRef":"BR-TASK-005","triggerVersion":"1"}'::jsonb then raise exception 'AVAILABILITY_TASK_REQUIRED';end if;
   select result_ref into task_id from crm_api.b07_task_apply(tf2p,tf2s,tf1p,tf1s,tq);
  end if;
  insert into crm_private.b04_availability_operations values(op,iid,s,actor,fp,r,rev,clock_timestamp());
 end if;
 perform crm_f2.verify(f2p,f2s,q,'C03','human_evidence','write_evidence');perform crm_f1.verify_envelope(f1p,f1s,q,'C03','evidence','write_evidence');return r;
end$function$

CREATE OR REPLACE FUNCTION crm_api.availability_read(f2p bytea, f2s bytea, f1p bytea, f1s bytea, q bytea)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare hf text[];tf text[];fs text[];a jsonb;s text;bid uuid;iid uuid;r jsonb;items jsonb;usable boolean;v jsonb;begin
 hf:=crm_f2.admit(f2p,f2s,q,'C01','read_evidence');tf:=crm_f1.verify_envelope(f1p,f1s,q,'C01','evidence','read_evidence');
 if hf[17] collate "C" is distinct from tf[14] collate "C" then raise exception 'AVAILABILITY_DENIED';end if;
 fs:=crm_f1.fields(q);if cardinality(fs)<>2 or fs[1]<>'CRM-H4-AVAILABILITY-READ1' then raise exception 'AVAILABILITY_INPUT_INVALID';end if;a:=fs[2]::jsonb;s:=hf[17];bid:=(a->>'bookingId')::uuid;
 if not exists(select 1 from crm_private.b04_bookings where booking_id=bid and admin_scope=s) then r:=null;
 elsif a?'availabilityId' then
  if a-array['availabilityId','bookingId']<>'{}'::jsonb then raise exception 'AVAILABILITY_INPUT_INVALID';end if;
  select availability_id into iid from crm_private.b04_availability where availability_id=(a->>'availabilityId')::uuid and booking_id=bid and admin_scope=s;
  select after_data into r from crm_private.b04_availability_revisions where availability_id=iid and admin_scope=s order by revision desc limit 1;
  if r is not null then r:=r||jsonb_build_object('history',(select jsonb_agg(jsonb_build_object('revision',revision,'action',action_kind,'before',before_data,'after',after_data,'actorId',actor_id,'sourceRef',source_ref,'reason',reason,'evidenceId',evidence_id,'at',occurred_at,'recordedAt',recorded_at) order by revision) from crm_private.b04_availability_revisions where availability_id=iid and admin_scope=s));end if;
 else
  if a-array['bookingId','coverage','source','actionAt','actionUntil']<>'{}'::jsonb or (not coalesce(crm_private.availability_coverage(a->'coverage',bid,s),false) and not exists(select 1 from crm_private.b04_availability av join crm_private.b04_availability_revisions rv using(availability_id) where av.booking_id=bid and av.admin_scope=s and (rv.after_data->'confirmed'->'response'->'coverage'=a->'coverage' or rv.after_data->'response'->'coverage'=a->'coverage')))
  or not coalesce(crm_private.availability_time(a->'actionAt'),false) or not coalesce(crm_private.availability_time(a->'actionUntil'),false) then raise exception 'AVAILABILITY_INPUT_INVALID';end if;
  select coalesce(jsonb_agg(jsonb_build_object('id',i.availability_id,'revision',v.after_data->'revision','status',v.after_data->'status','confirmed',case when v.after_data->'confirmed'='null'::jsonb then 'null'::jsonb else jsonb_build_object('response',(v.after_data->'confirmed'->'response')-array['content','factId','recordId','certainty'],'verification',jsonb_build_object('actionAt',v.after_data->'confirmed'->'verification'->'actionAt','actionUntil',v.after_data->'confirmed'->'verification'->'actionUntil')) end,'pending',v.after_data->'review'<>'null'::jsonb)),'[]') into items
  from crm_private.b04_availability i cross join lateral (select after_data from crm_private.b04_availability_revisions where availability_id=i.availability_id order by revision desc limit 1) v
  where i.booking_id=bid and i.admin_scope=s and coalesce(v.after_data->'response'->'coverage',v.after_data->'query'->'coverage')->>'serviceId'=a->'coverage'->>'serviceId'
  and coalesce(v.after_data->'response'->'coverage',v.after_data->'query'->'coverage')->'nightId'=a->'coverage'->'nightId'
  and coalesce(v.after_data->'response'->'coverage',v.after_data->'query'->'coverage')->'purpose'=a->'coverage'->'purpose'
  and coalesce(v.after_data->'response'->'source',v.after_data->'query'->'source')=a->'source'
  and (v.after_data->'response'->'coverage'=a->'coverage' or v.after_data->'confirmed'->'response'->'coverage'=a->'coverage' or v.after_data->'query'->'coverage'=a->'coverage');
  usable:=false;
  for v in select value from jsonb_array_elements(items) loop
   if v->>'status'='Disponibilidad confirmada' and v->'confirmed'->'response'->'coverage'=a->'coverage' and v->'confirmed'->'response'->'source'=a->'source'
   and v->'confirmed'->'verification'->'actionAt'=a->'actionAt' and v->'confirmed'->'verification'->'actionUntil'=a->'actionUntil'
   and (v->'confirmed'->'response'->'validUntil'='null'::jsonb or (a->>'actionUntil')::timestamptz<(v->'confirmed'->'response'->>'validUntil')::timestamptz) then usable:=true;end if;
  end loop;
  if exists(select 1 from jsonb_array_elements(items) e where e->'pending'='true'::jsonb) then usable:=false;end if;
  -- Multiple independent roots with differing verified external facts cannot choose precedence by arrival.
  if (select count(distinct (e->'confirmed'->'response')-'happenedAt') from jsonb_array_elements(items) e where e->'confirmed'<>'null'::jsonb and e->'confirmed'->'response'->'coverage'=a->'coverage')>1 then usable:=false;end if;
