 end if;
 perform crm_f2.verify(f2p,f2s,q,'C01','human_evidence','read_evidence');perform crm_f1.verify_envelope(f1p,f1s,q,'C01','evidence','read_evidence');return r;
end$function$

CREATE OR REPLACE FUNCTION crm_api.b03_apply(f2p bytea, f2s bytea, f1p bytea, f1s bytea, q bytea, cf2p bytea, cf2s bytea, cf1p bytea, cf1s bytea, cq bytea)
 RETURNS TABLE(result_ref uuid, replayed boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare hf text[];tf text[];v text[];cv text[];m jsonb;a jsonb;e jsonb;d jsonb;
 actor uuid;scope text;target uuid;opid uuid;lead uuid;action text;fingerprint text;prior jsonb;after_data jsonb;
 old crm_private.b03_opportunities%rowtype;op crm_private.b03_operations%rowtype;l crm_private.b03_leads%rowtype;ref text;ik text;
begin
 hf:=crm_f2.admit(f2p,f2s,q,'C03','write_evidence');tf:=crm_f1.verify_envelope(f1p,f1s,q,'C03','evidence','write_evidence');
 if hf[17] collate "C"<>tf[14] collate "C" then raise exception 'COMMERCIAL_DENIED' using errcode='42501';end if;
 v:=crm_f1.fields(q);if cardinality(v)<>2 or v[1]<>'CRM-H2-COM-1' then raise exception 'COMMERCIAL_INPUT_INVALID';end if;
 m:=v[2]::jsonb;a:=m->'material';e:=m->'event';actor:=hf[12]::uuid;scope:=hf[17];
 action:=m->>'action';target:=(m->>'targetId')::uuid;opid:=(m->>'operationId')::uuid;lead:=nullif(m->>'leadId','')::uuid;
 if m-array['action','targetId','operationId','leadId','expectedRevision','sourceRef','reason','material','event']<>'{}'::jsonb
  or jsonb_typeof(m->'sourceRef') is distinct from 'string' or jsonb_typeof(m->'reason') is distinct from 'string'
  or nullif(btrim(m->>'sourceRef'),'') is null or nullif(btrim(m->>'reason'),'') is null or coalesce(m->>'expectedRevision','') !~ '^(0|[1-9][0-9]*)$'
  or action is null or action not in ('lead','direct','convert','progress') then raise exception 'COMMERCIAL_INPUT_INVALID';end if;
 fingerprint:=encode(crm_crypto.digest(convert_to(m::text,'UTF8'),'sha256'),'hex');
 perform pg_advisory_xact_lock(hashtextextended(opid::text,0));
 select * into op from crm_private.b03_operations where operation_id=opid;
 if found then
  if op.admin_scope<>scope or op.actor_id<>actor or op.fingerprint<>fingerprint then raise exception 'COMMERCIAL_REPLAY_CONFLICT';end if;
  result_ref:=op.result_ref;replayed:=true;
 else
  perform pg_advisory_xact_lock(hashtextextended(coalesce(lead,target)::text,31));
  if action in ('lead','direct','convert') then
   if e is not null then raise exception 'COMMERCIAL_INPUT_INVALID';end if;
   if jsonb_typeof(a) is distinct from 'object' or a-array['contact','need','commercialPossible','pending','dates','participants','services','budget','contactId','organizationId','groupId']<>'{}'::jsonb
    or not(a ?& array['contact','need','commercialPossible','pending']) or jsonb_typeof(a->'pending') is distinct from 'array'
    or (a->'need'<>'null'::jsonb and (jsonb_typeof(a->'need')<>'string' or nullif(btrim(a->>'need'),'') is null))
    or a->'commercialPossible' not in ('null'::jsonb,'true'::jsonb,'false'::jsonb) then raise exception 'COMMERCIAL_INPUT_INVALID';end if;
   if a->'contact'<>'null'::jsonb and (jsonb_typeof(a->'contact')<>'object' or (a->'contact')-array['channel','address','sourceRef','valid']<>'{}'::jsonb
    or jsonb_typeof(a->'contact'->'channel') is distinct from 'string' or jsonb_typeof(a->'contact'->'address') is distinct from 'string'
    or jsonb_typeof(a->'contact'->'sourceRef') is distinct from 'string'
    or not((a->'contact') ?& array['channel','address','sourceRef','valid']) or a->'contact'->'valid' not in ('true'::jsonb,'false'::jsonb)
    or nullif(btrim(a->'contact'->>'channel'),'') is null or nullif(btrim(a->'contact'->>'address'),'') is null
    or nullif(btrim(a->'contact'->>'sourceRef'),'') is null) then raise exception 'COMMERCIAL_INPUT_INVALID';end if;
   if exists(select 1 from jsonb_array_elements(a->'pending') x where jsonb_typeof(x)<>'string' or btrim(x#>>'{}')='') then raise exception 'COMMERCIAL_INPUT_INVALID';end if;
   foreach ik in array array['contact','organization','group'] loop
    ref:=a->>(ik||'Id');if ref is not null and not exists(select 1 from crm_private.identity_entities i
     where i.identity_id=ref::uuid and i.identity_kind=ik and i.admin_scope=scope and i.archived_at is null and i.merged_into_id is null
      and (ik<>'group' or i.context_id=target)) then raise exception 'COMMERCIAL_IDENTITY_INVALID';end if;
   end loop;
   if action='lead' then
    if lead is not null or (m->>'expectedRevision')::bigint<>0 then raise exception 'COMMERCIAL_INPUT_INVALID';end if;
    insert into crm_private.b03_leads(lead_id,admin_scope,source_ref,responsible_actor,material) values(target,scope,m->>'sourceRef',actor,a);
    select to_jsonb(t) into after_data from crm_private.b03_leads t where lead_id=target;d:=jsonb_build_object('id','BR-LEAD-001');
   else
    if a->'contact'->'valid' is distinct from 'true'::jsonb or nullif(btrim(a->>'need'),'') is null or a->'commercialPossible' is distinct from 'true'::jsonb then raise exception 'COMMERCIAL_MINIMUM_REQUIRED:SM-OP-01';end if;
    if (m->>'expectedRevision')::bigint<>0 then raise exception 'COMMERCIAL_REVISION_CONFLICT';end if;
    if action='convert' then
     select * into l from crm_private.b03_leads where lead_id=lead and admin_scope=scope;
     if not found then raise exception 'COMMERCIAL_LEAD_REQUIRED';end if;
     select * into old from crm_private.b03_opportunities where lead_id=lead;
     if found then
      if old.admin_scope<>scope or old.creation_material<>a or old.source_ref<>l.source_ref then raise exception 'COMMERCIAL_CONVERSION_CONFLICT';end if;
      target:=old.opportunity_id;result_ref:=target;replayed:=true;
     end if;
    elsif lead is not null then raise exception 'COMMERCIAL_INPUT_INVALID';end if;
    if old.opportunity_id is null then
     if exists(select 1 from crm_private.identity_contexts where context_id=target) then
      if not exists(select 1 from crm_private.identity_contexts where context_id=target and context_kind='opportunity' and admin_scope=scope and verified) then raise exception 'COMMERCIAL_CONTEXT_INVALID';end if;
     else
      insert into crm_private.identity_contexts(context_id,context_kind,admin_scope,source_ref,evidence_ref,verified)
       values(target,'opportunity',scope,coalesce(l.source_ref,m->>'sourceRef'),m->>'sourceRef',true);
     end if;
     insert into crm_private.b03_opportunities(opportunity_id,lead_id,admin_scope,source_ref,responsible_actor,material,creation_material,state,revision)
      values(target,lead,scope,coalesce(l.source_ref,m->>'sourceRef'),coalesce(l.responsible_actor,actor),a,a,'Nueva',1);
     -- Reuse the actual H1 API, allocator, counter, D040 and immutable registry.
     cv:=crm_f1.fields(cq);
     if cv is distinct from array['CRM-H1-RESOLVE1','assign_code',target::text,target::text,'','OP',m->>'sourceRef',m->>'sourceRef',m->>'reason','0'] then raise exception 'COMMERCIAL_CODE_CONTRACT_INVALID';end if;
     if not exists(select 1 from crm_private.identity_codes c where c.code_kind='OP' and c.target_id=target and c.admin_scope=scope) then
      perform crm_api.identity_resolve(cf2p,cf2s,cf1p,cf1s,cq);end if;
     select to_jsonb(t) into after_data from crm_private.b03_opportunities t where opportunity_id=target;
     d:=jsonb_build_object('id','SM-OP-01');
    end if;
   end if;
  else
   select * into old from crm_private.b03_opportunities where opportunity_id=target and admin_scope=scope for update;
   if not found then raise exception 'COMMERCIAL_DENIED';end if;
   if old.revision<>(m->>'expectedRevision')::bigint then raise exception 'COMMERCIAL_REVISION_CONFLICT';end if;
   if a is not null or lead is not null or jsonb_typeof(e) is distinct from 'object' then raise exception 'COMMERCIAL_INPUT_INVALID';end if;
   d:=crm_private.b03_decide(old.state,e);
   if d->>'allowed' is distinct from 'true' then raise exception 'COMMERCIAL_BLOCKED:%:%',d->>'id',d->>'blocker';end if;
   if e->>'type'='contact' then
    if not exists(select 1 from crm_private.b07_records r join crm_private.b07_links b using(record_id)
     where r.record_id=(e->>'communicationId')::uuid and r.admin_scope=scope and b.admin_scope=scope
     and b.context_kind='opportunity' and b.context_id=target and r.record_kind='communication'
     and nullif(r.material->>'channel','') is not null and nullif(r.material->>'recipient_ref','') is not null
     and r.material->>'direction' in ('incoming','outgoing')) then raise exception 'COMMERCIAL_CONTACT_EVIDENCE_REQUIRED';end if;
   end if;
   if e->>'type' in ('contact','negotiate') then
    ref:=case when e->>'type'='contact' then e->>'evidenceId' else e->>'exchangeRef' end;
    if not exists(select 1 from crm_private.b07_records r join crm_private.b07_links b using(record_id)
     where r.record_id=ref::uuid and r.admin_scope=scope and b.admin_scope=scope and b.context_kind='opportunity' and b.context_id=target
     and ((r.record_kind='evidence' and r.material->>'certainty'='reviewed') or (r.record_kind='communication' and r.material->>'direction'='incoming'))) then
     raise exception 'COMMERCIAL_ACTUAL_EVIDENCE_REQUIRED';end if;
   end if;
   prior:=to_jsonb(old);
   if e->>'type'='define_need' or e->>'destination'='Necesidad definida' then
    a:=case when e->>'type'='define_need' then e else e->'support' end;
    update crm_private.b03_opportunities set material=jsonb_set(jsonb_set(material,'{need}',a->'need'),'{pending}',a->'pending') where opportunity_id=target;
   end if;
   update crm_private.b03_opportunities set state=d->>'destination',revision=revision+1,updated_at=clock_timestamp(),
    previous_state=case when e->>'type'='pause' then old.state else previous_state end,
    loss_reason=case when e->>'type'='lose' then e->>'lossReason' else loss_reason end where opportunity_id=target;
   select to_jsonb(t) into after_data from crm_private.b03_opportunities t where opportunity_id=target;
  end if;
  insert into crm_private.b03_operations(operation_id,admin_scope,actor_id,fingerprint,result_ref) values(opid,scope,actor,fingerprint,target);
  if after_data is not null then
   insert into crm_private.b03_history(history_id,subject_id,admin_scope,before_state,after_state,event,normative_ids,reason,source_ref,actor_id,occurred_at)
    values(opid,target,scope,prior,after_data,coalesce(e,jsonb_build_object('type',action,'leadId',lead)),jsonb_build_array(d->>'id'),m->>'reason',m->>'sourceRef',actor,(e->>'occurredAt')::timestamptz);
  end if;
  result_ref:=target;replayed:=coalesce(replayed,false);
 end if;
 perform crm_f2.verify(f2p,f2s,q,'C03','human_evidence','write_evidence');
 perform crm_f1.verify_envelope(f1p,f1s,q,'C03','evidence','write_evidence');return next;
end $function$

CREATE OR REPLACE FUNCTION crm_api.b03_read(f2p bytea, f2s bytea, f1p bytea, f1s bytea, q bytea)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare hf text[];tf text[];v text[];m jsonb;data jsonb;
begin
 hf:=crm_f2.admit(f2p,f2s,q,'C01','read_evidence');tf:=crm_f1.verify_envelope(f1p,f1s,q,'C01','evidence','read_evidence');
 if hf[17] collate "C"<>tf[14] collate "C" then raise exception 'COMMERCIAL_DENIED';end if;
 v:=crm_f1.fields(q);if cardinality(v)<>2 or v[1]<>'CRM-H2-COM-READ1' then raise exception 'COMMERCIAL_INPUT_INVALID';end if;m:=v[2]::jsonb;
 if m->>'kind'='lead' then select to_jsonb(t) into data from crm_private.b03_leads t where lead_id=(m->>'targetId')::uuid and admin_scope=hf[17];
 elsif m->>'kind'='opportunity' then select to_jsonb(t)||jsonb_build_object('human_code',c.human_code) into data
  from crm_private.b03_opportunities t join crm_private.identity_codes c on c.target_id=t.opportunity_id and c.code_kind='OP' and c.admin_scope=t.admin_scope where opportunity_id=(m->>'targetId')::uuid and t.admin_scope=hf[17];
 elsif m->>'kind'='history' then select coalesce(jsonb_agg(to_jsonb(t) order by recorded_at,history_id),'[]'::jsonb) into data from crm_private.b03_history t where subject_id=(m->>'targetId')::uuid and admin_scope=hf[17];
 else raise exception 'COMMERCIAL_INPUT_INVALID';end if;
 perform crm_f2.verify(f2p,f2s,q,'C01','human_evidence','read_evidence');perform crm_f1.verify_envelope(f1p,f1s,q,'C01','evidence','read_evidence');return data;
end $function$

CREATE OR REPLACE FUNCTION crm_api.b07_alert_apply(f2p bytea, f2s bytea, f1p bytea, f1s bytea, q bytea)
 RETURNS TABLE(result_ref uuid, replayed boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare hf text[];tf text[];v text[];m jsonb;i jsonb;a jsonb;au jsonb;missing jsonb;
 actor uuid;scope text;opid uuid;target uuid;action text;fingerprint text;causekey text;
 prior crm_private.b07_operations%rowtype;old crm_private.b07_alerts%rowtype;
 n crm_private.b07_notifications%rowtype;pa crm_private.b07_notification_attempts%rowtype;
 before_data jsonb;after_data jsonb;k text;attempt_fingerprint text;changed boolean:=true;
begin
 hf:=crm_f2.admit(f2p,f2s,q,'C03','write_evidence');
 tf:=crm_f1.verify_envelope(f1p,f1s,q,'C03','evidence','write_evidence');
 if hf[17] collate "C"<>tf[14] collate "C" then raise exception 'ALERT_DENIED' using errcode='42501'; end if;
 v:=crm_f1.fields(q);
 if cardinality(v)<>2 or v[1]<>'CRM-H5-ALERT-1' then raise exception 'ALERT_INPUT_INVALID'; end if;
 m:=v[2]::jsonb;actor:=hf[12]::uuid;scope:=hf[17];action:=m->>'action';
 if jsonb_typeof(m) is distinct from 'object' or m->>'purpose' is distinct from 'internal-alert'
  or action is null or action not in ('receive','stop','review','record_synthetic_result')
  or nullif(btrim(m->>'reason'),'') is null or m->>'operationId' is null or m->>'alertId' is null then
  raise exception 'ALERT_INPUT_INVALID'; end if;
 opid:=(m->>'operationId')::uuid;target:=(m->>'alertId')::uuid;
 fingerprint:=encode(crm_crypto.digest(convert_to(m::text,'UTF8'),'sha256'),'hex');
 perform pg_advisory_xact_lock(hashtextextended(opid::text,0));
 select * into prior from crm_private.b07_operations where operation_id=opid;
 if found then
  if prior.admin_scope<>scope or prior.actor_id<>actor or prior.fingerprint<>fingerprint then raise exception 'ALERT_REPLAY_CONFLICT'; end if;
  result_ref:=prior.result_ref;replayed:=true;
 else
  if action='receive' then
   if m-array['action','operationId','alertId','identity','material','reason','purpose']<>'{}'::jsonb then raise exception 'ALERT_INPUT_INVALID'; end if;
   i:=m->'identity';a:=m->'material';au:=a->'automation';
   if jsonb_typeof(i) is distinct from 'object' or jsonb_typeof(a) is distinct from 'object'
    or i-array['sourceRef','causeId','contextKind','contextId','scopeRef','effect']<>'{}'::jsonb
    or a-array['cause','risk','requiredAction','urgency','sourceVersion','automation']<>'{}'::jsonb then raise exception 'ALERT_INPUT_INVALID'; end if;
   foreach k in array array['sourceRef','causeId','contextKind','contextId','scopeRef','effect'] loop
    if jsonb_typeof(i->k) is distinct from 'string' or nullif(btrim(i->>k),'') is null then raise exception 'ALERT_INPUT_INVALID'; end if;
   end loop;
   foreach k in array array['cause','risk','requiredAction','urgency','sourceVersion'] loop
    if jsonb_typeof(a->k) is distinct from 'string' or nullif(btrim(a->>k),'') is null then raise exception 'ALERT_INPUT_INVALID'; end if;
   end loop;
   if i->>'contextKind' not in ('contact','organization','opportunity','booking','booking_service','provider','proposal','other')
    or a->>'urgency' not in ('informative','important','critical') then raise exception 'ALERT_INPUT_INVALID'; end if;
   perform (i->>'contextId')::uuid;
   missing:='[]'::jsonb;
   if au is null then raise exception 'ALERT_INPUT_INVALID'; end if;
   if au<>'null'::jsonb then
    if jsonb_typeof(au) is distinct from 'object' or au-array['definitionRef','executionRef','version','triggerRef','inputsRef','permissionsRef','effectsRef','recordsRef','retryLimit','pauseSeconds','missingParameters']<>'{}'::jsonb
     or a->>'urgency'='informative' then raise exception 'ALERT_AUTOMATION_INVALID'; end if;
    foreach k in array array['definitionRef','executionRef','version','triggerRef','inputsRef','permissionsRef','effectsRef','recordsRef'] loop
     if jsonb_typeof(au->k) is distinct from 'string' or nullif(btrim(au->>k),'') is null then raise exception 'ALERT_AUTOMATION_INVALID'; end if;
    end loop;
    foreach k in array array['retryLimit','pauseSeconds'] loop
     if au->k is null then raise exception 'ALERT_AUTOMATION_INVALID'; end if;
     if au->k='null'::jsonb then missing:=missing||jsonb_build_array(k);
     elsif jsonb_typeof(au->k)<>'number' or (au->>k)::numeric<0 or (au->>k)::numeric<>trunc((au->>k)::numeric)
      or (au->>k)::numeric>2147483647 then raise exception 'ALERT_AUTOMATION_INVALID'; end if;
    end loop;
    if jsonb_typeof(au->'missingParameters') is distinct from 'array' then raise exception 'ALERT_AUTOMATION_INVALID'; end if;
    if exists(select 1 from jsonb_array_elements(au->'missingParameters') x where jsonb_typeof(x)<>'string' or nullif(btrim(x#>>'{}'),'') is null) then raise exception 'ALERT_AUTOMATION_INVALID'; end if;
    missing:=missing||(au->'missingParameters');
   end if;
   causekey:=encode(crm_crypto.digest(convert_to(i::text,'UTF8'),'sha256'),'hex');
   perform pg_advisory_xact_lock(hashtextextended(scope||causekey,503));
   select * into old from crm_private.b07_alerts where admin_scope=scope and identity_key=causekey for update;
   if found then
    if old.identity<>i or old.material<>a then raise exception 'ALERT_IDENTITY_CONFLICT'; end if;
    target:=old.alert_id;changed:=false;
   else
    insert into crm_private.b07_alerts(alert_id,admin_scope,identity_key,identity,material,responsible_actor,control_state,missing_parameters)
     values(target,scope,causekey,i,a,actor,'review_required',missing);
    insert into crm_private.b07_notifications(notification_id,alert_id,admin_scope,channel,recipient_actor,intent,delivery_state)
     values(gen_random_uuid(),target,scope,'crm',actor,'internal-alert','visible');
    if a->>'urgency' in ('critical','important') then
     insert into crm_private.b07_notifications(notification_id,alert_id,admin_scope,channel,recipient_actor,intent,delivery_state)
      values(gen_random_uuid(),target,scope,'whatsapp',actor,'internal-alert','unavailable');
    end if;
   end if;
  else
   select * into old from crm_private.b07_alerts where alert_id=target and admin_scope=scope for update;
   if not found then raise exception 'ALERT_DENIED' using errcode='42501'; end if;
   before_data:=to_jsonb(old);
   if m->>'expectedRevision' is null or (m->>'expectedRevision')::bigint<1 then raise exception 'ALERT_REVISION_CONFLICT'; end if;
   if action='record_synthetic_result' then
    if m-array['action','operationId','alertId','expectedRevision','attemptId','outcome','resultRef','version','reason','reviewRef','purpose']<>'{}'::jsonb
     or m->>'attemptId' is null or m->>'outcome' is null or m->>'outcome' not in ('failed','uncertain','simulated_delivered')
     or nullif(btrim(m->>'resultRef'),'') is null or nullif(btrim(m->>'version'),'') is null then raise exception 'ALERT_ATTEMPT_INVALID'; end if;
    select * into n from crm_private.b07_notifications where alert_id=target and channel='whatsapp' for update;
    if not found then raise exception 'ALERT_NO_WHATSAPP_INTENT'; end if;
    attempt_fingerprint:=encode(crm_crypto.digest(convert_to((m-array['operationId','expectedRevision','purpose'])::text,'UTF8'),'sha256'),'hex');
    select * into pa from crm_private.b07_notification_attempts where attempt_id=(m->>'attemptId')::uuid;
    if found then
     if pa.notification_id<>n.notification_id or pa.fingerprint<>attempt_fingerprint then raise exception 'ALERT_ATTEMPT_CONFLICT'; end if;
     changed:=false;
    else
     if old.revision<>(m->>'expectedRevision')::bigint then raise exception 'ALERT_REVISION_CONFLICT'; end if;
     if old.control_state='stopped' then raise exception 'ALERT_STOPPED'; end if;
     if n.attempt_count>0 then
      if nullif(btrim(m->>'reviewRef'),'') is null then raise exception 'ALERT_REVIEW_REQUIRED'; end if;
      au:=old.material->'automation';
      if au='null'::jsonb or jsonb_array_length(old.missing_parameters)>0 then raise exception 'ALERT_PARAMETERS_MISSING'; end if;
      if n.attempt_count>(au->>'retryLimit')::int then raise exception 'ALERT_RETRY_LIMIT'; end if;
      if exists(select 1 from crm_private.b07_notification_attempts where notification_id=n.notification_id
       and recorded_at+make_interval(secs=>(au->>'pauseSeconds')::int)>clock_timestamp()) then raise exception 'ALERT_PAUSE_PENDING'; end if;
     end if;
     insert into crm_private.b07_notification_attempts(attempt_id,notification_id,admin_scope,attempt_number,fingerprint,outcome,result_ref,source_version,review_ref,simulated,recorded_by)
      values((m->>'attemptId')::uuid,n.notification_id,scope,n.attempt_count+1,attempt_fingerprint,m->>'outcome',m->>'resultRef',m->>'version',m->>'reviewRef',true,actor);
     update crm_private.b07_notifications set last_synthetic_outcome=m->>'outcome',attempt_count=attempt_count+1 where notification_id=n.notification_id;
     update crm_private.b07_alerts set revision=revision+1 where alert_id=target;
    end if;
   else
    if m-array['action','operationId','alertId','expectedRevision','reason','reviewRef','purpose']<>'{}'::jsonb or nullif(btrim(m->>'reviewRef'),'') is null then raise exception 'ALERT_REVIEW_REQUIRED'; end if;
    if old.revision<>(m->>'expectedRevision')::bigint then raise exception 'ALERT_REVISION_CONFLICT'; end if;
    update crm_private.b07_alerts set control_state=case when action='stop' then 'stopped' else 'review_required' end,revision=revision+1 where alert_id=target;
   end if;
  end if;
  insert into crm_private.b07_operations(operation_id,admin_scope,actor_id,fingerprint,result_ref) values(opid,scope,actor,fingerprint,target);
  if changed then
   select to_jsonb(t)||jsonb_build_object('notifications',(select jsonb_agg(to_jsonb(notice) order by notice.channel) from crm_private.b07_notifications notice where notice.alert_id=target)) into after_data from crm_private.b07_alerts t where t.alert_id=target;
   insert into crm_private.b07_history(history_id,operation_id,subject_id,admin_scope,action_kind,before_state,after_state,reason,source_ref,actor_id)
    values(opid,opid,target,scope,'alert_'||action,before_data,after_data,m->>'reason',coalesce(m->>'resultRef',m->>'reviewRef',i->>'sourceRef'),actor);
  end if;
  result_ref:=target;replayed:=not changed;
 end if;
 perform crm_f2.verify(f2p,f2s,q,'C03','human_evidence','write_evidence');
 perform crm_f1.verify_envelope(f1p,f1s,q,'C03','evidence','write_evidence');
 return next;
end $function$

CREATE OR REPLACE FUNCTION crm_api.b07_alert_read(f2p bytea, f2s bytea, f1p bytea, f1s bytea, q bytea)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare hf text[];tf text[];v text[];m jsonb;result jsonb;target uuid;
begin
 hf:=crm_f2.admit(f2p,f2s,q,'C01','read_evidence');
 tf:=crm_f1.verify_envelope(f1p,f1s,q,'C01','evidence','read_evidence');
 if hf[17] collate "C"<>tf[14] collate "C" then raise exception 'ALERT_DENIED'; end if;
 v:=crm_f1.fields(q);if cardinality(v)<>2 or v[1]<>'CRM-H5-ALERT-READ1' then raise exception 'ALERT_INPUT_INVALID'; end if;
 m:=v[2]::jsonb;
 if m->>'purpose' is distinct from 'internal-alert' or m-array['alertId','purpose']<>'{}'::jsonb then raise exception 'ALERT_DENIED'; end if;
 target:=(m->>'alertId')::uuid;
 select to_jsonb(t)||jsonb_build_object(
  'notifications',coalesce((select jsonb_agg(to_jsonb(notice) order by notice.channel) from crm_private.b07_notifications notice where notice.alert_id=target),'[]'::jsonb),
  'attempts',coalesce((select jsonb_agg(to_jsonb(a) order by a.attempt_number) from crm_private.b07_notification_attempts a join crm_private.b07_notifications n using(notification_id) where n.alert_id=target),'[]'::jsonb),
  'history',coalesce((select jsonb_agg(to_jsonb(h) order by h.recorded_at,h.history_id) from crm_private.b07_history h where h.subject_id=target and h.admin_scope=hf[17]),'[]'::jsonb)) into result
 from crm_private.b07_alerts t where t.alert_id=target and t.admin_scope=hf[17];
 perform crm_f2.verify(f2p,f2s,q,'C01','human_evidence','read_evidence');
 perform crm_f1.verify_envelope(f1p,f1s,q,'C01','evidence','read_evidence');return result;
end $function$

CREATE OR REPLACE FUNCTION crm_api.b07_apply(f2p bytea, f2s bytea, f1p bytea, f1s bytea, q bytea)
 RETURNS TABLE(result_ref uuid, replayed boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare hf text[];tf text[];v text[];op crm_private.b07_operations%rowtype;
  parent crm_private.b07_records%rowtype; related crm_private.b07_records%rowtype;
  actor uuid;scope text;target uuid;original uuid;corrects uuid;target_context uuid;
  payload_data jsonb;prior_state jsonb;after_state jsonb;fingerprint text;occurred timestamptz;
begin
  hf:=crm_f2.admit(f2p,f2s,q,'C03','write_evidence');
  tf:=crm_f1.verify_envelope(f1p,f1s,q,'C03','evidence','write_evidence');
  if hf[17] collate "C" <> tf[14] collate "C" then
    raise exception 'B07_DENIED' using errcode='42501'; end if;
  v:=crm_f1.fields(q);
  if cardinality(v)<>15 or v[1]<>'CRM-H1-B07-1' or v[2] not in ('create','link')
    or v[7]='' or v[8]='' or v[14]='' or v[15]='' or v[12] not in
      ('contact','organization','opportunity','booking','booking_service','provider','proposal','other')
  then raise exception 'B07_INPUT_INVALID' using errcode='22023'; end if;
  target:=v[4]::uuid;target_context:=v[13]::uuid;
  original:=nullif(v[10],'')::uuid;corrects:=nullif(v[11],'')::uuid;
  occurred:=nullif(v[9],'')::timestamptz;payload_data:=v[6]::jsonb;
  actor:=hf[12]::uuid;scope:=hf[17];
  fingerprint:=encode(crm_crypto.digest(q,'sha256'),'hex');
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(v[3],0));
  select * into op from crm_private.b07_operations where operation_id=v[3]::uuid;
  if found then
    if op.admin_scope<>scope or op.actor_id<>actor or op.fingerprint<>fingerprint then
      raise exception 'B07_REPLAY_CONFLICT' using errcode='23505'; end if;
    perform crm_f2.verify(f2p,f2s,q,'C03','human_evidence','write_evidence');
    result_ref:=op.result_ref;replayed:=true;return next;return;
  end if;
  if v[2]='create' then
    if v[5] not in ('document','evidence','communication','communication_fact',
       'integration_source','external_reference','external_event')
      or not coalesce(crm_private.b07_material_valid(v[5],payload_data,original,occurred),false) then
      raise exception 'B07_INPUT_INVALID' using errcode='22023'; end if;
    if original is not null then
      select * into parent from crm_private.b07_records where record_id=original;
      if not found or parent.admin_scope<>scope or not (
        (v[5]='document' and parent.record_kind='document') or
        (v[5]='communication_fact' and parent.record_kind='communication')) then
        raise exception 'B07_RELATION_INVALID' using errcode='22023'; end if;
      if v[5]='document' and parent.material->>'relation'<>'original' then
        raise exception 'B07_RELATION_INVALID' using errcode='22023'; end if;
      if not exists(select 1 from crm_private.b07_links l where l.record_id=original
        and l.admin_scope=scope and l.context_kind=v[12] and l.context_id=target_context) then
        raise exception 'B07_RELATION_INVALID' using errcode='22023'; end if;
      if v[5]='communication_fact' and (
        (payload_data->>'fact_kind'='sent' and parent.material->>'direction'<>'outgoing') or
        (payload_data->>'fact_kind'='received' and parent.material->>'direction'<>'outgoing') or
        (payload_data->>'fact_kind'='sent' and parent.material->>'recipient_ref' is distinct from payload_data->>'party_ref') or
        (payload_data->>'fact_kind'='sent' and v[12]='proposal' and
          (nullif(parent.material->>'proposal_version_ref','') is null or
           nullif(parent.material->>'authorization_ref','') is null))
      ) then raise exception 'B07_RELATION_INVALID' using errcode='22023'; end if;
    end if;
    if corrects is not null then
      select * into related from crm_private.b07_records where record_id=corrects;
      if not found or related.admin_scope<>scope or related.record_kind<>v[5] then
        raise exception 'B07_RELATION_INVALID' using errcode='22023'; end if;
      if not exists(select 1 from crm_private.b07_links l where l.record_id=corrects
        and l.admin_scope=scope and l.context_kind=v[12] and l.context_id=target_context) then
        raise exception 'B07_RELATION_INVALID' using errcode='22023'; end if;
      prior_state:=to_jsonb(related);
    end if;
    if v[5]='evidence' and payload_data ? 'document_id' then
      select * into related from crm_private.b07_records
        where record_id=(payload_data->>'document_id')::uuid;
      if not found or related.admin_scope<>scope or related.record_kind<>'document' then
        raise exception 'B07_RELATION_INVALID' using errcode='22023'; end if;
      if not exists(select 1 from crm_private.b07_links l where l.record_id=related.record_id
        and l.admin_scope=scope and l.context_kind=v[12] and l.context_id=target_context) then
        raise exception 'B07_RELATION_INVALID' using errcode='22023'; end if;
    end if;
    if v[5]='communication_fact' then
      select * into related from crm_private.b07_records
        where record_id=(payload_data->>'evidence_id')::uuid;
      if not found or related.admin_scope<>scope or related.record_kind<>'evidence' then
        raise exception 'B07_RELATION_INVALID' using errcode='22023'; end if;
      if not exists(select 1 from crm_private.b07_links l where l.record_id=related.record_id
        and l.admin_scope=scope and l.context_kind=v[12] and l.context_id=target_context) then
        raise exception 'B07_RELATION_INVALID' using errcode='22023'; end if;
      if exists(select 1 from crm_private.b07_records r where r.record_kind='communication_fact'
        and r.original_id=original and r.material->>'evidence_id'=payload_data->>'evidence_id') then
        raise exception 'B07_RELATION_INVALID' using errcode='22023'; end if;
      if payload_data->>'fact_kind'='sent' and payload_data->>'coverage' is distinct from parent.material->>'coverage' then
        raise exception 'B07_RELATION_INVALID' using errcode='22023'; end if;
    end if;
    if v[5] in ('external_reference','external_event') then
      select * into related from crm_private.b07_records
        where record_id=(payload_data->>'source_id')::uuid;
      if not found or related.admin_scope<>scope or related.record_kind<>'integration_source' then
        raise exception 'B07_RELATION_INVALID' using errcode='22023'; end if;
      if not exists(select 1 from crm_private.b07_links l where l.record_id=related.record_id
        and l.admin_scope=scope and l.context_kind=v[12] and l.context_id=target_context) then
        raise exception 'B07_RELATION_INVALID' using errcode='22023'; end if;
    end if;
    insert into crm_private.b07_records(record_id,record_kind,admin_scope,material,source_ref,
      purpose,occurred_at,recorded_by,original_id,corrects_id)
      values(target,v[5],scope,payload_data,v[7],v[8],occurred,actor,original,corrects);
    insert into crm_private.b07_links(link_id,record_id,admin_scope,context_kind,context_id,
      coverage,source_ref,linked_by) values(v[3]::uuid,target,scope,v[12],target_context,v[15],v[7],actor);
    select jsonb_build_object('record',to_jsonb(r),'link',to_jsonb(l)) into after_state
      from crm_private.b07_records r join crm_private.b07_links l on l.record_id=r.record_id
      where r.record_id=target and l.link_id=v[3]::uuid;
  else
    if v[5]<>'' or payload_data<>'{}'::jsonb or v[9]<>'' or corrects is not null
      or original is null then raise exception 'B07_INPUT_INVALID' using errcode='22023'; end if;
    select * into parent from crm_private.b07_records where record_id=original;
    if not found or parent.admin_scope<>scope then
      raise exception 'B07_DENIED' using errcode='42501'; end if;
    insert into crm_private.b07_links(link_id,record_id,admin_scope,context_kind,context_id,
      coverage,source_ref,linked_by) values(target,original,scope,v[12],target_context,v[15],v[7],actor);
    select to_jsonb(l) into after_state from crm_private.b07_links l where link_id=target;
  end if;
  insert into crm_private.b07_operations(operation_id,admin_scope,actor_id,fingerprint,result_ref)
    values(v[3]::uuid,scope,actor,fingerprint,target);
  insert into crm_private.b07_history(history_id,operation_id,subject_id,admin_scope,action_kind,
    before_state,after_state,reason,source_ref,occurred_at,actor_id)
    values(v[3]::uuid,v[3]::uuid,target,scope,v[2],prior_state,after_state,v[14],v[7],occurred,actor);
  perform crm_f2.verify(f2p,f2s,q,'C03','human_evidence','write_evidence');
  perform crm_f1.verify_envelope(f1p,f1s,q,'C03','evidence','write_evidence');
  result_ref:=target;replayed:=false;return next;
end $function$

CREATE OR REPLACE FUNCTION crm_api.b07_communication_apply(f2p bytea, f2s bytea, f1p bytea, f1s bytea, q bytea)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
#variable_conflict use_column
declare hf text[];tf text[];v text[];m jsonb;a text;scope text;actor uuid;opid uuid;id uuid;rid uuid;
 rec crm_private.b07_records%rowtype;orig crm_private.b07_records%rowtype;confirmed crm_private.b07_records%rowtype;
 old crm_private.b07_operations%rowtype;prior crm_private.b07_communication_work%rowtype;existing crm_private.b07_communication_work%rowtype;
 fingerprint text;identitykey text;kind text;original uuid;previous uuid;taskid uuid;body jsonb;allowed text[];
 proof crm_private.b07_records%rowtype;taskrow crm_private.b07_pending_tasks%rowtype;taskop uuid;taskmaterial jsonb;result jsonb;replayed boolean:=false;
begin
 hf:=crm_f2.admit(f2p,f2s,q,'C03','write_evidence');tf:=crm_f1.verify_envelope(f1p,f1s,q,'C03','evidence','write_evidence');
 if hf[17] collate "C"<>tf[14] collate "C" then raise exception 'COMM_DENIED';end if;
 scope:=hf[17];actor:=hf[12]::uuid;v:=crm_f1.fields(q);
 if cardinality(v)<>2 or v[1]<>'CRM-H5-COMM-1'then raise exception 'COMM_INPUT_INVALID';end if;
 m:=v[2]::jsonb;a:=m->>'action';
 allowed:=array['contextKind','contextId','purpose','operationId','workId','recordId','reason','sourceRef','at','action'];
 if a='draft'then allowed:=allowed||array['previousId','material'];
 elsif a='prepare'then allowed:=allowed||array['versionId'];
 elsif a='derive'then allowed:=allowed||array['originalId','kind','content','origin','review','permissionRef','authorRef','confirmedId','confidence','field'];
 elsif a='fact'then allowed:=allowed||array['versionId','fact','evidenceId','party','coverage','ambiguous','synthetic'];
 else raise exception 'COMM_INPUT_INVALID';end if;
 if jsonb_typeof(m) is distinct from 'object' or m-allowed<>'{}'::jsonb or not(m ?& allowed)
 or exists(select 1 from unnest(array['contextKind','contextId','purpose','reason','sourceRef','at']) k where nullif(btrim(m->>k),'') is null)
 then raise exception 'COMM_INPUT_INVALID';end if;
 opid:=(m->>'operationId')::uuid;id:=(m->>'workId')::uuid;rid:=(m->>'recordId')::uuid;perform (m->>'at')::timestamptz;
 select * into rec from crm_private.b07_records r where r.record_id=rid and r.admin_scope=scope
 and r.purpose=m->>'purpose' and exists(select 1 from crm_private.b07_links l where l.record_id=r.record_id and l.admin_scope=scope and l.context_kind=m->>'contextKind' and l.context_id=(m->>'contextId')::uuid);
 if not found then raise exception 'COMM_DENIED';end if;
 fingerprint:=encode(crm_crypto.digest(convert_to(m::text,'UTF8'),'sha256'),'hex');
 perform pg_advisory_xact_lock(hashtextextended(opid::text,0));
 select * into old from crm_private.b07_operations where operation_id=opid;
 if found then
 if old.admin_scope<>scope or old.actor_id<>actor or old.fingerprint<>fingerprint then raise exception 'COMM_REPLAY_CONFLICT';end if;
 id:=old.result_ref;replayed:=true;
 else
 -- Root lock protects absent revisions/derivatives too; no session singleton assumed.
 perform pg_advisory_xact_lock(hashtextextended(scope||rid::text,55));
 body:=m-array['operationId','workId','reason'];
 identitykey:=encode(crm_crypto.digest(convert_to(body::text,'UTF8'),'sha256'),'hex');
 select * into existing from crm_private.b07_communication_work where admin_scope=scope and identity_key=identitykey;
 if found then id:=existing.work_id;replayed:=true;
 else
 kind:=a;
 if a='draft'then
 if rec.record_kind<>'communication' or rec.material->>'direction'<>'outgoing' then raise exception 'COMM_DIRECTION_INVALID';end if;
 if jsonb_typeof(m->'material') is distinct from 'object' or (m->'material')-array['content','coverage','recipient','nature','origin','pending','sourceRef']<>'{}'::jsonb
 or not((m->'material') ?& array['content','coverage','recipient','nature','origin','pending','sourceRef'])
 or exists(select 1 from unnest(array['content','coverage','recipient','sourceRef']) k where nullif(btrim(m->'material'->>k),'') is null)
 or coalesce(m->'material'->>'nature','') not in ('informative','sensitive') or coalesce(m->'material'->>'origin','') not in ('human','synthetic_automatic')
 or jsonb_typeof(m->'material'->'pending') is distinct from 'array'
 or exists(select 1 from jsonb_array_elements(m->'material'->'pending') x where jsonb_typeof(x)<>'string' or nullif(btrim(x#>>'{}'),'')is null)
 then raise exception 'COMM_INPUT_INVALID';end if;
 select * into prior from crm_private.b07_communication_work where record_id=rid and kind='draft' order by recorded_at desc,work_id desc limit 1;
 previous:=(m->>'previousId')::uuid;
 if prior.work_id is distinct from previous then raise exception 'COMM_VERSION_CONFLICT';end if;
 elsif a='prepare'then
 previous:=(m->>'versionId')::uuid;
 select * into prior from crm_private.b07_communication_work where work_id=previous and record_id=rid and admin_scope=scope and kind='draft';
 if not found or exists(select 1 from crm_private.b07_communication_work where record_id=rid and kind='draft' and previous_id=previous) then raise exception 'COMM_VERSION_CONFLICT';end if;
 if exists(select 1 from crm_private.b07_communication_work where kind='prepare' and previous_id=previous)then raise exception 'COMM_ALREADY_PREPARED';end if;
 elsif a='derive'then
 original:=(m->>'originalId')::uuid;kind:=m->>'kind';
 select * into orig from crm_private.b07_records r where r.record_id=original and r.admin_scope=scope and r.purpose=m->>'purpose' and r.record_kind='document' and r.material->>'relation'='original'
 and exists(select 1 from crm_private.b07_links l where l.record_id=r.record_id and l.admin_scope=scope and l.context_kind=m->>'contextKind' and l.context_id=(m->>'contextId')::uuid);
 if not found then raise exception 'COMM_ORIGINAL_DENIED';end if;
 if kind not in ('summary','note','candidate')or coalesce(m->>'origin','') not in ('human','synthetic_automatic')
 or exists(select 1 from unnest(array['content','review','permissionRef','authorRef'])k where nullif(btrim(m->>k),'')is null)
 or (m->>'confidence'is not null and ((m->>'confidence')::numeric not between 0 and 1))then raise exception 'COMM_INPUT_INVALID';end if;
 if kind='candidate'then
 if m->>'origin'<>'synthetic_automatic' or nullif(m->>'field','')is null then raise exception 'COMM_INPUT_INVALID';end if;
 if m->>'confirmedId'is not null then
 select * into confirmed from crm_private.b07_records r where r.record_id=(m->>'confirmedId')::uuid and r.admin_scope=scope and r.purpose=m->>'purpose'
 and r.record_kind='evidence' and r.material->>'source_kind'='manual' and r.material->>'certainty'='reviewed'
 and exists(select 1 from crm_private.b07_links l where l.record_id=r.record_id and l.admin_scope=scope and l.context_kind=m->>'contextKind' and l.context_id=(m->>'contextId')::uuid);
 if not found then raise exception 'COMM_CONFIRMATION_DENIED';end if;
 end if;
 -- Every synthetic candidate has visible pending review. A manual confirmed reference requires follow-up.
 body:=body||jsonb_build_object('reviewState','pending','confirmedSnapshot',case when confirmed.record_id is null then null else confirmed.material end);
 if confirmed.record_id is not null then
 taskid:=gen_random_uuid();taskop:=gen_random_uuid();
 taskmaterial:=jsonb_build_object('action','receive','operationId',taskop,'taskId',taskid,'expectedRevision',0,'purpose','pending-followup',
 'identity',jsonb_build_object('causeKind','review','causeId',confirmed.record_id,'contextKind',m->>'contextKind','contextId',m->>'contextId','scopeRef',m->>'field','relatedKind',null,'relatedId',null,'effect','review-extraction'),
 'material',jsonb_build_object('title','Revisar extracción frente a dato confirmado','deadline',jsonb_build_object('kind','unknown','reason','Sin plazo aprobado'),'priority',jsonb_build_object('kind','pending','reason','Sin prioridad configurada'),'sourceRef',confirmed.record_id::text,'sourceVersion','1','triggerRef','manual','triggerVersion','1'),
 'reason','BR-AI-005: revisión de candidato sintético; no altera dato confirmado');
 select x.result_ref into taskid from crm_private.booking_preparation_task_core(taskmaterial,actor,scope)x;
 select * into taskrow from crm_private.b07_pending_tasks where task_id=taskid for update;
 if taskrow.state<>'pending' then
 perform crm_private.h5_task_lifecycle_core(jsonb_build_object('action','reopen','operationId',gen_random_uuid(),'taskId',taskid,
 'expectedRevision',taskrow.revision,'purpose','pending-followup','reason','Nuevo candidato material exige revisión explícita',
 'reviewEvidenceRef',id::text),actor,scope);
 end if;
 end if;
 end if;
 -- Reuse H1 Document/Evidence. The derived record is distinct from its source; no binary is fabricated.
 if kind='candidate'then
 insert into crm_private.b07_records(record_id,record_kind,admin_scope,material,source_ref,purpose,occurred_at,recorded_by)
 values(id,'evidence',scope,jsonb_build_object('claim',m->>'content','coverage',m->>'field','certainty','candidate','source_kind','document','document_id',original),m->>'sourceRef',m->>'purpose',(m->>'at')::timestamptz,actor);
 else
 insert into crm_private.b07_records(record_id,record_kind,admin_scope,material,source_ref,purpose,occurred_at,recorded_by,original_id)
 values(id,'document',scope,jsonb_build_object('relation','derived','content_ref',id::text,'content_kind',kind,'author_ref',m->>'authorRef','review_ref',m->>'review','storage_state','reference_only'),m->>'sourceRef',m->>'purpose',(m->>'at')::timestamptz,actor,original);
 end if;
 insert into crm_private.b07_links(link_id,record_id,admin_scope,context_kind,context_id,coverage,source_ref,linked_by)
 values(id,id,scope,m->>'contextKind',(m->>'contextId')::uuid,coalesce(m->>'field',kind),m->>'sourceRef',actor);
 elsif a='fact'then
 kind:=m->>'fact';previous:=(m->>'versionId')::uuid;
 if rec.record_kind<>'communication' or kind not in ('sent','received','read','response') or m->'synthetic' is distinct from 'true'::jsonb
 or jsonb_typeof(m->'ambiguous') is distinct from 'boolean' or nullif(btrim(m->>'party'),'')is null or nullif(btrim(m->>'coverage'),'')is null then raise exception 'COMM_INPUT_INVALID';end if;
 select * into proof from crm_private.b07_records r where r.record_id=(m->>'evidenceId')::uuid and r.admin_scope=scope and r.purpose=m->>'purpose' and r.record_kind='evidence'
 and r.material->>'certainty'='reviewed' and r.material->>'source_kind'='manual'
 and r.material->>'claim'=concat('synthetic:',kind,':',rid,':',coalesce(previous::text,''),':',m->>'party')
 and r.material->>'coverage'=m->>'coverage' and r.occurred_at=(m->>'at')::timestamptz
 and exists(select 1 from crm_private.b07_links l where l.record_id=r.record_id and l.admin_scope=scope and l.context_kind=m->>'contextKind' and l.context_id=(m->>'contextId')::uuid);
 if not found then raise exception 'COMM_PROOF_REQUIRED';end if;
 original:=proof.record_id;
 if kind='sent'then
 if m->>'contextKind'='proposal' and (nullif(rec.material->>'proposal_version_ref','')is null or nullif(rec.material->>'authorization_ref','')is null)then raise exception 'COMM_PROPOSAL_VERSION_REQUIRED';end if;
 select * into prior from crm_private.b07_communication_work where work_id=previous and record_id=rid and kind='draft' and admin_scope=scope;
 if not found or rec.material->>'direction'<>'outgoing' or prior.material->'material'->>'recipient'<>m->>'party' or prior.material->'material'->>'coverage'<>m->>'coverage'
 or exists(select 1 from crm_private.b07_communication_work where kind='draft' and previous_id=previous)
 or not exists(select 1 from crm_private.b07_communication_work where kind='prepare' and previous_id=prior.work_id)
 or (prior.material->'material'->>'nature'='sensitive' and prior.material->'material'->>'origin'='synthetic_automatic' and crm_private.communication_approval(prior)is null) then raise exception 'COMM_APPROVAL_REQUIRED';end if;
 end if;
 body:=body||jsonb_build_object('reviewState',case when kind='response'then 'pending'else null end,'businessConfirmation',false);
 if kind in ('sent','received','response')then
 insert into crm_private.b07_records(record_id,record_kind,admin_scope,material,source_ref,purpose,occurred_at,recorded_by,original_id)
 values(id,'communication_fact',scope,jsonb_build_object('fact_kind',kind,'evidence_id',proof.record_id,'party_ref',m->>'party','coverage',m->>'coverage'),m->>'sourceRef',m->>'purpose',(m->>'at')::timestamptz,actor,rid);
 insert into crm_private.b07_links(link_id,record_id,admin_scope,context_kind,context_id,coverage,source_ref,linked_by)
 values(id,id,scope,m->>'contextKind',(m->>'contextId')::uuid,m->>'coverage',m->>'sourceRef',actor);
 end if;
 end if;
 insert into crm_private.b07_communication_work(work_id,record_id,admin_scope,kind,identity_key,material,original_id,previous_id,task_id,recorded_by)
 values(id,rid,scope,kind,identitykey,body,original,previous,taskid,actor);
 end if;
 insert into crm_private.b07_operations(operation_id,admin_scope,actor_id,fingerprint,result_ref)values(opid,scope,actor,fingerprint,id);
 insert into crm_private.b07_history(history_id,operation_id,subject_id,admin_scope,action_kind,before_state,after_state,reason,source_ref,occurred_at,actor_id)
 values(opid,opid,rid,scope,'communication_'||a,case when prior.work_id is null then null else to_jsonb(prior)end,jsonb_build_object('workId',id,'reused',replayed,'material',body),m->>'reason',m->>'sourceRef',(m->>'at')::timestamptz,actor);
 end if;
 perform crm_f2.verify(f2p,f2s,q,'C03','human_evidence','write_evidence');perform crm_f1.verify_envelope(f1p,f1s,q,'C03','evidence','write_evidence');
 return jsonb_build_object('id',id,'replayed',replayed);
end $function$

CREATE OR REPLACE FUNCTION crm_api.b07_communication_read(f2p bytea, f2s bytea, f1p bytea, f1s bytea, q bytea)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
#variable_conflict use_column
declare hf text[];tf text[];v text[];m jsonb;rec crm_private.b07_records%rowtype;result jsonb;
begin
 hf:=crm_f2.admit(f2p,f2s,q,'C01','read_evidence');tf:=crm_f1.verify_envelope(f1p,f1s,q,'C01','evidence','read_evidence');
 if hf[17] collate "C"<>tf[14] collate "C"then raise exception 'COMM_DENIED';end if;
 v:=crm_f1.fields(q);if cardinality(v)<>2 or v[1]<>'CRM-H5-COMM-READ1'then raise exception 'COMM_INPUT_INVALID';end if;
 m:=v[2]::jsonb;if m-array['recordId','contextKind','contextId','purpose']<>'{}'::jsonb then raise exception 'COMM_INPUT_INVALID';end if;
 select * into rec from crm_private.b07_records r where r.record_id=(m->>'recordId')::uuid and r.admin_scope=hf[17] and r.purpose=m->>'purpose'
 and exists(select 1 from crm_private.b07_links l where l.record_id=r.record_id and l.admin_scope=hf[17] and l.context_kind=m->>'contextKind' and l.context_id=(m->>'contextId')::uuid);
 if found then
 select jsonb_build_object('record',to_jsonb(rec),'work',coalesce(jsonb_agg(to_jsonb(w)||jsonb_build_object(
 'approval',case when w.kind='draft'then crm_private.communication_approval(w)else null end,
 'prepared',exists(select 1 from crm_private.b07_communication_work p where p.kind='prepare'and p.previous_id=w.work_id),
 'objectConservation',case when w.original_id is null then null else coalesce((select jsonb_agg(jsonb_build_object('versionId',o.version_id,'state',o.state))from crm_private.b07_object_versions o where o.document_id=w.original_id and o.admin_scope=hf[17]),'[]'::jsonb)end
 )order by w.recorded_at,w.work_id)filter(where w.work_id is not null),'[]'::jsonb),'externalSendEnabled',false,
 'registeredFacts',coalesce((select jsonb_agg(to_jsonb(r) order by r.recorded_at,r.record_id)from crm_private.b07_records r where r.original_id=rec.record_id and r.record_kind='communication_fact'and r.admin_scope=hf[17] and r.purpose=m->>'purpose' and exists(select 1 from crm_private.b07_links l where l.record_id=r.record_id and l.admin_scope=hf[17] and l.context_kind=m->>'contextKind' and l.context_id=(m->>'contextId')::uuid)),'[]'::jsonb))
 into result from crm_private.b07_communication_work w where w.record_id=rec.record_id and w.admin_scope=hf[17]
 and w.material->>'purpose'=m->>'purpose' and w.material->>'contextKind'=m->>'contextKind' and w.material->>'contextId'=m->>'contextId';
 end if;
 perform crm_f2.verify(f2p,f2s,q,'C01','human_evidence','read_evidence');perform crm_f1.verify_envelope(f1p,f1s,q,'C01','evidence','read_evidence');return result;
end $function$

CREATE OR REPLACE FUNCTION crm_api.b07_object_apply(f2p bytea, f2s bytea, f1p bytea, f1s bytea, q bytea)
 RETURNS TABLE(result_ref uuid, replayed boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare hf text[];tf text[];v text[];m jsonb;actor uuid;scope text;opid uuid;target uuid;
 fingerprint text;op crm_private.b07_operations%rowtype;
 old crm_private.b07_object_versions%rowtype;previous crm_private.b07_object_versions%rowtype;
 before_data jsonb;after_data jsonb;next_state text;root uuid;
begin
 hf:=crm_f2.admit(f2p,f2s,q,'C03','write_evidence');
 tf:=crm_f1.verify_envelope(f1p,f1s,q,'C03','evidence','write_evidence');
 if hf[17] collate "C"<>tf[14] collate "C" then raise exception 'OBJECT_DENIED' using errcode='42501'; end if;
 v:=crm_f1.fields(q);
 if cardinality(v)<>2 or v[1]<>'CRM-H1-OBJECT-1' then raise exception 'OBJECT_INPUT_INVALID'; end if;
 m:=v[2]::jsonb;actor:=hf[12]::uuid;scope:=hf[17];opid:=(m->>'operationId')::uuid;
 target:=(m->>'versionId')::uuid;
 -- expectedRevision is sampled by the server on each retry, not client material.
 fingerprint:=encode(crm_crypto.digest(convert_to((m-'expectedRevision')::text,'UTF8'),'sha256'),'hex');
 if nullif(m->>'reason','') is null or nullif(m->>'sourceRef','') is null or nullif(m->>'purpose','') is null then
  raise exception 'OBJECT_INPUT_INVALID'; end if;
 perform pg_advisory_xact_lock(hashtextextended(opid::text,0));
 select * into op from crm_private.b07_operations where operation_id=opid;
 if found then
  if op.admin_scope<>scope or op.actor_id<>actor or op.fingerprint<>fingerprint then raise exception 'OBJECT_REPLAY_CONFLICT'; end if;
  result_ref:=op.result_ref;replayed:=true;
 else
  if m->>'action'='orphan' then
   perform pg_advisory_xact_lock(hashtextextended(m->>'privateRef',1));
   if exists(select 1 from crm_private.b07_object_versions where private_ref=m->>'privateRef') then raise exception 'OBJECT_NOT_ORPHAN'; end if;
   insert into crm_private.b07_object_orphans(private_ref,admin_scope,state,source_ref,recorded_by)
    values(m->>'privateRef',scope,'needs_review',m->>'sourceRef',actor) on conflict do nothing;
   select to_jsonb(o) into after_data from crm_private.b07_object_orphans o where private_ref=m->>'privateRef' and admin_scope=scope;
   if after_data is null then raise exception 'OBJECT_DENIED'; end if;
  elsif m->>'action'='prepare' then
   root:=(m->>'rootId')::uuid;perform pg_advisory_xact_lock(hashtextextended(root::text,2));
   if not exists(select 1 from crm_private.b07_records r join crm_private.b07_links l on l.record_id=r.record_id
    where r.record_id=(m->>'documentId')::uuid and r.record_kind='document' and r.admin_scope=scope
     and l.admin_scope=scope and l.context_kind=m->>'contextKind' and l.context_id=(m->>'contextId')::uuid) then raise exception 'OBJECT_DENIED'; end if;
   if (m->>'expectedVersion')::integer=0 then
    if exists(select 1 from crm_private.b07_object_versions where root_id=root) then raise exception 'OBJECT_VERSION_CONFLICT'; end if;
   else
    select * into previous from crm_private.b07_object_versions where root_id=root and version_number=(m->>'expectedVersion')::integer;
    if not found or previous.admin_scope<>scope or previous.document_id<>(m->>'documentId')::uuid or
     previous.purpose<>m->>'purpose' or exists(select 1 from crm_private.b07_object_versions where root_id=root and version_number>previous.version_number) then raise exception 'OBJECT_VERSION_CONFLICT'; end if;
    before_data:=to_jsonb(previous);
   end if;
   insert into crm_private.b07_object_versions(version_id,root_id,version_number,predecessor_id,document_id,
    admin_scope,purpose,source_ref,private_ref,expected_digest,expected_size,expected_media,state,recorded_by)
   values(target,root,(m->>'expectedVersion')::integer+1,previous.version_id,(m->>'documentId')::uuid,
    scope,m->>'purpose',m->>'sourceRef',root::text||'/'||target::text,m->>'digest',(m->>'size')::bigint,m->>'media','prepared',actor);
   select to_jsonb(o) into after_data from crm_private.b07_object_versions o where version_id=target;
  else
   select * into old from crm_private.b07_object_versions where version_id=target for update;
   if not found or old.admin_scope<>scope or old.purpose<>m->>'purpose' or not exists(
    select 1 from crm_private.b07_links l where l.record_id=old.document_id and l.admin_scope=scope
     and l.context_kind=m->>'contextKind' and l.context_id=(m->>'contextId')::uuid) then raise exception 'OBJECT_DENIED'; end if;
   if old.revision<>(m->>'expectedRevision')::bigint then raise exception 'OBJECT_VERSION_CONFLICT'; end if;
   before_data:=to_jsonb(old);
   if m->>'action'='uploaded' then
    if old.state<>'prepared' and old.state<>'missing' then raise exception 'OBJECT_STATE_INVALID'; end if;
    update crm_private.b07_object_versions set state='present_unverified',revision=revision+1 where version_id=target;
   elsif m->>'action'='observe' then
    next_state:=case when m->>'presence'='missing' then 'missing'
     when m->>'presence'='present' and m->>'digest'=old.expected_digest and (m->>'size')::bigint=old.expected_size
      and m->>'media'=old.expected_media then case when old.linked_at is null then 'verified_unlinked' else 'stored' end
     when m->>'presence'='present' then 'inconsistent' else null end;
    if next_state is null then raise exception 'OBJECT_INPUT_INVALID'; end if;
    update crm_private.b07_object_versions set state=next_state,observed_digest=m->>'digest',
     observed_size=(m->>'size')::bigint,observed_media=m->>'media',observed_at=clock_timestamp(),revision=revision+1 where version_id=target;
   elsif m->>'action'='link' then
    if old.state not in ('verified_unlinked','stored') then raise exception 'OBJECT_STATE_INVALID'; end if;
    if m ? 'evidenceId' then
     if not exists(select 1 from crm_private.b07_records r join crm_private.b07_links l on l.record_id=r.record_id
      where r.record_id=(m->>'evidenceId')::uuid and r.record_kind='evidence' and r.admin_scope=scope
       and r.material->>'document_id'=old.document_id::text and l.admin_scope=scope
       and l.context_kind=m->>'contextKind' and l.context_id=(m->>'contextId')::uuid) then raise exception 'OBJECT_DENIED'; end if;
     if exists(select 1 from crm_private.b07_evidence_object_bindings b where b.evidence_id=(m->>'evidenceId')::uuid
      and b.version_id<>target) then raise exception 'OBJECT_HISTORICAL_BINDING_CONFLICT'; end if;
     insert into crm_private.b07_evidence_object_bindings(evidence_id,version_id,admin_scope,linked_by)
      values((m->>'evidenceId')::uuid,target,scope,actor) on conflict do nothing;
    end if;
    update crm_private.b07_object_versions set state='stored',linked_at=coalesce(linked_at,clock_timestamp()),revision=revision+1 where version_id=target;
   else raise exception 'OBJECT_INPUT_INVALID'; end if;
   select to_jsonb(o) into after_data from crm_private.b07_object_versions o where version_id=target;
  end if;
  if m->>'action'='link' and m ? 'evidenceId' then
   after_data:=after_data||jsonb_build_object('evidence_binding',
    (select to_jsonb(b) from crm_private.b07_evidence_object_bindings b where b.evidence_id=(m->>'evidenceId')::uuid));
  end if;
  insert into crm_private.b07_operations(operation_id,admin_scope,actor_id,fingerprint,result_ref) values(opid,scope,actor,fingerprint,target);
  insert into crm_private.b07_history(history_id,operation_id,subject_id,admin_scope,action_kind,before_state,after_state,reason,source_ref,actor_id)
   values(opid,opid,target,scope,'object_'||(m->>'action'),before_data,after_data,m->>'reason',m->>'sourceRef',actor);
  result_ref:=target;replayed:=false;
 end if;
 perform crm_f2.verify(f2p,f2s,q,'C03','human_evidence','write_evidence');
 perform crm_f1.verify_envelope(f1p,f1s,q,'C03','evidence','write_evidence');
 return next;
end $function$

CREATE OR REPLACE FUNCTION crm_api.b07_object_read(f2p bytea, f2s bytea, f1p bytea, f1s bytea, q bytea)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare hf text[];tf text[];v text[];m jsonb;result jsonb;
begin
 hf:=crm_f2.admit(f2p,f2s,q,'C01','read_evidence');
 tf:=crm_f1.verify_envelope(f1p,f1s,q,'C01','evidence','read_evidence');
 if hf[17] collate "C"<>tf[14] collate "C" then raise exception 'OBJECT_DENIED'; end if;
 v:=crm_f1.fields(q);if cardinality(v)<>2 or v[1]<>'CRM-H1-OBJECT-READ1' then raise exception 'OBJECT_INPUT_INVALID'; end if;
 m:=v[2]::jsonb;
 select to_jsonb(o)||jsonb_build_object('evidence_bindings',
  (select jsonb_agg(to_jsonb(b)) from crm_private.b07_evidence_object_bindings b where b.version_id=o.version_id
   and b.admin_scope=hf[17] and exists(select 1 from crm_private.b07_links el where el.record_id=b.evidence_id
    and el.admin_scope=hf[17] and el.context_kind=m->>'contextKind' and el.context_id=(m->>'contextId')::uuid)))
 into result from crm_private.b07_object_versions o
  where o.version_id=(m->>'versionId')::uuid and o.admin_scope=hf[17] and o.purpose=m->>'purpose'
   and exists(select 1 from crm_private.b07_links l where l.record_id=o.document_id and l.admin_scope=hf[17]
    and l.context_kind=m->>'contextKind' and l.context_id=(m->>'contextId')::uuid);
 perform crm_f2.verify(f2p,f2s,q,'C01','human_evidence','read_evidence');
 perform crm_f1.verify_envelope(f1p,f1s,q,'C01','evidence','read_evidence');return result;
end $function$

CREATE OR REPLACE FUNCTION crm_api.b07_read(f2p bytea, f2s bytea, f1p bytea, f1s bytea, q bytea)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare hf text[];tf text[];v text[];wanted_record uuid;wanted_context uuid;result jsonb;
begin
  hf:=crm_f2.admit(f2p,f2s,q,'C01','read_evidence');
  tf:=crm_f1.verify_envelope(f1p,f1s,q,'C01','evidence','read_evidence');
  if hf[17] collate "C" <> tf[14] collate "C" then
    raise exception 'B07_DENIED' using errcode='42501'; end if;
  v:=crm_f1.fields(q);
  if cardinality(v)<>4 or v[1]<>'CRM-H1-B07-READ1'
    or v[3] not in ('contact','organization','opportunity','booking','booking_service','provider','proposal','other')
  then raise exception 'B07_INPUT_INVALID' using errcode='22023'; end if;
  wanted_record:=v[2]::uuid;wanted_context:=v[4]::uuid;
  select jsonb_build_object('record',to_jsonb(r),
    'links',(select jsonb_agg(to_jsonb(l2) order by l2.linked_at,l2.link_id)
      from crm_private.b07_links l2 where l2.record_id=r.record_id
        and l2.admin_scope=hf[17] and l2.context_kind=v[3] and l2.context_id=wanted_context))
    into result from crm_private.b07_records r
    join crm_private.b07_links l on l.record_id=r.record_id
    where r.record_id=wanted_record and r.admin_scope=hf[17]
      and l.admin_scope=hf[17] and l.context_kind=v[3] and l.context_id=wanted_context;
  perform crm_f2.verify(f2p,f2s,q,'C01','human_evidence','read_evidence');
  perform crm_f1.verify_envelope(f1p,f1s,q,'C01','evidence','read_evidence');
  return result;
end $function$

CREATE OR REPLACE FUNCTION crm_api.b07_task_apply(f2p bytea, f2s bytea, f1p bytea, f1s bytea, q bytea)
 RETURNS TABLE(result_ref uuid, replayed boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare hf text[];tf text[];v text[];m jsonb;actor uuid;scope text;
begin
 hf:=crm_f2.admit(f2p,f2s,q,'C03','write_evidence');
