   approval:=a->'adjustment';select * into ps from crm_private.b05_payment_schedules where schedule_id=(approval->>'scheduleId')::uuid and booking_id=bid and admin_scope=s;
   if not found or not(ps.scope_kind='global' and ps.scope_id=bid or ps.scope_kind=(case a->'scope'->>'kind' when 'booking' then 'global' else a->'scope'->>'kind' end) and ps.scope_id=(a->'scope'->>'id')::uuid) then raise exception 'CANCELLATION_OBLIGATION_REQUIRED:E3';end if;
   if not crm_private.modification_proof((approval->>'approvalEvidenceId')::uuid,did,s,'cancellation:approve:'||encode(crm_crypto.digest(convert_to(jsonb_build_object('determination',old,'adjustment',approval-'approvalEvidenceId')::text,'UTF8'),'sha256'),'hex'),(a->>'at')::timestamptz) then raise exception 'CANCELLATION_APPROVAL_REQUIRED:E3';end if;
   select revision,snapshot into sr,before_schedule from crm_private.b05_schedule_revisions where schedule_id=ps.schedule_id order by revision desc limit 1;
   if sr<>(approval->>'expectedRevision')::bigint then raise exception 'CANCELLATION_REVISION_CONFLICT:E2';end if;
   if jsonb_typeof(approval->'parts') is distinct from 'array' or jsonb_array_length(approval->'parts')<>jsonb_array_length(before_schedule->'parts') then raise exception 'CANCELLATION_OBLIGATION_REQUIRED:E3';end if;
   select sum((value->>'amount')::numeric) into total from jsonb_array_elements(before_schedule->'parts');
   newtotal:=0;parts:='[]'::jsonb;
   for p in select value from jsonb_array_elements(approval->'parts') loop
    select value into part from jsonb_array_elements(before_schedule->'parts') where value->>'slot'=p->>'slot';
    if part is null or not crm_private.obligation_part_valid(p) or p->'due' is distinct from part->'due' or exists(select 1 from jsonb_array_elements(parts) z where z->>'slot'=p->>'slot') then raise exception 'CANCELLATION_OBLIGATION_REQUIRED:E3';end if;
    parts:=parts||jsonb_build_array(p);newtotal:=newtotal+(p->>'amount')::numeric;
   end loop;
   if total<(old->'computed'->>'baseTotal')::numeric or newtotal<>total-(old->'computed'->>'right')::numeric then raise exception 'CANCELLATION_AMOUNT_REQUIRED:E3';end if;
   after_schedule:=jsonb_set(before_schedule,'{parts}',parts);
   insert into crm_private.b05_schedule_revisions values(ps.schedule_id,sr+1,s,after_schedule,actor,clock_timestamp());
   for p in select value from jsonb_array_elements(parts) loop
    select value into part from jsonb_array_elements(before_schedule->'parts') where value->>'slot'=p->>'slot';
    insert into crm_private.b05_obligation_adjustments values(gen_random_uuid(),ps.schedule_id,p->>'slot',sr+1,s,part,p,(p->>'amount')::numeric-(part->>'amount')::numeric,actor,a->>'reason',a->>'sourceRef',(a->>'evidenceId')::uuid,clock_timestamp());
   end loop;
   insert into crm_private.b05_obligation_operations values(op,bid,s,actor,fp,a,jsonb_build_object('id',ps.schedule_id,'revision',sr+1,'determinationId',did),clock_timestamp());
   insert into crm_private.b05_obligation_history values(op,bid,s,actor,before_schedule,after_schedule,a->>'sourceRef',a->>'reason',(a->>'evidenceId')::uuid,(a->>'at')::timestamptz,clock_timestamp());
   insert into crm_private.b06_cancellation_applications values(op,did,rev,bid,s,a->'scope',root.start_quantity,root.quantity,ps.schedule_id,sr+1,(old->'computed'->>'right')::numeric,(old->'computed'->>'retention')::numeric,actor,(a->>'evidenceId')::uuid,clock_timestamp());
   state:=old||jsonb_build_object('revision',rev+1,'applied',true,'application',jsonb_build_object('scheduleId',ps.schedule_id,'scheduleRevision',sr+1,'before',before_schedule->'parts','after',parts,'movementExecuted',false));
  end if;
  insert into crm_private.b06_cancellation_operations values(op,did,s,actor,fp,state,rev+1,clock_timestamp());
  insert into crm_private.b06_cancellation_revisions values(did,rev+1,s,op,action,a,old,state,actor,(a->>'evidenceId')::uuid,a->>'sourceRef',a->>'reason',(a->>'at')::timestamptz,clock_timestamp());
  r:=jsonb_build_object('id',did,'replayed',false,'result',state);
 end if;
 perform crm_f2.verify(f2p,f2s,q,'C03','human_evidence','write_evidence');perform crm_f1.verify_envelope(f1p,f1s,q,'C03','evidence','write_evidence');return r;
end$function$

CREATE OR REPLACE FUNCTION crm_api.cancellation_read(f2p bytea, f2s bytea, f1p bytea, f1s bytea, q bytea)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare hf text[];tf text[];fs text[];a jsonb;r jsonb;b crm_private.b04_bookings;m jsonb;begin
 hf:=crm_f2.admit(f2p,f2s,q,'C01','read_evidence');tf:=crm_f1.verify_envelope(f1p,f1s,q,'C01','evidence','read_evidence');if hf[17] collate "C"<>tf[14] collate "C" then raise exception 'CANCELLATION_DENIED';end if;
 fs:=crm_f1.fields(q);if cardinality(fs)<>2 or fs[1]<>'CRM-H4-CANCELLATION-READ1' then raise exception 'CANCELLATION_INPUT_INVALID';end if;a:=fs[2]::jsonb;
 if a->>'purpose'='basis' then
  if a-array['bookingId','scope','purpose']<>'{}'::jsonb or not(a?&array['bookingId','scope','purpose']) or (a->'scope')-array['kind','id','serviceId']<>'{}'::jsonb or not(a->'scope'?&array['kind','id']) or a->'scope'->>'kind' not in('booking','modality','service','night') then raise exception 'CANCELLATION_INPUT_INVALID';end if;
  select * into b from crm_private.b04_bookings where booking_id=(a->>'bookingId')::uuid and admin_scope=hf[17];
  if found then m:=crm_private.cancellation_scope(a->'scope',b.booking_id,hf[17]);r:=jsonb_build_object('bookingId',b.booking_id,'scope',a->'scope','scopeToken',crm_private.cancellation_token(a->'scope',b.booking_id,hf[17]),'referenceDate',m->'date','acceptedVersion',b.version_id,'terms',b.terms,'participation',case when a->'scope'->>'kind'='modality' then jsonb_build_object('modalityId',a->'scope'->'id','amount',m->'modality'->>'final_person_price','quantity',m->'modality'->'participants','unit','participation') else null end);end if;
  perform crm_f2.verify(f2p,f2s,q,'C01','human_evidence','read_evidence');return r;
 end if;
 if a-array['bookingId','determinationId','purpose']<>'{}'::jsonb or not(a?&array['bookingId','determinationId','purpose']) or a->>'purpose' not in('history','right') then raise exception 'CANCELLATION_INPUT_INVALID';end if;
 select x.after_data into r from crm_private.b06_cancellation_determinations d join crm_private.b06_cancellation_revisions x using(determination_id) where d.booking_id=(a->>'bookingId')::uuid and d.determination_id=(a->>'determinationId')::uuid and d.admin_scope=hf[17] order by x.revision desc limit 1;
 if r is not null then
  if a->>'purpose'='right' then r:=jsonb_build_object('id',r->'id','revision',r->'revision','status',r->'computed'->'status','right',r->'computed'->'right','retention',r->'computed'->'retention','missing',r->'computed'->'missing','applied',r->'applied','currentlyApplicable',r->>'scopeToken'=crm_private.cancellation_token(r->'scope',(a->>'bookingId')::uuid,hf[17]));
  else r:=r||jsonb_build_object('history',(select jsonb_agg(to_jsonb(x) order by x.revision) from crm_private.b06_cancellation_revisions x where x.determination_id=(a->>'determinationId')::uuid));end if;
 end if;
 perform crm_f2.verify(f2p,f2s,q,'C01','human_evidence','read_evidence');return r;
end$function$

CREATE OR REPLACE FUNCTION crm_api.catalog_apply(f2p bytea, f2s bytea, f1p bytea, f1s bytea, q bytea)
 RETURNS TABLE(result_ref uuid, result_version bigint, replayed boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare hf text[]; tf text[]; v text[]; op crm_private.catalog_operations%rowtype;
  item crm_private.catalog_items%rowtype; endpoint crm_private.catalog_items%rowtype;
  rev crm_private.catalog_revisions%rowtype; parent_rev crm_private.catalog_revisions%rowtype;
  related_rev crm_private.catalog_revisions%rowtype;
  actor uuid; scope text; target uuid; parent uuid; related uuid; party uuid;
  expected bigint; next_version bigint; fingerprint text; before_state jsonb;
  after_state jsonb; result_id uuid; refs text[]; seen text[]:=array[]::text[];
  ref text; snapshot jsonb:='[]'::jsonb; definition jsonb;
begin
  hf:=crm_f2.admit(f2p,f2s,q,'C03','write_catalog');
  tf:=crm_f1.verify_envelope(f1p,f1s,q,'C03','catalog','write_catalog');
  if hf[17] collate "C" <> tf[14] collate "C" then
    raise exception 'CATALOG_DENIED' using errcode='42501'; end if;
  v:=crm_f1.fields(q);
  if cardinality(v)<>15 or v[1]<>'CRM-H1-CAT1'
    or v[2] not in ('create_item','publish_version','fix_application')
    or v[3] is null or v[4] is null or v[11] is null
    or v[12] is null or v[12]='' or v[13] is null or v[13]=''
    or v[14] !~ '^(0|[1-9][0-9]{0,18})$'
  then raise exception 'CATALOG_INPUT_INVALID' using errcode='22023'; end if;
  target:=v[4]::uuid; parent:=nullif(v[6],'')::uuid;
  related:=nullif(v[7],'')::uuid; party:=nullif(v[8],'')::uuid;
  actor:=hf[12]::uuid; scope:=hf[17]; expected:=v[14]::bigint;
  fingerprint:=encode(crm_crypto.digest(q,'sha256'),'hex');
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(v[3],0));
  select * into op from crm_private.catalog_operations where operation_id=v[3]::uuid;
  if found then
    if op.actor_id<>actor or op.admin_scope<>scope or op.material_fingerprint<>fingerprint then
      raise exception 'CATALOG_REPLAY_CONFLICT' using errcode='23505'; end if;
    perform crm_f2.verify(f2p,f2s,q,'C03','human_catalog','write_catalog');
    result_ref:=op.result_ref; result_version:=op.result_version;
    replayed:=true; return next; return;
  end if;
  if v[2]='create_item' then
    if expected<>0 or v[10]<>'{}' or v[15]<>'' or v[5] not in
      ('service','variant','category','attribute','audience','unit','pricing_form','provider',
       'offering','category_assignment','attribute_assignment','audience_recommendation',
       'unit_assignment','pricing_form_assignment')
    then raise exception 'CATALOG_INPUT_INVALID' using errcode='22023'; end if;
    if v[5] in ('service','category','attribute','audience','unit','pricing_form','provider') then
      if parent is not null or related is not null then
        raise exception 'CATALOG_RELATION_INVALID' using errcode='22023'; end if;
    elsif v[5]='variant' then
      if parent is null or related is not null then
        raise exception 'CATALOG_RELATION_INVALID' using errcode='22023'; end if;
    else
      if parent is null or related is null then
        raise exception 'CATALOG_RELATION_INVALID' using errcode='22023'; end if;
    end if;
    if v[5]<>'provider' and (party is not null or v[9]<>'') then
      raise exception 'CATALOG_RELATION_INVALID' using errcode='22023'; end if;
    if v[5]='provider' and (party is null)<>(v[9]='') then
      raise exception 'CATALOG_RELATION_INVALID' using errcode='22023'; end if;
    if party is not null and not exists(select 1 from crm_private.identity_entities e
      where e.identity_id=party and e.identity_kind=v[9] and e.admin_scope=scope
        and e.identity_verified and e.archived_at is null) then
      raise exception 'CATALOG_RELATION_INVALID' using errcode='22023'; end if;
    if parent is not null then
      select * into endpoint from crm_private.catalog_items where item_id=parent for share;
      if not found or endpoint.admin_scope<>scope or not (
        (v[5]='variant' and endpoint.item_kind='service') or
        (v[5]='offering' and endpoint.item_kind='provider') or
        (v[5] in ('category_assignment','attribute_assignment','audience_recommendation',
          'unit_assignment','pricing_form_assignment')
          and endpoint.item_kind in ('service','variant'))) then
        raise exception 'CATALOG_RELATION_INVALID' using errcode='22023'; end if;
    end if;
    if related is not null then
      select * into endpoint from crm_private.catalog_items where item_id=related for share;
      if not found or endpoint.admin_scope<>scope or not (
        (v[5]='offering' and endpoint.item_kind in ('service','variant')) or
        (v[5]='category_assignment' and endpoint.item_kind='category') or
        (v[5]='attribute_assignment' and endpoint.item_kind='attribute') or
        (v[5]='audience_recommendation' and endpoint.item_kind='audience') or
        (v[5]='unit_assignment' and endpoint.item_kind='unit') or
        (v[5]='pricing_form_assignment' and endpoint.item_kind='pricing_form')) then
        raise exception 'CATALOG_RELATION_INVALID' using errcode='22023'; end if;
    end if;
    insert into crm_private.catalog_items(item_id,item_kind,admin_scope,parent_id,related_id,
      party_id,party_kind,source_ref,evidence_ref,created_by)
      values(target,v[5],scope,parent,related,party,nullif(v[9],''),v[11],v[12],actor);
    select to_jsonb(i) into after_state from crm_private.catalog_items i where i.item_id=target;
    result_id:=target; next_version:=0;
  elsif v[2]='publish_version' then
    if party is not null or v[9]<>'' or v[15]<>'' then
      raise exception 'CATALOG_INPUT_INVALID' using errcode='22023'; end if;
    select * into item from crm_private.catalog_items i where i.item_id=target for update;
    if not found or item.admin_scope<>scope or item.item_kind<>v[5] then
      raise exception 'CATALOG_DENIED' using errcode='42501'; end if;
    select coalesce(max(revision_number),0) into next_version
      from crm_private.catalog_revisions where item_id=target;
    if next_version<>expected then
      raise exception 'CATALOG_VERSION_CONFLICT' using errcode='40001'; end if;
    definition:=v[10]::jsonb;
    if not crm_private.catalog_definition_valid(item.item_kind,definition) then
      raise exception 'CATALOG_DEFINITION_INVALID' using errcode='22023'; end if;
    if item.parent_id is null and parent is not null
      or item.parent_id is not null and parent is null
      or item.related_id is null and related is not null
      or item.related_id is not null and related is null then
      raise exception 'CATALOG_RELATION_INVALID' using errcode='22023'; end if;
    if parent is not null then
      select * into parent_rev from crm_private.catalog_revisions r where r.revision_id=parent;
      if not found or parent_rev.item_id<>item.parent_id or parent_rev.admin_scope<>scope then
        raise exception 'CATALOG_RELATION_INVALID' using errcode='22023'; end if;
    end if;
    if related is not null then
      select * into related_rev from crm_private.catalog_revisions r where r.revision_id=related;
      if not found or related_rev.item_id<>item.related_id or related_rev.admin_scope<>scope then
        raise exception 'CATALOG_RELATION_INVALID' using errcode='22023'; end if;
    end if;
    select to_jsonb(r) into before_state from crm_private.catalog_revisions r
      where r.item_id=target order by r.revision_number desc limit 1;
    insert into crm_private.catalog_revisions(revision_id,item_id,admin_scope,revision_number,
      definition,parent_revision_id,related_revision_id,source_ref,evidence_ref,reason,actor_id)
      values(v[3]::uuid,target,scope,next_version+1,definition,parent,related,
        v[11],v[12],v[13],actor);
    next_version:=next_version+1; result_id:=v[3]::uuid;
    select jsonb_build_object('revision',to_jsonb(r),'item',to_jsonb(i))
      into after_state from crm_private.catalog_revisions r
      join crm_private.catalog_items i on i.item_id=r.item_id
      where r.revision_id=result_id;
  else
    if v[5]<>'application' or parent is null or related is not null
      or party is not null or v[9]<>'' or v[10]<>'{}' or expected<>0
    then raise exception 'CATALOG_INPUT_INVALID' using errcode='22023'; end if;
    refs:=string_to_array(v[15],',');
    if refs is null or cardinality(refs)<1 or cardinality(refs)>50 then
      raise exception 'CATALOG_INPUT_INVALID' using errcode='22023'; end if;
    foreach ref in array refs loop
      if ref !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
        or ref=any(seen) then
        raise exception 'CATALOG_INPUT_INVALID' using errcode='22023'; end if;
      seen:=array_append(seen,ref);
      select * into rev from crm_private.catalog_revisions r where r.revision_id=ref::uuid;
      if not found or rev.admin_scope<>scope then
        raise exception 'CATALOG_RELATION_INVALID' using errcode='22023'; end if;
      select * into item from crm_private.catalog_items i where i.item_id=rev.item_id;
      snapshot:=snapshot || jsonb_build_array(jsonb_build_object(
        'revision',to_jsonb(rev),'item',to_jsonb(item)));
    end loop;
    insert into crm_private.catalog_applications(application_id,subject_ref,admin_scope,
      applied_revisions,source_ref,evidence_ref,reason,actor_id)
      values(target,parent,scope,snapshot,v[11],v[12],v[13],actor);
    select to_jsonb(a) into after_state from crm_private.catalog_applications a
      where a.application_id=target;
    result_id:=target; next_version:=0;
  end if;
  insert into crm_private.catalog_operations(operation_id,admin_scope,actor_id,
    material_fingerprint,action_kind,result_ref,result_version)
    values(v[3]::uuid,scope,actor,fingerprint,v[2],result_id,next_version);
  insert into crm_private.catalog_history(history_id,operation_id,subject_id,admin_scope,
    before_state,after_state,source_ref,evidence_ref,reason,actor_id)
    values(v[3]::uuid,v[3]::uuid,target,scope,before_state,after_state,
      v[11],v[12],v[13],actor);
  perform crm_f2.verify(f2p,f2s,q,'C03','human_catalog','write_catalog');
  perform crm_f1.verify_envelope(f1p,f1s,q,'C03','catalog','write_catalog');
  result_ref:=result_id; result_version:=next_version; replayed:=false; return next;
end $function$

CREATE OR REPLACE FUNCTION crm_api.catalog_read(f2p bytea, f2s bytea, f1p bytea, f1s bytea, q bytea)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare hf text[]; tf text[]; v text[]; target uuid; output jsonb;
  page_limit integer; page_offset integer; total integer; next_page text;
begin
  hf:=crm_f2.admit(f2p,f2s,q,'C01','read_catalog');
  tf:=crm_f1.verify_envelope(f1p,f1s,q,'C01','catalog','read_catalog');
  if hf[17] collate "C" <> tf[14] collate "C" then
    raise exception 'CATALOG_DENIED' using errcode='42501'; end if;
  v:=crm_f1.fields(q);
  if cardinality(v)<>5 or v[1]<>'CRM-H1-CAT-READ1'
    or v[2] not in ('item','version','application','history')
    or v[4] !~ '^[1-9][0-9]{0,2}$' or v[5] !~ '^(0|[1-9][0-9]{0,8})$'
  then raise exception 'CATALOG_INPUT_INVALID' using errcode='22023'; end if;
  target:=v[3]::uuid; page_limit:=v[4]::integer; page_offset:=v[5]::integer;
  if page_limit>100 then raise exception 'CATALOG_INPUT_INVALID' using errcode='22023'; end if;
  if v[2]='item' then
    select jsonb_build_object('item',to_jsonb(i),'latest_revision',to_jsonb(r))
      into output from crm_private.catalog_items i
      left join lateral (select * from crm_private.catalog_revisions r
        where r.item_id=i.item_id order by r.revision_number desc limit 1) r on true
      where i.item_id=target and i.admin_scope=hf[17];
  elsif v[2]='version' then
    select jsonb_build_object('revision',to_jsonb(r),'item',to_jsonb(i))
      into output from crm_private.catalog_revisions r
      join crm_private.catalog_items i on i.item_id=r.item_id
      where r.revision_id=target and r.admin_scope=hf[17];
  elsif v[2]='application' then
    select to_jsonb(a) into output from crm_private.catalog_applications a
      where a.application_id=target and a.admin_scope=hf[17];
  else
    select coalesce(jsonb_agg(to_jsonb(h) order by h.recorded_at,h.history_id),'[]'::jsonb)
      into output from crm_private.catalog_history h
      where h.subject_id=target and h.admin_scope=hf[17];
  end if;
  if v[2]='history' then
    total:=jsonb_array_length(output);
    select coalesce(jsonb_agg(x.value order by x.ordinality),'[]'::jsonb) into output
      from jsonb_array_elements(output) with ordinality x(value,ordinality)
      where x.ordinality>page_offset and x.ordinality<=page_offset+page_limit;
    next_page:=case when page_offset+page_limit<total
      then (page_offset+page_limit)::text else null end;
  else
    if page_offset<>0 then raise exception 'CATALOG_INPUT_INVALID' using errcode='22023'; end if;
    next_page:=null;
  end if;
  perform crm_f2.verify(f2p,f2s,q,'C01','human_catalog','read_catalog');
  perform crm_f1.verify_envelope(f1p,f1s,q,'C01','catalog','read_catalog');
  return jsonb_build_object('data',output,'nextPage',next_page);
end $function$

CREATE OR REPLACE FUNCTION crm_api.closure_apply(f2p bytea, f2s bytea, f1p bytea, f1s bytea, q bytea)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare hf text[];tf text[];fs text[];a jsonb;bid uuid;op uuid;s text;actor uuid;fp text;prior crm_private.b06_closure_operations;i jsonb;v jsonb;r jsonb;rev bigint;basis jsonb;old jsonb;conflict_constraint text;begin
 hf:=crm_f2.admit(f2p,f2s,q,'C03','write_evidence');tf:=crm_f1.verify_envelope(f1p,f1s,q,'C03','evidence','write_evidence');
 if hf[17]collate "C" is distinct from tf[14]collate "C" then raise exception 'CLOSURE_DENIED';end if;
 s:=hf[17];actor:=hf[12]::uuid;fs:=crm_f1.fields(q);
 if cardinality(fs)<>2 or fs[1]<>'CRM-H5-CLOSURE1'then raise exception 'CLOSURE_INPUT_INVALID';end if;a:=fs[2]::jsonb;
 if jsonb_typeof(a)is distinct from'object'or not(a?&array['action','operationId','bookingId','dimension','expectedRevision','expectedMaterial','sourceRef','reason','at','evidenceId','criteria','documentDependencies','serviceApplicability'])or a-array['action','operationId','bookingId','dimension','expectedRevision','expectedMaterial','sourceRef','reason','at','evidenceId','criteria','documentDependencies','serviceApplicability']<>'{}'::jsonb or coalesce(a->>'action','')not in('open','evaluate','reopen')or coalesce(a->>'dimension','')not in('commercial','operational','economic')or not coalesce(crm_private.invoice_text(a->'sourceRef'),false)or not coalesce(crm_private.invoice_text(a->'reason'),false)or not coalesce(crm_private.availability_time(a->'at'),false)or coalesce(a->>'expectedRevision','')!~'^[0-9]+$'or jsonb_typeof(a->'serviceApplicability')is distinct from'array'then raise exception 'CLOSURE_INPUT_INVALID';end if;
 bid:=(a->>'bookingId')::uuid;op:=(a->>'operationId')::uuid;
 -- Authorize the Booking even on replay, then serialize before any material reads.
 if not exists(select 1 from crm_private.b04_bookings where booking_id=bid and admin_scope=s)then raise exception 'CLOSURE_DENIED';end if;
 perform crm_private.booking_preparation_lock(bid);fp:=crm_private.booking_preparation_hash(a);
 select *into prior from crm_private.b06_closure_operations where operation_id=op;
 if found then
  if prior.booking_id<>bid or prior.admin_scope<>s or prior.actor_id<>actor or prior.fingerprint<>fp then raise exception 'CLOSURE_REPLAY_CONFLICT:E2';end if;
  r:=prior.result||jsonb_build_object('replayed',true);
 else
  if not coalesce(crm_private.payment_evidence((a->>'evidenceId')::uuid,bid,s,'closure:'||crm_private.booking_preparation_hash(a-array['operationId','evidenceId']),(a->>'at')::timestamptz,true),false)or not exists(select 1 from crm_private.b07_records where record_id=(a->>'evidenceId')::uuid and recorded_by=actor)then raise exception 'CLOSURE_EVIDENCE_REQUIRED:E3';end if;
  i:=crm_private.closure_inputs(bid,s);select count(*)into rev from crm_private.b06_closure_assessments where booking_id=bid and admin_scope=s;
  if rev<>(a->>'expectedRevision')::bigint or a->>'expectedMaterial'is distinct from crm_private.booking_preparation_hash(i)then raise exception 'CLOSURE_MATERIAL_CONFLICT:E2';end if;
  select state into old from crm_private.b06_closure_assessments where booking_id=bid and admin_scope=s and dimension=a->>'dimension'order by revision desc limit 1;
  if a->>'action'='evaluate'and old is null then raise exception 'CLOSURE_OPEN_REQUIRED:E3';end if;

  if a->>'action'='reopen' then
   perform crm_private.closure_invalidate(bid,jsonb_build_object('sourceTable','explicit-reopening','sourceRecord',a,'actorId',actor));
   if old->>'status'is distinct from'Resuelto' then raise exception 'CLOSURE_NOT_RESOLVED:E3';end if;
   if not exists(select 1 from crm_private.b06_closure_invalidations where booking_id=bid and assessment_revision=(old->>'revision')::bigint)then raise exception 'CLOSURE_REOPEN_UNFOUNDED:E3';end if;
  elsif old->>'status'='Resuelto'then raise exception 'CLOSURE_REOPEN_RESERVED:E3';end if;

  v:=crm_private.closure_assess(i,case when a->>'action'='reopen'then a||jsonb_build_object('action','open')else a end);basis:=crm_private.closure_basis(i,a->>'dimension',a);
  v:=v||jsonb_build_object('dimension',a->'dimension','revision',rev+1,'basis',basis,'basisHash',crm_private.booking_preparation_hash(basis),'actorId',actor,'at',a->'at','evidenceId',a->'evidenceId','reason',a->'reason','sourceRef',a->'sourceRef');
  insert into crm_private.b06_closure_assessments values(bid,rev+1,a->>'dimension',s,op,a,v,actor,(a->>'evidenceId')::uuid,clock_timestamp());
  r:=jsonb_build_object('id',bid,'replayed',false,'result',v);
  insert into crm_private.b06_closure_operations values(op,bid,s,actor,fp,r,clock_timestamp());
 end if;
 perform crm_f2.verify(f2p,f2s,q,'C03','human_evidence','write_evidence');perform crm_f1.verify_envelope(f1p,f1s,q,'C03','evidence','write_evidence');return r;
exception when unique_violation then
 get stacked diagnostics conflict_constraint=CONSTRAINT_NAME;
 if conflict_constraint in('b06_closure_assessments_operation_id_key','b06_closure_operations_pkey')then raise exception 'CLOSURE_REPLAY_CONFLICT:E2';end if;
 raise;
end$function$

CREATE OR REPLACE FUNCTION crm_api.closure_joint_apply(f2p bytea, f2s bytea, f1p bytea, f1s bytea, q bytea)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare hf text[];tf text[];fs text[];a jsonb;bid uuid;op uuid;s text;actor uuid;fp text;prior crm_private.b06_closure_operations;i jsonb;v jsonb;r jsonb;rev bigint;basis jsonb;view jsonb;d text;assessment record;results jsonb:='{}';conflict_constraint text;begin
 hf:=crm_f2.admit(f2p,f2s,q,'C03','write_evidence');tf:=crm_f1.verify_envelope(f1p,f1s,q,'C03','evidence','write_evidence');
 if hf[17]collate "C" is distinct from tf[14]collate "C" then raise exception 'CLOSURE_DENIED';end if;
 s:=hf[17];actor:=hf[12]::uuid;fs:=crm_f1.fields(q);
 if cardinality(fs)<>2 or fs[1]<>'CRM-H5-CLOSURE1'then raise exception 'CLOSURE_INPUT_INVALID';end if;a:=fs[2]::jsonb;
 if jsonb_typeof(a)is distinct from'object' or not(a?&array['action','operationId','bookingId','expectedRevision','expectedMaterial','expectedJointRevision','sourceRef','reason','at','evidenceId']) or a-array['action','operationId','bookingId','expectedRevision','expectedMaterial','expectedJointRevision','sourceRef','reason','at','evidenceId']<>'{}'::jsonb or a->>'action'is distinct from'close' or not coalesce(crm_private.invoice_text(a->'sourceRef'),false)or not coalesce(crm_private.invoice_text(a->'reason'),false)or not coalesce(crm_private.availability_time(a->'at'),false)or coalesce(a->>'expectedRevision','')!~'^[0-9]+$'or coalesce(a->>'expectedJointRevision','')!~'^[0-9]+$'then raise exception 'CLOSURE_INPUT_INVALID';end if;
 bid:=(a->>'bookingId')::uuid;op:=(a->>'operationId')::uuid;
 if not exists(select 1 from crm_private.b04_bookings where booking_id=bid and admin_scope=s)then raise exception 'CLOSURE_DENIED';end if;
 perform crm_private.booking_preparation_lock(bid);fp:=crm_private.booking_preparation_hash(a);
 select *into prior from crm_private.b06_closure_operations where operation_id=op;
 if found then
  if prior.booking_id<>bid or prior.admin_scope<>s or prior.actor_id<>actor or prior.fingerprint<>fp then raise exception 'CLOSURE_REPLAY_CONFLICT:E2';end if;
  r:=prior.result||jsonb_build_object('replayed',true);
 else
  if not coalesce(crm_private.payment_evidence((a->>'evidenceId')::uuid,bid,s,'closure:'||crm_private.booking_preparation_hash(a-array['operationId','evidenceId']),(a->>'at')::timestamptz,true),false)or not exists(select 1 from crm_private.b07_records where record_id=(a->>'evidenceId')::uuid and recorded_by=actor)then raise exception 'CLOSURE_EVIDENCE_REQUIRED:E3';end if;
  view:=crm_private.closure_read_core(bid,s);i:=view->'inputs';rev:=(view->'jointClosure'->>'revision')::bigint;
  if (view->>'revision')::bigint<>(a->>'expectedRevision')::bigint or a->>'expectedMaterial'is distinct from view->>'material' or rev<>(a->>'expectedJointRevision')::bigint then raise exception 'CLOSURE_MATERIAL_CONFLICT:E2';end if;
  if view->'jointClosure'->'current'='true'::jsonb then raise exception 'CLOSURE_ALREADY_CLOSED:E2';end if;
  foreach d in array array['commercial','operational','economic']loop
   if view->'assessments'->d->>'currentStatus'is distinct from'Resuelto' then raise exception 'CLOSURE_DIMENSION_PENDING:E3:%',d;end if;
   select *into assessment from crm_private.b06_closure_assessments where booking_id=bid and admin_scope=s and dimension=d order by revision desc limit 1;
   v:=crm_private.closure_assess(i,assessment.command);
   if v->>'status'is distinct from'Resuelto' then raise exception 'CLOSURE_DIMENSION_PENDING:E3:%',d;end if;
   results:=results||jsonb_build_object(d,assessment.state);
  end loop;
  -- BR-INC-002/SM-CL-04 applies to every open critical incident, beyond the
  -- dimension-specific materiality filters of the H5-013 evaluator.
  if exists(select 1 from jsonb_array_elements(i->'incidents')x where x->>'severity'='Crítica'and x->>'status'in('Abierta','En gestión')and
   (x->'justification'->>'purpose'is distinct from'complete-close' or not coalesce(crm_private.invoice_text(x->'justification'->'basis'),false)or x->'justification'->>'actorId'is null or x->'justification'->>'evidenceId'is null))then raise exception 'CLOSURE_CRITICAL_INCIDENT:E3';end if;
  v:=jsonb_build_object('status','Cerrada / Histórico','bookingId',bid,'revision',rev+1,'assessments',results,'basis',i,'basisHash',view->'material','actorId',actor,'at',a->'at','evidenceId',a->'evidenceId','sourceRef',a->'sourceRef','reason',a->'reason');
  insert into crm_private.b06_joint_closures values(bid,rev+1,s,op,v,actor,(a->>'evidenceId')::uuid,clock_timestamp());
  r:=jsonb_build_object('id',bid,'replayed',false,'result',v);
  insert into crm_private.b06_closure_operations values(op,bid,s,actor,fp,r,clock_timestamp());
 end if;
 perform crm_f2.verify(f2p,f2s,q,'C03','human_evidence','write_evidence');perform crm_f1.verify_envelope(f1p,f1s,q,'C03','evidence','write_evidence');return r;
exception when unique_violation then
 get stacked diagnostics conflict_constraint=CONSTRAINT_NAME;
 if conflict_constraint in('b06_joint_closures_operation_id_key','b06_closure_operations_pkey')then raise exception 'CLOSURE_REPLAY_CONFLICT:E2';end if;
 raise;
end$function$

CREATE OR REPLACE FUNCTION crm_api.closure_read(f2p bytea, f2s bytea, f1p bytea, f1s bytea, q bytea)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare hf text[];tf text[];fs text[];a jsonb;r jsonb;begin
 hf:=crm_f2.admit(f2p,f2s,q,'C01','read_evidence');tf:=crm_f1.verify_envelope(f1p,f1s,q,'C01','evidence','read_evidence');
 if hf[17]collate "C" is distinct from tf[14]collate "C"then raise exception 'CLOSURE_DENIED';end if;
 fs:=crm_f1.fields(q);if cardinality(fs)<>2 or fs[1]<>'CRM-H5-CLOSURE-READ1'then raise exception 'CLOSURE_INPUT_INVALID';end if;a:=fs[2]::jsonb;
 if not(a?'bookingId')or a-'bookingId'<>'{}'::jsonb then raise exception 'CLOSURE_INPUT_INVALID';end if;
