end$function$

CREATE OR REPLACE FUNCTION crm_api.commercial_apply(f2p bytea, f2s bytea, f1p bytea, f1s bytea, q bytea)
 RETURNS TABLE(result_ref uuid, result_version bigint, replayed boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare hf text[]; tf text[]; v text[]; op crm_private.commercial_operations%rowtype;
  item crm_private.commercial_items%rowtype; catalog_item crm_private.catalog_items%rowtype;
  catalog_rev crm_private.catalog_revisions%rowtype; prior crm_private.commercial_revisions%rowtype;
  rev crm_private.commercial_revisions%rowtype; source_item crm_private.commercial_items%rowtype;
  actor uuid; scope text; target uuid; linked_item uuid; linked_rev uuid; origin uuid;
  expected bigint; next_version bigint; fingerprint text; before_state jsonb;
  after_state jsonb; result_id uuid; definition jsonb; snapshot jsonb:='[]'::jsonb;
  component jsonb; unit_id uuid; refs text[]; seen text[]:=array[]::text[];
  ref text; ref_kind text;
  start_value text; end_value text; validity_kind_value text;
begin
  hf:=crm_f2.admit(f2p,f2s,q,'C03','write_catalog');
  tf:=crm_f1.verify_envelope(f1p,f1s,q,'C03','catalog','write_catalog');
  if hf[17] collate "C" <> tf[14] collate "C" then
    raise exception 'COMMERCIAL_DENIED' using errcode='42501'; end if;
  v:=crm_f1.fields(q);
  if cardinality(v)<>16 or v[1]<>'CRM-H1-COM1'
    or v[2] not in ('create','publish','fix_application','promote_custom')
    or v[3] is null or v[4] is null or v[13] is null or v[13]=''
    or v[14] is null or v[14]='' or v[15] is null or v[15]=''
    or v[16] !~ '^(0|[1-9][0-9]{0,18})$'
  then raise exception 'COMMERCIAL_INPUT_INVALID' using errcode='22023'; end if;
  target:=v[4]::uuid; linked_item:=nullif(v[6],'')::uuid;
  linked_rev:=nullif(v[7],'')::uuid; origin:=nullif(v[8],'')::uuid;
  actor:=hf[12]::uuid; scope:=hf[17]; expected:=v[16]::bigint;
  fingerprint:=encode(crm_crypto.digest(q,'sha256'),'hex');
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(v[3],0));
  select * into op from crm_private.commercial_operations where operation_id=v[3]::uuid;
  if found then
    if op.actor_id<>actor or op.admin_scope<>scope or op.fingerprint<>fingerprint then
      raise exception 'COMMERCIAL_REPLAY_CONFLICT' using errcode='23505'; end if;
    perform crm_f2.verify(f2p,f2s,q,'C03','human_catalog','write_catalog');
    result_ref:=op.result_ref; result_version:=op.result_version;
    replayed:=true; return next; return;
  end if;
  if v[2]='create' then
    if expected<>0 or v[9]<>'{}' or v[7]<>'' or v[8]<>'' or v[10]<>'' or v[11]<>'' or v[12]<>''
      or v[5] not in ('tariff','pack','custom_pack','promotion','capacity_rule','eligibility_rule','document_requirement')
    then raise exception 'COMMERCIAL_INPUT_INVALID' using errcode='22023'; end if;
    if (v[5] in ('pack','custom_pack','promotion'))<>(linked_item is null) then
      raise exception 'COMMERCIAL_RELATION_INVALID' using errcode='22023'; end if;
    if linked_item is not null then
      select * into catalog_item from crm_private.catalog_items where item_id=linked_item for share;
      if not found or catalog_item.admin_scope<>scope or catalog_item.item_kind not in
        ('service','variant','offering','provider')
        or (v[5] in ('tariff','capacity_rule','eligibility_rule') and catalog_item.item_kind='provider')
      then raise exception 'COMMERCIAL_RELATION_INVALID' using errcode='22023'; end if;
    end if;
    insert into crm_private.commercial_items(item_id,item_kind,admin_scope,catalog_item_id,
      source_ref,evidence_ref,created_by)
      values(target,v[5],scope,linked_item,v[13],v[14],actor);
    select to_jsonb(i) into after_state from crm_private.commercial_items i where i.item_id=target;
    result_id:=target; next_version:=0;
  elsif v[2]='publish' then
    if v[8]<>'' or v[5]='application' or v[12]<>'' then
      raise exception 'COMMERCIAL_INPUT_INVALID' using errcode='22023'; end if;
    select * into item from crm_private.commercial_items i where i.item_id=target for update;
    if not found or item.admin_scope<>scope or item.item_kind<>v[5]
      or item.catalog_item_id is distinct from linked_item then
      raise exception 'COMMERCIAL_DENIED' using errcode='42501'; end if;
    select coalesce(max(revision_number),0) into next_version
      from crm_private.commercial_revisions where item_id=target;
    if next_version<>expected then
      raise exception 'COMMERCIAL_VERSION_CONFLICT' using errcode='40001'; end if;
    definition:=v[9]::jsonb;
    if not crm_private.commercial_definition_valid(item.item_kind,definition) then
      raise exception 'COMMERCIAL_DEFINITION_INVALID' using errcode='22023'; end if;
    start_value:=nullif(v[10],''); end_value:=nullif(v[11],'');
    validity_kind_value:=case when start_value is null and end_value is null then 'unknown'
      when coalesce(start_value,end_value) ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' then 'civil_date'
      else 'instant' end;
    if validity_kind_value='civil_date' then
      if (start_value is not null and start_value !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$')
        or (end_value is not null and end_value !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$')
        or (start_value is not null and end_value is not null
          and start_value::date>end_value::date) then
        raise exception 'COMMERCIAL_VALIDITY_INVALID' using errcode='22023'; end if;
    elsif validity_kind_value='instant' then
      if (start_value is not null and start_value !~
          '^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}(\.[0-9]+)?(Z|[+-][0-9]{2}:[0-9]{2})$')
        or (end_value is not null and end_value !~
          '^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}(\.[0-9]+)?(Z|[+-][0-9]{2}:[0-9]{2})$')
        or (start_value is not null and end_value is not null
          and start_value::timestamptz>end_value::timestamptz) then
        raise exception 'COMMERCIAL_VALIDITY_INVALID' using errcode='22023'; end if;
    end if;
    if linked_item is null and linked_rev is not null
      or linked_item is not null and linked_rev is null then
      raise exception 'COMMERCIAL_RELATION_INVALID' using errcode='22023'; end if;
    if linked_rev is not null then
      select * into catalog_rev from crm_private.catalog_revisions where revision_id=linked_rev;
      if not found or catalog_rev.item_id<>linked_item or catalog_rev.admin_scope<>scope then
        raise exception 'COMMERCIAL_RELATION_INVALID' using errcode='22023'; end if;
      select * into catalog_item from crm_private.catalog_items where item_id=linked_item;
      snapshot:=snapshot || jsonb_build_array(jsonb_build_object(
        'role','scope','revision',to_jsonb(catalog_rev),'item',to_jsonb(catalog_item)));
    end if;
    if item.item_kind='tariff' then
      for ref,ref_kind in select value,case ordinality when 1 then 'unit'
        else 'pricing_form' end from jsonb_array_elements_text(jsonb_build_array(
        definition->>'unit_revision_id',definition->>'pricing_form_revision_id'))
        with ordinality loop
        if ref is null then continue; end if;
        select * into catalog_rev from crm_private.catalog_revisions where revision_id=ref::uuid;
        if not found or catalog_rev.admin_scope<>scope then
          raise exception 'COMMERCIAL_RELATION_INVALID' using errcode='22023'; end if;
        select * into catalog_item from crm_private.catalog_items where item_id=catalog_rev.item_id;
        if catalog_item.item_kind<>ref_kind then
          raise exception 'COMMERCIAL_RELATION_INVALID' using errcode='22023'; end if;
        snapshot:=snapshot || jsonb_build_array(jsonb_build_object(
          'role',catalog_item.item_kind,'revision',to_jsonb(catalog_rev),'item',to_jsonb(catalog_item)));
      end loop;
      if definition ? 'tiers' then
        for component in select value from jsonb_array_elements(definition->'tiers') loop
          for ref,ref_kind in select value,case ordinality when 1 then 'unit'
            else 'variant' end from jsonb_array_elements_text(jsonb_build_array(
            component->>'unit_revision_id',component->>'variant_revision_id'))
            with ordinality loop
            if ref is null then continue; end if;
            select * into catalog_rev from crm_private.catalog_revisions where revision_id=ref::uuid;
            if not found or catalog_rev.admin_scope<>scope then
              raise exception 'COMMERCIAL_RELATION_INVALID' using errcode='22023'; end if;
            select * into catalog_item from crm_private.catalog_items where item_id=catalog_rev.item_id;
            if catalog_item.item_kind<>ref_kind then
              raise exception 'COMMERCIAL_RELATION_INVALID' using errcode='22023'; end if;
            snapshot:=snapshot || jsonb_build_array(jsonb_build_object(
              'role','tier_'||catalog_item.item_kind,'revision',to_jsonb(catalog_rev),
              'item',to_jsonb(catalog_item)));
          end loop;
        end loop;
      end if;
    elsif item.item_kind in ('pack','custom_pack') then
      for component in select value from jsonb_array_elements(definition->'components') loop
        select * into catalog_rev from crm_private.catalog_revisions
          where revision_id=(component->>'service_revision_id')::uuid;
        if not found or catalog_rev.admin_scope<>scope then
          raise exception 'COMMERCIAL_RELATION_INVALID' using errcode='22023'; end if;
        select * into catalog_item from crm_private.catalog_items where item_id=catalog_rev.item_id;
        if catalog_item.item_kind not in ('service','variant') then
          raise exception 'COMMERCIAL_RELATION_INVALID' using errcode='22023'; end if;
        snapshot:=snapshot || jsonb_build_array(jsonb_build_object(
          'role','component','revision',to_jsonb(catalog_rev),'item',to_jsonb(catalog_item),
          'quantity',component->>'quantity','included',component->'included'));
        if component ? 'unit_revision_id' then
          unit_id:=(component->>'unit_revision_id')::uuid;
          select * into catalog_rev from crm_private.catalog_revisions where revision_id=unit_id;
          if not found or catalog_rev.admin_scope<>scope then
            raise exception 'COMMERCIAL_RELATION_INVALID' using errcode='22023'; end if;
          select * into catalog_item from crm_private.catalog_items where item_id=catalog_rev.item_id;
          if catalog_item.item_kind<>'unit' then
            raise exception 'COMMERCIAL_RELATION_INVALID' using errcode='22023'; end if;
          snapshot:=snapshot || jsonb_build_array(jsonb_build_object(
            'role','component_unit','revision',to_jsonb(catalog_rev),'item',to_jsonb(catalog_item)));
        end if;
      end loop;
    elsif item.item_kind='capacity_rule' and definition ? 'unit_revision_id' then
      unit_id:=(definition->>'unit_revision_id')::uuid;
      select * into catalog_rev from crm_private.catalog_revisions
        where revision_id=unit_id;
      if not found or catalog_rev.admin_scope<>scope then
        raise exception 'COMMERCIAL_RELATION_INVALID' using errcode='22023'; end if;
      select * into catalog_item from crm_private.catalog_items where item_id=catalog_rev.item_id;
      if catalog_item.item_kind<>'unit' then
        raise exception 'COMMERCIAL_RELATION_INVALID' using errcode='22023'; end if;
      snapshot:=snapshot || jsonb_build_array(jsonb_build_object(
        'role','capacity_unit','revision',to_jsonb(catalog_rev),'item',to_jsonb(catalog_item)));
    end if;
    select to_jsonb(r) into before_state from crm_private.commercial_revisions r
      where r.item_id=target order by r.revision_number desc limit 1;
    insert into crm_private.commercial_revisions(revision_id,item_id,admin_scope,revision_number,
      definition,catalog_snapshot,validity_kind,valid_from,valid_until,source_ref,evidence_ref,reason,actor_id)
      values(v[3]::uuid,target,scope,next_version+1,definition,snapshot,validity_kind_value,start_value,end_value,
        v[13],v[14],v[15],actor);
    next_version:=next_version+1; result_id:=v[3]::uuid;
    select jsonb_build_object('revision',to_jsonb(r),'item',to_jsonb(i)) into after_state
      from crm_private.commercial_revisions r join crm_private.commercial_items i using(item_id)
      where r.revision_id=result_id;
  elsif v[2]='promote_custom' then
    if v[5]<>'pack' or linked_item is not null or linked_rev is not null or origin is null
      or v[9]<>'{}' or v[10]<>'' or v[11]<>'' or v[12]<>'' or expected<>0 then
      raise exception 'COMMERCIAL_INPUT_INVALID' using errcode='22023'; end if;
    select * into prior from crm_private.commercial_revisions where revision_id=origin;
    if not found or prior.admin_scope<>scope then
      raise exception 'COMMERCIAL_RELATION_INVALID' using errcode='22023'; end if;
    select * into source_item from crm_private.commercial_items where item_id=prior.item_id;
    if source_item.item_kind<>'custom_pack' then
      raise exception 'COMMERCIAL_RELATION_INVALID' using errcode='22023'; end if;
    insert into crm_private.commercial_items(item_id,item_kind,admin_scope,origin_custom_revision_id,
      source_ref,evidence_ref,created_by)
      values(target,'pack',scope,origin,v[13],v[14],actor);
    insert into crm_private.commercial_revisions(revision_id,item_id,admin_scope,revision_number,
      definition,catalog_snapshot,validity_kind,valid_from,valid_until,source_ref,evidence_ref,reason,actor_id)
      values(v[3]::uuid,target,scope,1,prior.definition,prior.catalog_snapshot,
        prior.validity_kind,prior.valid_from,prior.valid_until,v[13],v[14],v[15],actor);
    result_id:=target; next_version:=1;
    select jsonb_build_object('item',to_jsonb(i),'revision',to_jsonb(r),
      'origin_revision',to_jsonb(prior)) into after_state
      from crm_private.commercial_items i join crm_private.commercial_revisions r using(item_id)
      where i.item_id=target and r.revision_number=1;
  else
    if v[5]<>'application' or linked_item is not null or linked_rev is not null
      or origin is null or v[9]<>'{}' or v[10]<>'' or v[11]<>'' or expected<>0 then
      raise exception 'COMMERCIAL_INPUT_INVALID' using errcode='22023'; end if;
    refs:=string_to_array(v[12],',');
    if refs is null or cardinality(refs)<1 or cardinality(refs)>50 then
      raise exception 'COMMERCIAL_INPUT_INVALID' using errcode='22023'; end if;
    foreach ref in array refs loop
      if ref !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
        or ref=any(seen) then
        raise exception 'COMMERCIAL_INPUT_INVALID' using errcode='22023'; end if;
      seen:=array_append(seen,ref);
      select * into rev from crm_private.commercial_revisions where revision_id=ref::uuid;
      if not found or rev.admin_scope<>scope then
        raise exception 'COMMERCIAL_RELATION_INVALID' using errcode='22023'; end if;
      select * into item from crm_private.commercial_items where item_id=rev.item_id;
      snapshot:=snapshot || jsonb_build_array(jsonb_build_object(
        'revision',to_jsonb(rev),'item',to_jsonb(item)));
    end loop;
    insert into crm_private.commercial_applications(application_id,subject_ref,admin_scope,
      applied_revisions,source_ref,evidence_ref,reason,actor_id)
      values(target,origin,scope,snapshot,v[13],v[14],v[15],actor);
    select to_jsonb(a) into after_state from crm_private.commercial_applications a
      where a.application_id=target;
    result_id:=target; next_version:=0;
  end if;
  insert into crm_private.commercial_operations(operation_id,admin_scope,actor_id,
    fingerprint,result_ref,result_version)
    values(v[3]::uuid,scope,actor,fingerprint,result_id,next_version);
  insert into crm_private.commercial_history(history_id,operation_id,subject_id,admin_scope,
    before_state,after_state,source_ref,evidence_ref,reason,actor_id)
    values(v[3]::uuid,v[3]::uuid,target,scope,before_state,after_state,v[13],v[14],v[15],actor);
  perform crm_f2.verify(f2p,f2s,q,'C03','human_catalog','write_catalog');
  perform crm_f1.verify_envelope(f1p,f1s,q,'C03','catalog','write_catalog');
  result_ref:=result_id; result_version:=next_version; replayed:=false; return next;
end $function$

CREATE OR REPLACE FUNCTION crm_api.commercial_read(f2p bytea, f2s bytea, f1p bytea, f1s bytea, q bytea)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare hf text[]; tf text[]; v text[]; target uuid; output jsonb;
  page_limit integer; page_offset integer; total integer; next_page text;
begin
  hf:=crm_f2.admit(f2p,f2s,q,'C01','read_catalog');
  tf:=crm_f1.verify_envelope(f1p,f1s,q,'C01','catalog','read_catalog');
  if hf[17] collate "C" <> tf[14] collate "C" then
    raise exception 'COMMERCIAL_DENIED' using errcode='42501'; end if;
  v:=crm_f1.fields(q);
  if cardinality(v)<>5 or v[1]<>'CRM-H1-COM-READ1'
    or v[2] not in ('item','version','application','history')
    or v[4] !~ '^[1-9][0-9]{0,2}$' or v[5] !~ '^(0|[1-9][0-9]{0,8})$'
  then raise exception 'COMMERCIAL_INPUT_INVALID' using errcode='22023'; end if;
  target:=v[3]::uuid; page_limit:=v[4]::integer; page_offset:=v[5]::integer;
  if page_limit>100 then raise exception 'COMMERCIAL_INPUT_INVALID' using errcode='22023'; end if;
  if v[2]='item' then
    select jsonb_build_object('item',to_jsonb(i),'latest_revision',to_jsonb(r))
      into output from crm_private.commercial_items i
      left join lateral (select * from crm_private.commercial_revisions r
        where r.item_id=i.item_id order by r.revision_number desc limit 1) r on true
      where i.item_id=target and i.admin_scope=hf[17];
  elsif v[2]='version' then
    select jsonb_build_object('revision',to_jsonb(r),'item',to_jsonb(i))
      into output from crm_private.commercial_revisions r
      join crm_private.commercial_items i using(item_id)
      where r.revision_id=target and r.admin_scope=hf[17];
  elsif v[2]='application' then
    select to_jsonb(a) into output from crm_private.commercial_applications a
      where a.application_id=target and a.admin_scope=hf[17];
  else
    select coalesce(jsonb_agg(to_jsonb(h) order by h.recorded_at,h.history_id),'[]'::jsonb)
      into output from crm_private.commercial_history h
      where h.subject_id=target and h.admin_scope=hf[17];
  end if;
  if v[2]='history' then
    total:=jsonb_array_length(output);
    select coalesce(jsonb_agg(x.value order by x.ordinality),'[]'::jsonb) into output
      from jsonb_array_elements(output) with ordinality x(value,ordinality)
      where x.ordinality>page_offset and x.ordinality<=page_offset+page_limit;
    next_page:=case when page_offset+page_limit<total
      then (page_offset+page_limit)::text else null end;
  else
    if page_offset<>0 then raise exception 'COMMERCIAL_INPUT_INVALID' using errcode='22023'; end if;
    next_page:=null;
  end if;
  perform crm_f2.verify(f2p,f2s,q,'C01','human_catalog','read_catalog');
  perform crm_f1.verify_envelope(f1p,f1s,q,'C01','catalog','read_catalog');
  return jsonb_build_object('data',output,'nextPage',next_page);
end $function$

CREATE OR REPLACE FUNCTION crm_api.commit_internal_unit(p bytea, s bytea, q bytea)
 RETURNS TABLE(replayed boolean, operation_id text, root_id text, resulting_version bigint, after_value text, material_fingerprint text, effect_id text, intent_id text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare f text[];
begin
  f:=crm_f1.verify_unit(p,s,q);
  if f[13] collate "C"='h0-011-human-unit' collate "C" then
    raise exception 'H0_009_DENIED' using errcode='42501';
  end if;
  return query select * from crm_internal.commit_internal_unit_core(p,s,q);
exception
  when serialization_failure or deadlock_detected then raise;
  when sqlstate 'H0002' then raise;
  when others then raise exception 'H0_009_DENIED' using errcode='42501';
end $function$

CREATE OR REPLACE FUNCTION crm_api.commit_internal_unit(p bytea, s bytea, q bytea, f2p bytea, f2s bytea, hq bytea)
 RETURNS TABLE(replayed boolean, operation_id text, root_id text, resulting_version bigint, after_value text, material_fingerprint text, effect_id text, intent_id text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
#variable_conflict use_column
declare tf text[]; tq text[]; hqf text[]; receipt crm_ha.command_receipts%rowtype;
begin
  perform crm_f2.admit(f2p,f2s,hq,'C03','apply_probe_batch');
  tf:=crm_f1.verify_envelope(p,s,q,'C03','internal_unit','commit_internal_unit');
  if tf[13] collate "C"<>'h0-011-human-unit' collate "C" then
    raise exception 'H0_M04_UNIT_DENIED' using errcode='42501';
  end if;
  tq:=crm_f1.fields(q); hqf:=crm_f1.fields(hq);
  if cardinality(tq)<>18 or tq[1]<>'CRM-UNIT1' or cardinality(hqf)<3
    or hqf[1]<>'CRM-H0-M04' or hqf[2] not in ('propose','decide','reserve')
    or tq[2] collate "C"<>hqf[3] collate "C"
    or tq[4] collate "C"<>('ha-'||hqf[3]) collate "C"
    or tf[14] collate "C"<>(crm_f2.verify(f2p,f2s,hq,'C03','human_core_probe','apply_probe_batch'))[17] collate "C"
  then raise exception 'H0_M04_UNIT_DENIED' using errcode='42501'; end if;
  select * into receipt from crm_ha.command_receipts where command_id=tq[2];
  if not found or receipt.command_name collate "C"<>hqf[2] collate "C"
    or receipt.command_fingerprint collate "C"<>encode(crm_crypto.digest(hq,'sha256'),'hex') collate "C"
    or receipt.proposal_id is null
  then raise exception 'H0_M04_UNIT_DENIED' using errcode='42501'; end if;
  return query select * from crm_internal.commit_internal_unit_core(p,s,q);
  perform crm_f2.admit(f2p,f2s,hq,'C03','apply_probe_batch');
  perform crm_ha.check_evidence_at_end(hqf[3]);
exception
  when serialization_failure or deadlock_detected then raise;
  when sqlstate 'H0002' then raise;
  when others then raise exception 'H0_M04_UNIT_DENIED' using errcode='42501';
end $function$

CREATE OR REPLACE FUNCTION crm_api.complete_access_recovery(p bytea, s bytea, q bytea)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare f text[]; v text[]; r crm_private.access_recoveries%rowtype;
  a crm_private.crm_actors%rowtype; rid uuid; aid uuid; subj uuid;
begin
  f:=crm_f1.verify_envelope(p,s,q,'C03','access_recovery','complete');
  v:=crm_f1.fields(q);
  if cardinality(v)<>10 or v[1]<>'CRM-H0-M06-REC1' or v[2]<>'complete'
    or v[6]<>'true' or v[7]<>'true'
  then raise exception 'H0_M06_DENIED' using errcode='42501'; end if;
  rid:=v[3]::uuid; aid:=v[4]::uuid; subj:=v[5]::uuid;
  select * into strict a from crm_private.crm_actors where actor_id=aid for update;
  select * into strict r from crm_private.access_recoveries where recovery_id=rid for update;
  if not a.enabled or a.auth_subject<>subj or r.actor_id<>aid or r.auth_subject<>subj
    or a.admin_scope collate "C"<>f[14] collate "C"
    or r.admin_scope collate "C"<>f[14] collate "C"
    or a.access_generation<>r.access_generation or r.auth_state<>'revoked'
    or (r.recovery_kind='break_glass' and (v[8]<>'true' or v[9]<>'true' or v[10]<>'true'))
    or a.access_state not in ('recovery_in_progress','ready')
    or (r.completed_at is null and a.access_state<>'recovery_in_progress')
    or (r.completed_at is not null and a.access_state<>'ready')
  then raise exception 'H0_M06_DENIED' using errcode='42501'; end if;
  if r.completed_at is null then
    update crm_private.access_recoveries set completed_at=clock_timestamp(),
      password_ready=true,totp_verified=true,new_factor_enrolled=(v[8]='true'),
      old_factor_revoked=(v[9]='true'),new_paper_copy_verified=(v[10]='true')
      where recovery_id=rid;
    update crm_private.crm_actors set access_state='ready',updated_at=clock_timestamp()
      where actor_id=aid;
  end if;
  perform crm_f1.verify_envelope(p,s,q,'C03','access_recovery','complete');
  return r.access_generation;
exception when others then raise exception 'H0_M06_DENIED' using errcode='42501';
end $function$

CREATE OR REPLACE FUNCTION crm_api.confirmation_apply(f2p bytea, f2s bytea, f1p bytea, f1s bytea, q bytea, tf2p bytea, tf2s bytea, tf1p bytea, tf1s bytea, tq bytea)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare hf text[];tf text[];fs text[];a jsonb;op uuid;iid uuid;bid uuid;actor uuid;s text;action text;fp text;hash text;at_time timestamptz;rev bigint;evalrev bigint;
 root crm_private.b04_confirmations;prev crm_private.b04_confirmation_operations;existing crm_private.b04_confirmation_facts;
 old jsonb;state jsonb;d jsonb;r jsonb;fact jsonb;c jsonb;reqs jsonb;deps jsonb;missing jsonb;app crm_private.catalog_applications;sv uuid;
 known boolean:=false;follow boolean:=false;task jsonb;task_id uuid;opp uuid;
begin
 hf:=crm_f2.admit(f2p,f2s,q,'C03','write_evidence');tf:=crm_f1.verify_envelope(f1p,f1s,q,'C03','evidence','write_evidence');if hf[17] collate "C" is distinct from tf[14] collate "C" then raise exception 'CONFIRMATION_DENIED';end if;
 fs:=crm_f1.fields(q);if cardinality(fs)<>2 or fs[1]<>'CRM-H4-CONFIRMATION1' then raise exception 'CONFIRMATION_INPUT_INVALID';end if;a:=fs[2]::jsonb;
 if jsonb_typeof(a) is distinct from 'object' or not(a ?& array['action','operationId','confirmationId','bookingId','expectedRevision','expectedEvaluationRevision','sourceRef','reason','at','evidenceId','data'])
 or a-array['action','operationId','confirmationId','bookingId','expectedRevision','expectedEvaluationRevision','sourceRef','reason','at','evidenceId','data','origin']<>'{}'::jsonb
 or exists(select 1 from unnest(array['action','operationId','confirmationId','bookingId','sourceRef','reason','evidenceId']) k where not coalesce(crm_private.invoice_text(a->k),false))
 or not coalesce(crm_private.availability_time(a->'at'),false) or jsonb_typeof(a->'data') is distinct from 'object'
 or coalesce(a->>'expectedRevision','')!~'^(0|[1-9][0-9]*)$' or coalesce(a->>'expectedEvaluationRevision','')!~'^(0|[1-9][0-9]*)$' or coalesce(a->>'origin','manual')<>'manual' then raise exception 'CONFIRMATION_INPUT_INVALID';end if;
 op:=(a->>'operationId')::uuid;iid:=(a->>'confirmationId')::uuid;bid:=(a->>'bookingId')::uuid;actor:=hf[12]::uuid;s:=hf[17];action:=a->>'action';d:=a->'data';at_time:=(a->>'at')::timestamptz;
 if action not in ('register','evaluate','review','rectify') then raise exception 'CONFIRMATION_INPUT_INVALID';end if;
 select opportunity_id into opp from crm_private.b04_bookings where booking_id=bid and admin_scope=s;if not found then raise exception 'CONFIRMATION_DENIED';end if;
 -- Shared accepted parent, documentary and availability roots, in the existing lock order.
 perform pg_advisory_xact_lock(hashtextextended(opp::text,31));perform pg_advisory_xact_lock(hashtextextended('requirement-booking:'||bid,0));perform pg_advisory_xact_lock(hashtextextended('availability-booking:'||bid,0));perform pg_advisory_xact_lock(hashtextextended('confirmation-booking:'||bid,0));
 select * into root from crm_private.b04_confirmations where confirmation_id=iid;
 if (action<>'register' and root.confirmation_id is null) or (root.confirmation_id is not null and (root.booking_id<>bid or root.admin_scope<>s)) then raise exception 'CONFIRMATION_DENIED';end if;
 fp:=encode(crm_crypto.digest(convert_to(a::text,'UTF8'),'sha256'),'hex');perform pg_advisory_xact_lock(hashtextextended('confirmation-op:'||op,0));select * into prev from crm_private.b04_confirmation_operations where operation_id=op;
 if found then
  if prev.admin_scope<>s or prev.actor_id<>actor or prev.fingerprint<>fp then raise exception 'CONFIRMATION_REPLAY_CONFLICT:E2';end if;r:=prev.result||jsonb_build_object('replayed',true);
 else
  hash:=encode(crm_crypto.digest(convert_to((a-array['operationId','evidenceId'])::text,'UTF8'),'sha256'),'hex');
  if not crm_private.payment_evidence((a->>'evidenceId')::uuid,iid,s,'confirmation:'||action||':'||hash,at_time,true) or not exists(select 1 from crm_private.b07_records where record_id=(a->>'evidenceId')::uuid and recorded_by=actor) then raise exception 'CONFIRMATION_EVIDENCE_REQUIRED:E3';end if;
  if action in ('register','rectify') then
   perform pg_advisory_xact_lock(hashtextextended('confirmation-fact:'||(d->>'factId'),0));select * into existing from crm_private.b04_confirmation_facts where fact_id=(d->>'factId')::uuid;
   if found then
    if existing.admin_scope<>s or existing.material is distinct from d or not exists(select 1 from crm_private.b04_confirmations where confirmation_id=existing.confirmation_id and booking_id=bid and admin_scope=s) then raise exception 'CONFIRMATION_FACT_CONFLICT:E2';end if;
    if action='rectify' and existing.confirmation_id<>iid then raise exception 'CONFIRMATION_FACT_CONFLICT:E2';end if;iid:=existing.confirmation_id;select * into root from crm_private.b04_confirmations where confirmation_id=iid;known:=true;
   end if;
  end if;
  if root.confirmation_id is not null then select revision,after_data into rev,old from crm_private.b04_confirmation_revisions where confirmation_id=iid order by revision desc limit 1;end if;
  if not known and action in ('review','evaluate') and exists(select 1 from crm_private.b04_confirmation_revisions where confirmation_id=iid and action_kind=action and event->'data'=d) then
   if action='review' and old->'review'<>'null'::jsonb or action='evaluate' and (crm_private.confirmation_current(old,bid,s)->>'usable')::boolean then known:=true;end if;
  end if;
  state:=old;
  if not known then
   if coalesce(rev,0)<>(a->>'expectedRevision')::bigint then raise exception 'CONFIRMATION_REVISION_CONFLICT:E2';end if;
   if action in ('register','rectify') then
    if not coalesce(crm_private.confirmation_fact(d,bid,s,actor,at_time),false) then raise exception 'CONFIRMATION_FACT_REQUIRED:E3';end if;
    if action='register' then
     if root.confirmation_id is not null or (a->>'expectedRevision')::bigint<>0 then raise exception 'CONFIRMATION_REVISION_CONFLICT:E2';end if;
     insert into crm_private.b04_confirmations values(iid,bid,s,op);state:=jsonb_build_object('id',iid,'bookingId',bid,'fact',d,'review',null,'evaluation',null);rev:=0;
    else
     if old->'review'='null'::jsonb or d->'recordId'=old->'fact'->'recordId' then raise exception 'CONFIRMATION_NEW_PROOF_REQUIRED:E3';end if;
     if (d->>'happenedAt')::timestamptz<=(old->'fact'->>'happenedAt')::timestamptz then raise exception 'CONFIRMATION_PRECEDENCE_REQUIRED:E8';end if;
     if d->'coverage'->'serviceId'<>old->'fact'->'coverage'->'serviceId' then raise exception 'CONFIRMATION_SCOPE_REQUIRED:E3';end if;
     state:=old||jsonb_build_object('fact',d,'review',null,'evaluation',null);
    end if;
    insert into crm_private.b04_confirmation_facts values((d->>'factId')::uuid,iid,s,case when action='rectify' then (old->'fact'->>'factId')::uuid else null end,d,actor,(a->>'evidenceId')::uuid,(d->>'happenedAt')::timestamptz,clock_timestamp(),op);
   elsif action='review' then
    if d-array['recordId','cause','before','after','aspects','dependencies','result']<>'{}'::jsonb or not(d ?& array['recordId','cause','before','after','aspects','dependencies','result'])
    or not coalesce(crm_private.confirmation_record((d->>'recordId')::uuid,bid,s),false) or not coalesce(crm_private.invoice_text(d->'cause'),false)
    or d->'before' is distinct from old->'fact' or jsonb_typeof(d->'after') is distinct from 'object' or jsonb_typeof(d->'aspects') is distinct from 'array' or jsonb_array_length(d->'aspects')=0
    or exists(select 1 from jsonb_array_elements_text(d->'aspects') x where x not in ('time','date','quantity','unit','price','conditions','capacity','source','variant','scope'))
    or d->'dependencies' is distinct from jsonb_build_array(old->'fact'->'coverage') or d->>'result' is distinct from 'pending' then raise exception 'CONFIRMATION_REVIEW_REQUIRED:E3';end if;
    state:=old||jsonb_build_object('review',d||jsonb_build_object('evidenceId',a->'evidenceId','actorId',actor,'at',at_time));follow:=true;
   else
    if d-array['coverage','catalogApplicationId','eligibilityProofId','scopeProofId','agreementProofId','dependencies']<>'{}'::jsonb or not(d ?& array['coverage','catalogApplicationId','eligibilityProofId','scopeProofId','agreementProofId','dependencies']) then raise exception 'CONFIRMATION_EVALUATION_REQUIRED:E3';end if;
    c:=d->'coverage';if not coalesce(crm_private.confirmation_coverage(c,bid,s),false) then raise exception 'CONFIRMATION_SCOPE_REQUIRED:E3';end if;sv:=(c->>'serviceId')::uuid;
    if (c-array['quantity']) is distinct from ((old->'fact'->'coverage')-array['quantity']) or (c->>'quantity')::numeric>(old->'fact'->'coverage'->>'quantity')::numeric then raise exception 'CONFIRMATION_COVERAGE_REQUIRED:E3';end if;
    select coalesce(max(revision),0) into evalrev from crm_private.b04_confirmation_evaluations where service_id=sv and admin_scope=s;
    if evalrev<>(a->>'expectedEvaluationRevision')::bigint then raise exception 'CONFIRMATION_EVALUATION_CONFLICT:E2';end if;
    missing:='[]';if old->'review'<>'null'::jsonb then missing:=missing||'"review"'::jsonb;end if;
    -- A reviewed applied catalogue manifest is real versioned input, never a recommendation boolean.
    select * into app from crm_private.catalog_applications where application_id=(d->>'catalogApplicationId')::uuid and subject_ref=sv and admin_scope=s;
    if not found or not exists(select 1 from jsonb_array_elements(app.applied_revisions) x where x->'revision'->>'revision_id'=c->>'serviceRevisionId')
    or app.application_id is distinct from (select application_id from crm_private.catalog_applications where subject_ref=sv and admin_scope=s order by recorded_at desc,application_id desc limit 1) then raise exception 'CONFIRMATION_CATALOG_REQUIRED:E3';end if;
    hash:=encode(crm_crypto.digest(convert_to(jsonb_build_object('coverage',c,'application',to_jsonb(app))::text,'UTF8'),'sha256'),'hex');
    if not crm_private.payment_evidence((d->>'eligibilityProofId')::uuid,sv,s,'confirmation:eligibility:'||hash,at_time,true) then missing:=missing||'"objective-eligibility"'::jsonb;end if;
    hash:=encode(crm_crypto.digest(convert_to(c::text,'UTF8'),'sha256'),'hex');
    if not crm_private.payment_evidence((d->>'scopeProofId')::uuid,sv,s,'confirmation:scope:'||hash,at_time,true) then missing:=missing||'"scope-capacity-price-conditions"'::jsonb;end if;
    if not crm_private.payment_evidence((d->>'agreementProofId')::uuid,sv,s,'confirmation:time:'||hash,at_time,true) then missing:=missing||'"time-agreement"'::jsonb;end if;
    reqs:=crm_private.confirmation_requirements(bid,c,s);
    if exists(select 1 from jsonb_array_elements(reqs) x where x->>'status' not in ('Revisado','No aplica')) then missing:=missing||'"requirement"'::jsonb;end if;
    deps:=crm_private.confirmation_dependencies(d->'dependencies',bid,c,s,at_time);
    if exists(select 1 from jsonb_array_elements(deps) x where x->'current'->'usable' is distinct from 'true'::jsonb) then missing:=missing||'"dependency-review"'::jsonb;end if;
    -- Two distinct contemporaneous contradictory facts remain E8, not receipt-order precedence.
    if crm_private.confirmation_discrepancy(old->'fact',bid,s,iid) then missing:=missing||'"external-discrepancy:E8"'::jsonb;end if;
    state:=old||jsonb_build_object('evaluation',d||jsonb_build_object('requirements',reqs,'dependencySnapshot',deps,'missing',missing,'evaluationRevision',evalrev+1,'actorId',actor,'at',at_time,'evidenceId',a->'evidenceId','factId',old->'fact'->'factId'));
    insert into crm_private.b04_confirmation_evaluations values(bid,sv,evalrev+1,iid,s,op,state->'evaluation');follow:=missing<>'[]'::jsonb;
   end if;
   rev:=rev+1;state:=state||jsonb_build_object('revision',rev);
  end if;
  if old is distinct from state then insert into crm_private.b04_confirmation_revisions values(iid,rev,s,op,action,a,old,state,actor,(a->>'evidenceId')::uuid,a->>'sourceRef',a->>'reason',at_time,clock_timestamp());end if;
  r:=jsonb_build_object('id',iid,'replayed',known,'result',state);
  if follow then
   fs:=crm_f1.fields(tq);task:=fs[2]::jsonb;
   if fs[1]<>'CRM-H1-TASK-1' or task->>'taskId'<>iid::text or task->>'operationId'<>op::text or task->'identity' is distinct from jsonb_build_object('causeKind','block','causeId',iid,'contextKind','booking','contextId',bid,'scopeRef',iid,'effect','confirmation-review')
   or task->'material' is distinct from '{"title":"Revisar confirmación y cobertura del alcance","deadline":{"kind":"unknown","reason":"No consta fecha fijada para el seguimiento"},"priority":{"kind":"pending","reason":"Prioridad no configurada"},"sourceRef":"SM-PC","sourceVersion":"1","triggerRef":"BR-TASK-005","triggerVersion":"1"}'::jsonb then raise exception 'CONFIRMATION_TASK_REQUIRED';end if;
   select result_ref into task_id from crm_api.b07_task_apply(tf2p,tf2s,tf1p,tf1s,tq);
  end if;
  insert into crm_private.b04_confirmation_operations values(op,iid,s,actor,fp,r,rev,clock_timestamp());
 end if;
 perform crm_f2.verify(f2p,f2s,q,'C03','human_evidence','write_evidence');perform crm_f1.verify_envelope(f1p,f1s,q,'C03','evidence','write_evidence');return r;
end$function$

CREATE OR REPLACE FUNCTION crm_api.confirmation_read(f2p bytea, f2s bytea, f1p bytea, f1s bytea, q bytea)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare hf text[];tf text[];fs text[];a jsonb;s text;bid uuid;iid uuid;r jsonb;current jsonb;begin
 hf:=crm_f2.admit(f2p,f2s,q,'C01','read_evidence');tf:=crm_f1.verify_envelope(f1p,f1s,q,'C01','evidence','read_evidence');if hf[17] collate "C" is distinct from tf[14] collate "C" then raise exception 'CONFIRMATION_DENIED';end if;
 fs:=crm_f1.fields(q);if cardinality(fs)<>2 or fs[1]<>'CRM-H4-CONFIRMATION-READ1' then raise exception 'CONFIRMATION_INPUT_INVALID';end if;a:=fs[2]::jsonb;s:=hf[17];bid:=(a->>'bookingId')::uuid;iid:=(a->>'confirmationId')::uuid;
 if a-array['confirmationId','bookingId','purpose']<>'{}'::jsonb or not(a ?& array['confirmationId','bookingId']) or a?'purpose' and a->>'purpose' is distinct from 'service-coverage' then raise exception 'CONFIRMATION_INPUT_INVALID';end if;
 select v.after_data into r from crm_private.b04_confirmations i cross join lateral(select after_data from crm_private.b04_confirmation_revisions where confirmation_id=i.confirmation_id and admin_scope=s order by revision desc limit 1) v where i.confirmation_id=iid and i.booking_id=bid and i.admin_scope=s;
 if r is not null then
  if a?'purpose' then
   current:=crm_private.confirmation_current(r,bid,s);
   r:=jsonb_build_object('id',iid,'revision',r->'revision','serviceState',case when (current->>'usable')::boolean then 'Confirmado' else 'Pendiente' end,'usable',current->'usable','missing',current->'missing','factId',r->'fact'->'factId','bookingConfirmed',false,'prepared',false,'executed',false,'holdReleased',false,'refundExecuted',false);
  else r:=r||jsonb_build_object('history',(select jsonb_agg(jsonb_build_object('revision',revision,'action',action_kind,'before',before_data,'after',after_data,'actorId',actor_id,'reason',reason,'sourceRef',source_ref,'evidenceId',evidence_id,'at',occurred_at,'recordedAt',recorded_at) order by revision) from crm_private.b04_confirmation_revisions where confirmation_id=iid and admin_scope=s));end if;
 end if;
 perform crm_f2.verify(f2p,f2s,q,'C01','human_evidence','read_evidence');perform crm_f1.verify_envelope(f1p,f1s,q,'C01','evidence','read_evidence');return r;
end$function$

