CREATE OR REPLACE FUNCTION crm_api.establish_session(p bytea, s bytea, q bytea)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare f text[]; a crm_private.crm_actors%rowtype; qf text[]; at_time timestamptz;
begin
  f:=crm_f2.verify(p,s,q,'establish','human_session','establish');
  qf:=crm_f1.fields(q);
  if f[16]<>'full-identification' or f[21]<>'identification'
    or cardinality(qf)<>5 or qf[1]<>'CRM-F2-INP1' or qf[2]<>'establish'
    or qf[3]<>f[11] or qf[4]<>f[13] or qf[5]<>f[14]
  then raise exception 'F2_DENIED' using errcode='42501'; end if;
  select * into strict a from crm_private.crm_actors
    where actor_id=f[12]::uuid for update;
  if a.auth_subject<>f[11]::uuid or not a.enabled or a.access_state<>'ready'
    or a.access_generation<>f[15]::bigint or a.admin_scope<>f[17]
  then raise exception 'F2_DENIED' using errcode='42501'; end if;
  -- Re-read PostgreSQL's real clock after the actor lock, before either INSERT.
  perform crm_f2.verify(p,s,q,'establish','human_session','establish');
  at_time:=clock_timestamp();
  insert into crm_private.crm_sessions(session_id,actor_id,auth_subject,access_generation,created_at)
    values(f[13]::uuid,a.actor_id,a.auth_subject,a.access_generation,at_time);
  insert into crm_private.identification_epochs(epoch_id,session_id,identified_at,
    last_human_activity_at,full_password,full_mfa,access_state,current_epoch)
    values(f[14]::uuid,f[13]::uuid,at_time,at_time,true,true,'ready',true);
  -- Any lock wait inside the INSERTs still aborts the entire unit on expiry.
  perform crm_f2.verify(p,s,q,'establish','human_session','establish');
  return f[14]::uuid;
exception when others then raise exception 'F2_DENIED' using errcode='42501';
end $function$

CREATE OR REPLACE FUNCTION crm_api.h0_m04_command(f2p bytea, f2s bytea, p bytea, s bytea, q bytea)
 RETURNS TABLE(command_state text, proposal_id text, decision_id text, reservation_id text, attempt_id text, state text, material_fingerprint text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
#variable_conflict use_column
declare f text[]; qf text[]; d text[]; hf text[]; material bytea; part_material bytea;
  proposal_row crm_ha.proposals%rowtype; part_row crm_ha.parts%rowtype;
  decision_row crm_ha.decisions%rowtype; reservation_row crm_ha.reservations%rowtype;
  old crm_ha.command_receipts%rowtype; digest_value text; now_at timestamptz:=clock_timestamp();
  decision_value text; decision_key text; reservation_key text; attempt_key text;
  effect_key text; intent_key text; part_count integer; i integer; part_fields text[];
begin
  qf:=crm_f1.fields(q);
  if qf is null or cardinality(qf)<4 or qf[1]<>'CRM-H0-M04'
    or qf[3] !~ '^[a-z][a-z0-9-]{0,127}$' then raise exception 'H0_M04_DENIED' using errcode='42501'; end if;
  f:=crm_f1.verify_envelope(p,s,q,
    case when qf[2]='read' then 'C01' else 'C03' end,
    'human_approval',case when qf[2]='read' then 'read_proposal' else 'manage_effect' end);
  if qf[2] in ('propose','decide','reserve') then
    hf:=crm_f2.admit(f2p,f2s,q,'C03','apply_probe_batch');
    if hf[17] collate "C"<>f[14] collate "C" then raise exception 'H0_M04_DENIED' using errcode='42501'; end if;
  end if;
  digest_value:=encode(crm_crypto.digest(q,'sha256'),'hex');
  insert into crm_f1.consumption values(f[5],f[6]::oid,f[8]::xid8,f[21],f[20]::bigint);
  perform pg_advisory_xact_lock(hashtextextended(qf[3],0));
  select * into old from crm_ha.command_receipts where command_id=qf[3];
  if found then
    if old.command_fingerprint collate "C"<>digest_value collate "C" then raise exception 'H0_M04_CONFLICT' using errcode='H0002'; end if;
    perform crm_f1.verify_envelope(p,s,q,'C03','human_approval','manage_effect');
    return query select 'previous',old.proposal_id,old.decision_id,old.reservation_id,old.attempt_id,old.state,old.command_fingerprint;
    return;
  end if;
  if qf[2]='propose' then
    if cardinality(qf)<>5 or qf[4] not in ('human','ai') then raise exception 'H0_M04_DENIED' using errcode='42501'; end if;
    material:=decode(qf[5],'hex'); d:=crm_f1.fields(material);
    if encode(crm_f1.pack_fields(d),'hex')<>qf[5] or cardinality(d)<21
      or d[1]<>'CRM-H0-HA-MATERIAL1' or d[2]<>'1' or d[3]='' or d[4]=''
      or d[6] not in ('not-applicable','unknown','value') or d[8] not in ('not-applicable','unknown','value')
      or d[10] not in ('not-applicable','unknown','value') or d[14] not in ('not-applicable','unknown','value')
      or d[16] not in ('none','required') or d[20] !~ '^[1-9][0-9]?$'
      or cardinality(d)<>20+d[20]::integer*3
      or (d[6]<>'value' and d[7]<>'') or (d[8]<>'value' and d[9]<>'')
      or (d[10]<>'value' and d[11]<>'') or (d[14]<>'value' and d[15]<>'')
      or (d[16]='none' and (d[17]<>'' or d[18]<>'' or d[19]<>''))
      or (d[16]='required' and (d[17]='' or d[18] !~ '^[0-9a-f]{64}$' or d[19]=''))
    then raise exception 'H0_M04_DENIED' using errcode='42501'; end if;
    perform 1 from crm_private.crm_actors a where a.actor_id=hf[12]::uuid and a.enabled
      and a.access_state='ready' and a.admin_scope=d[12] for update;
    if not found then raise exception 'H0_M04_DENIED' using errcode='42501'; end if;
    hf:=crm_f2.admit(f2p,f2s,q,'C03','apply_probe_batch');
    now_at:=clock_timestamp();
    insert into crm_ha.proposals values(qf[3],encode(crm_crypto.digest(material,'sha256'),'hex'),material,
      qf[4],hf[12]::uuid,d[12],now_at);
    part_count:=d[20]::integer;
    for i in 0..part_count-1 loop
      part_material:=decode(d[22+i*3],'hex'); part_fields:=crm_f1.fields(part_material);
      if encode(crm_f1.pack_fields(part_fields),'hex')<>d[22+i*3]
        or encode(crm_crypto.digest(part_material,'sha256'),'hex')<>d[23+i*3]
        or cardinality(part_fields)<>13 or part_fields[1]<>'CRM-H0-HA-PART1'
        or part_fields[2]<>d[21+i*3] or part_fields[12]<>d[12]
      then raise exception 'H0_M04_DENIED' using errcode='42501'; end if;
      insert into crm_ha.parts values(qf[3],d[21+i*3],d[23+i*3],part_material);
    end loop;
    insert into crm_ha.events values(qf[3],qf[3],null,null,'proposed',
      case when qf[4]='human' then 'human' else 'technical' end,
      hf[12],now_at,digest_value);
    insert into crm_ha.command_receipts values(qf[3],digest_value,'propose',qf[3],null,null,null,'proposed',now_at);
    return query select 'applied',qf[3],null::text,null::text,null::text,'proposed',encode(crm_crypto.digest(material,'sha256'),'hex'); return;
  elsif qf[2]='decide' then
    d:=crm_f1.fields(decode(qf[4],'hex'));
    if cardinality(qf)<>4 or cardinality(d)<>5 or d[1] !~ '^[a-z][a-z0-9-]{0,127}$'
      or d[2] !~ '^[a-z][a-z0-9-]{0,127}$' or d[3] not in ('approved','rejected') or d[4]='' or d[5] !~ '^[0-9a-f]{64}$'
    then raise exception 'H0_M04_DENIED' using errcode='42501'; end if;
    perform pg_advisory_xact_lock(hashtextextended(d[1]||':decision',0));
    select * into strict proposal_row from crm_ha.proposals where proposal_id=d[1];
    if proposal_row.material_fingerprint collate "C"<>d[5] collate "C" or proposal_row.scope collate "C"<>hf[17] collate "C"
    then raise exception 'H0_M04_CONFLICT' using errcode='H0002'; end if;
    hf:=crm_f2.admit(f2p,f2s,q,'C03','apply_probe_batch');
    now_at:=clock_timestamp();
    decision_key:=d[2]; decision_value:=d[3];
    insert into crm_ha.decisions values(decision_key,d[1],d[5],decision_value,d[4],hf[12]::uuid,hf[13]::uuid,now_at);
    insert into crm_ha.events values(qf[3],d[1],null,null,decision_value,'human',hf[12],now_at,digest_value);
    insert into crm_ha.command_receipts values(qf[3],digest_value,'decide',d[1],decision_key,null,null,decision_value,now_at);
    return query select 'applied',d[1],decision_key,null::text,null::text,decision_value,d[5]; return;
  elsif qf[2]='reserve' then
    d:=crm_f1.fields(decode(qf[4],'hex'));
    if cardinality(qf)<>4 or cardinality(d)<>7 or d[1] !~ '^[a-z][a-z0-9-]{0,127}$' or d[2] !~ '^[a-z][a-z0-9-]{0,127}$'
      or d[3] !~ '^[a-z][a-z0-9-]{0,127}$' or d[4] !~ '^[0-9a-f]{64}$'
      or d[5] !~ '^[0-9a-f]{64}$' or d[6] !~ '^[a-z][a-z0-9-]{0,127}$'
      or d[7] !~ '^[a-z][a-z0-9-]{0,127}$'
    then raise exception 'H0_M04_DENIED' using errcode='42501'; end if;
    select * into strict proposal_row from crm_ha.proposals where proposal_id=d[1];
    select * into strict decision_row from crm_ha.decisions where decision_id=d[2] and proposal_id=d[1];
    perform pg_advisory_xact_lock(hashtextextended(d[1]||':'||d[3],0));
    select * into strict part_row from crm_ha.parts where proposal_id=d[1] and part_id=d[3];
    if decision_row.decision<>'approved' or proposal_row.material_fingerprint collate "C"<>d[4] collate "C"
      or part_row.material_fingerprint collate "C"<>d[5] collate "C" or proposal_row.scope collate "C"<>hf[17] collate "C"
      or proposal_row.material_payload is null
    then raise exception 'H0_M04_DENIED' using errcode='42501'; end if;
    if (crm_f1.fields(proposal_row.material_payload))[16]<>'none' then
      if not exists(select 1 from crm_ha.evidence_revalidations e where e.command_id=qf[3]
        and e.proposal_id=d[1] and e.part_id=d[3] and e.command_fingerprint=digest_value
        and e.context_scope=hf[17] and e.created_xid=pg_current_xact_id()) then
        raise exception 'H0_M04_EVIDENCE_UNVERIFIED' using errcode='42501'; end if;
      perform crm_ha.check_evidence_at_end(qf[3]);
    end if;
    effect_key:='effect-'||substr(encode(crm_crypto.digest(convert_to(d[1]||':'||d[3],'UTF8'),'sha256'),'hex'),1,32);
    intent_key:='intent-'||substr(encode(crm_crypto.digest(convert_to(d[1]||':'||d[3],'UTF8'),'sha256'),'hex'),1,32);
    if d[6]<>effect_key or d[7]<>intent_key then raise exception 'H0_M04_DENIED' using errcode='42501'; end if;
    hf:=crm_f2.admit(f2p,f2s,q,'C03','apply_probe_batch');
    now_at:=clock_timestamp();
    insert into crm_ha.reservations values(qf[3],d[1],d[2],d[3],d[5],effect_key,intent_key,'reserved',now_at,now_at);
    insert into crm_ha.events values(qf[3],d[1],qf[3],null,'reserved','human',hf[12],now_at,digest_value);
    insert into crm_ha.command_receipts values(qf[3],digest_value,'reserve',d[1],d[2],qf[3],null,'reserved',now_at);
    return query select 'applied',d[1],d[2],qf[3],null::text,'reserved',d[4]; return;
  elsif qf[2]='attempt' then
    d:=crm_f1.fields(decode(qf[4],'hex'));
    if cardinality(d)<>2 then raise exception 'H0_M04_DENIED' using errcode='42501'; end if;
    select * into strict reservation_row from crm_ha.reservations where reservation_id=d[1] for update;
    if reservation_row.state<>'reserved' then raise exception 'H0_M04_DENIED' using errcode='42501'; end if;
    now_at:=clock_timestamp();
    update crm_ha.reservations set state='attempting',updated_at=now_at where reservation_id=d[1];
    select * into strict proposal_row from crm_ha.proposals where proposal_id=reservation_row.proposal_id;
    insert into crm_ha.events values(qf[3],reservation_row.proposal_id,d[1],d[2],'attempted','technical',f[11],now_at,digest_value);
    perform set_config('crm.ha_payload',encode(p,'hex'),true),set_config('crm.ha_mac',encode(s,'hex'),true),
      set_config('crm.ha_input',encode(q,'hex'),true);
    insert into crm_private.external_effect_records(record_id,operation_id,root_id,context_scope,effect_id,
      stage,intent_id,attempt_id,recorded_at)
      values(d[2],d[1],'ha-'||d[1],proposal_row.scope,reservation_row.effect_id,'attempt',reservation_row.intent_id,d[2],now_at);
    perform set_config('crm.ha_payload','',true),set_config('crm.ha_mac','',true),set_config('crm.ha_input','',true);
    insert into crm_ha.command_receipts values(qf[3],digest_value,'attempt',reservation_row.proposal_id,reservation_row.decision_id,d[1],d[2],'attempting',now_at);
    return query select 'applied',reservation_row.proposal_id,reservation_row.decision_id,d[1],d[2],'attempting',reservation_row.material_fingerprint; return;
  elsif qf[2] in ('outcome','reconcile') then
    d:=crm_f1.fields(decode(qf[4],'hex'));
    if cardinality(d)<>4 or d[3] not in ('succeeded','failed','uncertain') or d[4]=''
    then raise exception 'H0_M04_DENIED' using errcode='42501'; end if;
    select * into strict reservation_row from crm_ha.reservations where reservation_id=d[1] for update;
    perform 1 from crm_ha.events where attempt_id=d[2] and reservation_id=d[1] and event_kind='attempted';
    if not found or (qf[2]='outcome' and reservation_row.state<>'attempting')
      or (qf[2]='reconcile' and reservation_row.state<>'uncertain')
      or (qf[2]='reconcile' and d[3]='uncertain')
    then raise exception 'H0_M04_DENIED' using errcode='42501'; end if;
    now_at:=clock_timestamp();
    decision_value:=case when d[3]='uncertain' then 'uncertain' when d[3]='succeeded' then 'consumed' else 'reserved' end;
    update crm_ha.reservations set state=decision_value,updated_at=now_at where reservation_id=d[1];
    select * into strict proposal_row from crm_ha.proposals where proposal_id=reservation_row.proposal_id;
    insert into crm_ha.events values(qf[3],reservation_row.proposal_id,d[1],d[2],
      case when d[3]='uncertain' then 'uncertain' when qf[2]='reconcile' and d[3]='succeeded'
        then 'reconciled-succeeded' when qf[2]='reconcile' then 'reconciled-failed'
        when d[3]='succeeded' then 'succeeded' else 'failed-known' end,
      'technical',f[11],now_at,digest_value);
    perform set_config('crm.ha_payload',encode(p,'hex'),true),set_config('crm.ha_mac',encode(s,'hex'),true),
      set_config('crm.ha_input',encode(q,'hex'),true);
    if d[3]='uncertain' then
      insert into crm_private.external_effect_records(record_id,operation_id,root_id,context_scope,effect_id,
        stage,intent_id,attempt_id,recorded_at)
        values('uncertain-'||qf[3],d[1],'ha-'||d[1],proposal_row.scope,reservation_row.effect_id,
          'uncertain',reservation_row.intent_id,d[2],now_at);
    else
      insert into crm_private.external_effect_records(record_id,operation_id,root_id,context_scope,effect_id,
        stage,intent_id,attempt_id,outcome,result_reference,recorded_at)
        values('result-'||qf[3],d[1],'ha-'||d[1],proposal_row.scope,reservation_row.effect_id,
          'result',reservation_row.intent_id,d[2],d[3],d[4],now_at);
    end if;
    perform set_config('crm.ha_payload','',true),set_config('crm.ha_mac','',true),set_config('crm.ha_input','',true);
    insert into crm_ha.command_receipts values(qf[3],digest_value,qf[2],reservation_row.proposal_id,
      reservation_row.decision_id,d[1],d[2],decision_value,now_at);
    return query select 'applied',reservation_row.proposal_id,reservation_row.decision_id,d[1],d[2],decision_value,reservation_row.material_fingerprint; return;
  else raise exception 'H0_M04_DENIED' using errcode='42501'; end if;
exception when sqlstate 'H0002' or unique_violation then raise exception 'H0_M04_CONFLICT' using errcode='H0002';
  when others then raise exception 'H0_M04_DENIED' using errcode='42501';
end $function$

CREATE OR REPLACE FUNCTION crm_api.h0_m04_evidence_replay(p bytea, s bytea, q bytea)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare f text[]; h text[]; d text[]; r crm_ha.command_receipts%rowtype;
begin
  f:=crm_f1.verify_envelope(p,s,q,'C01','human_approval_evidence','check_replay');
  if f[13] is distinct from 'h0-011-evidence-revalidation' then raise exception 'denied'; end if;
  h:=crm_f1.fields(q);
  if cardinality(h)<>4 or h[1]<>'CRM-H0-M04' or h[2]<>'reserve' then raise exception 'denied'; end if;
  d:=crm_f1.fields(decode(h[4],'hex'));
  if cardinality(d)<>7 then raise exception 'denied'; end if;
  select * into r from crm_ha.command_receipts where command_id=h[3];
  if not found then return false; end if;
  if r.command_fingerprint is distinct from encode(crm_crypto.digest(q,'sha256'),'hex') then
    raise exception 'H0_M04_CONFLICT' using errcode='H0002'; end if;
  if not exists(select 1 from crm_ha.proposals where proposal_id=r.proposal_id and scope=f[14])
    then raise exception 'denied'; end if;
  return true;
exception when sqlstate 'H0002' then raise;
  when others then raise exception 'H0_M04_EVIDENCE_DENIED' using errcode='42501';
end $function$

CREATE OR REPLACE FUNCTION crm_api.h0_m04_read_proposal(f2p bytea, f2s bytea, p bytea, s bytea, q bytea, proposal_key text)
 RETURNS TABLE(proposal_id text, material_fingerprint text, material_payload bytea, decision text, decision_id text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
#variable_conflict use_column
declare f text[]; hf text[]; qf text[]; prop crm_ha.proposals%rowtype;
begin
  f:=crm_f1.verify_envelope(p,s,q,'C01','human_approval','read_proposal');
  qf:=crm_f1.fields(q);
  if cardinality(qf)<>3 or qf[1]<>'CRM-INP1' or qf[2]<>'C01'
    or qf[3]<>proposal_key then raise exception 'H0_M04_DENIED' using errcode='42501'; end if;
  hf:=crm_f2.admit(f2p,f2s,q,'C01','read_probe');
  if hf[17] collate "C"<>f[14] collate "C" then raise exception 'H0_M04_DENIED' using errcode='42501'; end if;
  select * into strict prop from crm_ha.proposals where proposal_id=proposal_key and scope=f[14];
  return query select prop.proposal_id,prop.material_fingerprint,prop.material_payload,d.decision,d.decision_id
    from crm_ha.decisions d where d.proposal_id=prop.proposal_id
    union all select prop.proposal_id,prop.material_fingerprint,prop.material_payload,null::text,null::text
    where not exists(select 1 from crm_ha.decisions where proposal_id=prop.proposal_id);
exception when others then raise exception 'H0_M04_DENIED' using errcode='42501'; end $function$

CREATE OR REPLACE FUNCTION crm_api.h0_m04_revalidate_evidence(p bytea, s bytea, q bytea, f2p bytea, f2s bytea, hq bytea)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare f text[]; h text[]; d text[]; e text[]; m text[]; hf text[];
  prop crm_ha.proposals%rowtype; old crm_ha.command_receipts%rowtype;
  now_us bigint; approved_us bigint;
begin
  -- Same actor/session/epoch -> command lock order as M04.
  hf:=crm_f2.admit(f2p,f2s,hq,'C03','apply_probe_batch');
  f:=crm_f1.verify_envelope(p,s,q,'C03','human_approval_evidence','revalidate_evidence');
  if f[13] is distinct from 'h0-011-evidence-revalidation' or f[14] is distinct from hf[17]
    then raise exception 'denied'; end if;
  h:=crm_f1.fields(hq); e:=crm_f1.fields(q);
  if cardinality(h)<>4 or h[1]<>'CRM-H0-M04' or h[2]<>'reserve'
    or cardinality(e)<>12 or e[1]<>'CRM-HA-EVIDENCE1'
    or e[2] is distinct from h[3]
    or e[5] is distinct from encode(crm_crypto.digest(hq,'sha256'),'hex') then raise exception 'denied'; end if;
  d:=crm_f1.fields(decode(h[4],'hex'));
  if cardinality(d)<>7 or e[3] is distinct from d[1] or e[4] is distinct from d[3]
    then raise exception 'denied'; end if;
  perform pg_advisory_xact_lock(hashtextextended(h[3],0));
  select * into old from crm_ha.command_receipts where command_id=h[3];
  if found then
    if old.command_fingerprint is distinct from e[5] then
      raise exception 'H0_M04_CONFLICT' using errcode='H0002'; end if;
    return; -- Concurrent winner already committed; no new evidence/effect.
  end if;
  select * into strict prop from crm_ha.proposals where proposal_id=d[1] and scope=f[14];
  m:=crm_f1.fields(prop.material_payload);
  if m[16] is distinct from 'required' or m[17] is distinct from e[6] or m[18] is distinct from e[7]
    or prop.material_fingerprint is distinct from d[4]
    or not exists(select 1 from crm_ha.parts where proposal_id=d[1] and part_id=d[3] and material_fingerprint=d[5])
    or not exists(select 1 from crm_ha.decisions where proposal_id=d[1] and decision_id=d[2]
      and decision='approved' and material_fingerprint=d[4]) then raise exception 'denied'; end if;
  if e[8] !~ '^[0-9]{1,18}$' or e[9] !~ '^[0-9]{1,18}$' or e[10] !~ '^[0-9]{1,18}$'
    then raise exception 'denied'; end if;
  approved_us:=floor(extract(epoch from m[19]::timestamptz)*1000000)::bigint;
  now_us:=floor(extract(epoch from clock_timestamp())*1000000)::bigint;
  if e[8]::bigint>now_us or e[8]::bigint>=e[10]::bigint or now_us>=e[10]::bigint
    or e[10]::bigint<>least(approved_us,e[9]::bigint) then raise exception 'denied'; end if;
  perform crm_f1.verify_envelope(p,s,q,'C03','human_approval_evidence','revalidate_evidence');
  perform crm_f2.verify(f2p,f2s,hq,'C03','human_core_probe','apply_probe_batch');
  insert into crm_ha.evidence_revalidations values(h[3],d[1],d[3],e[5],e[6],e[7],e[8]::bigint,
    e[9]::bigint,approved_us,e[10]::bigint,e[11],e[12],f[14],pg_current_xact_id(),clock_timestamp(),'verified');
exception when serialization_failure or deadlock_detected then raise;
  when sqlstate 'H0002' then raise;
  when others then raise exception 'H0_M04_EVIDENCE_DENIED' using errcode='42501';
end $function$

CREATE OR REPLACE FUNCTION crm_api.h5_diagnostic_read(f2p bytea, f2s bytea, f1p bytea, f1s bytea, q bytea)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare h text[];t text[];f text[];a jsonb;nodes jsonb;chosen jsonb;r jsonb;refs text[];n integer;history jsonb;
begin
 h:=crm_f2.admit(f2p,f2s,q,'C01','read_evidence');t:=crm_f1.verify_envelope(f1p,f1s,q,'C01','evidence','read_evidence');f:=crm_f1.fields(q);
 if h[17]<>t[14]or cardinality(f)<>2 or f[1]<>'CRM-H5-DIAGNOSTIC-READ1'then raise exception 'DIAGNOSTIC_DENIED';end if;
 a:=f[2]::jsonb;
 if a-array['contextKind','contextId','pageSize','after','reference']<>'{}' or not(a?&array['contextKind','contextId','pageSize'])
 or jsonb_typeof(a->'pageSize')<>'number' or(a->>'pageSize')::numeric<>trunc((a->>'pageSize')::numeric)
 or(a->>'pageSize')::int not between 1 and 100
 or(a?'after'and a->>'after'!~'^[a-z0-9_]+/[a-z0-9:-]+$')
 or(a?'reference'and a->>'reference'!~'^([a-f0-9-]{36}|ref-[a-f0-9]{16})$')then raise exception 'DIAGNOSTIC_DENIED';end if;
 n:=(a->>'pageSize')::int;nodes:=crm_private.diagnostic_nodes(h[17],a->>'contextKind',(a->>'contextId')::uuid);
 if a?'reference'then
  -- An explicit B08 operation lookup may inspect its owner's authorized history.
  -- This is not part of the root's canonical set and never authorizes a write.
  -- Preserve original typed context/version and revalidate both source versions.
  with owned_history as(
   select o.operation_id,o.actor_id,o.recorded_at,hist.history_id,hist.recorded_at history_time,
    e.execution_id,d.version,d.context
   from crm_private.b07_operations o
   join crm_private.b07_history hist on hist.operation_id=o.operation_id and hist.subject_id=o.result_ref
   join crm_private.b08_command_results result on result.operation_id=o.operation_id
   join crm_private.b08_executions e on e.execution_id=hist.subject_id
   join crm_private.b08_definitions d on d.definition_id=e.definition_id
    and d.definition_id::text=hist.after_state#>>'{definition,definition_id}'
    and d.version::text=hist.after_state#>>'{definition,version}'
    and d.context=hist.after_state#>'{definition,context}'
   where o.operation_id::text=a->>'reference' and o.admin_scope=h[17] and hist.admin_scope=h[17]
    and result.admin_scope=h[17] and e.admin_scope=h[17] and d.admin_scope=h[17]
    and left(hist.action_kind,5)='work_' and hist.subject_id::text=hist.after_state#>>'{execution,execution_id}'
    and crm_private.b08_context(d,h[17])
    and exists(select 1 from jsonb_array_elements(nodes)x where x->>'source'='b08_executions' and x->>'id'=e.execution_id::text)
  ), projected as(
   select jsonb_build_object('key','b07_operations/'||operation_id,'source','b07_operations','id',operation_id,
    'references',jsonb_build_array(operation_id,execution_id),'actorId',actor_id,'recordedAt',recorded_at,
    'historical',true,'definitionVersion',version,'originContextKind',context->>'contextKind','originContextId',context->>'contextId')node from owned_history
   union all
   select jsonb_build_object('key','b07_history/'||history_id,'source','b07_history','id',history_id,
    'references',jsonb_build_array(history_id,operation_id,execution_id),'actorId',actor_id,'recordedAt',history_time,
    'historical',true,'definitionVersion',version,'originContextKind',context->>'contextKind','originContextId',context->>'contextId')node from owned_history
  )select coalesce(jsonb_agg(distinct node),'[]')into history from projected
   where not exists(select 1 from jsonb_array_elements(nodes)x where x->>'key'=node->>'key');
  nodes:=nodes||history;
  -- Follow correlated IDs transitively inside this root only. No business state
  -- is inferred from the existence or outcome of an observation.
  with recursive edges as(select value node from jsonb_array_elements(nodes)),walk(ref)as(
   select a->>'reference' union select v.value from walk w join edges e on e.node->'references'?w.ref cross join lateral jsonb_array_elements_text(e.node->'references')v where v.value is not null
  )select array_agg(ref)into refs from walk;
  select coalesce(jsonb_agg(value),'[]')into nodes from jsonb_array_elements(nodes)where exists(select 1 from unnest(refs)x where value->'references'?x);
 end if;
 select coalesce(jsonb_agg(node order by node->>'key' collate "C"),'[]')into chosen from(select value node from jsonb_array_elements(nodes)where not(a?'after')or value->>'key' collate "C">a->>'after' collate "C" order by value->>'key' collate "C" limit n+1)x;
 r:=jsonb_build_object('technicalOnly',true,'nodes',(select coalesce(jsonb_agg(value order by ord),'[]')from jsonb_array_elements(chosen)with ordinality x(value,ord)where ord<=n),
  'next',case when jsonb_array_length(chosen)>n then chosen->(n-1)->>'key'else null end);
 perform crm_f2.verify(f2p,f2s,q,'C01','human_evidence','read_evidence');perform crm_f1.verify_envelope(f1p,f1s,q,'C01','evidence','read_evidence');return r;
end$function$

CREATE OR REPLACE FUNCTION crm_api.h5_diagnostic_record(f2p bytea, f2s bytea, f1p bytea, f1s bytea, q bytea)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare h text[];t text[];f text[];a jsonb;i jsonb;s text;k text;root uuid;old crm_private.b10_diagnostic_observations%rowtype;r jsonb;opstate text;
begin
 h:=crm_f2.admit(f2p,f2s,q,'C03','write_evidence');t:=crm_f1.verify_envelope(f1p,f1s,q,'C03','evidence','write_evidence');f:=crm_f1.fields(q);
 if h[17]<>t[14] or cardinality(f)<>2 or f[1]<>'CRM-H5-DIAGNOSTIC1' then raise exception 'DIAGNOSTIC_DENIED';end if;
 a:=f[2]::jsonb;s:=h[17];k:=a->>'contextKind';root:=(a->>'contextId')::uuid;
 if a-array['contextKind','contextId','observationId','requestRef','operationId','executionId','eventId','outcome','issues']<>'{}'
 or not(a?&array['contextKind','contextId','observationId','requestRef','outcome','issues'])
 or not crm_private.diagnostic_root(s,k,root) or coalesce(a->>'requestRef','')!~'^ref-[a-f0-9]{16}$'
 or coalesce(a->>'outcome','')not in('accepted','previous','pending','rejected')
 or jsonb_typeof(a->'issues')is distinct from 'array' then raise exception 'DIAGNOSTIC_DENIED';end if;
 if jsonb_array_length(a->'issues')>8 or (a->>'outcome' in('accepted','previous'))<>(jsonb_array_length(a->'issues')=0) then raise exception 'DIAGNOSTIC_DENIED';end if;
 for i in select value from jsonb_array_elements(a->'issues')loop
  if jsonb_typeof(i)<>'object' or i-array['code','affectedScope']<>'{}' or not(i?&array['code','affectedScope'])
   or coalesce(i->>'code','')not in('E1','E2','E3','E4','E5','E6','E7','E8')
   or coalesce(i->>'affectedScope','')not in('request','access','operation','execution','event','evidence','dependency','identity','document','work')
   or (i->>'code'='E4' and a->>'outcome'='rejected')then raise exception 'DIAGNOSTIC_DENIED';end if;
 end loop;
 -- Serialize only technical observation identity; conflicting content is not a replay.
 perform pg_advisory_xact_lock(hashtextextended(a->>'observationId',17017));
 select * into old from crm_private.b10_diagnostic_observations where observation_id=(a->>'observationId')::uuid;
 if found then
  if old.admin_scope<>s or old.actor_id<>h[12]::uuid or old.context_kind<>k or old.context_id<>root or old.request_ref<>a->>'requestRef'
   or old.operation_id is distinct from (a->>'operationId')::uuid or old.execution_id is distinct from (a->>'executionId')::uuid
   or old.event_id is distinct from(a->>'eventId')::uuid or old.outcome<>a->>'outcome' or old.issues<>a->'issues'then raise exception 'DIAGNOSTIC_DENIED';end if;
  -- Reauthorize the exact stored observation through the same typed historical
  -- projection as C01. This rejects stale evidence and incompatible late owners.
  if not exists(select 1 from jsonb_array_elements(crm_private.diagnostic_nodes(s,k,root))n
   where n->>'source'='b10_diagnostic_observations' and n->>'id'=old.observation_id::text)
   then raise exception 'DIAGNOSTIC_DENIED';end if;
  r:=jsonb_build_object('id',old.observation_id,'replayed',true);
 else
  -- A missing identity is a new write; historical readability is insufficient.
 if a?'executionId' and not exists(select 1 from crm_private.b08_executions e join crm_private.b08_definitions d using(definition_id,version)
 where e.execution_id=(a->>'executionId')::uuid and e.admin_scope=s and d.admin_scope=s and crm_private.b08_context(d,s) and exists(select 1 from crm_private.diagnostic_contexts(s,k,root)c
  where c.context_kind=d.context->>'contextKind' and c.context_id::text=d.context->>'contextId'))then raise exception 'DIAGNOSTIC_DENIED';end if;
 if a?'eventId' and not exists(select 1 from crm_private.b07_records e join crm_private.b07_links l using(record_id)
 where e.record_id=(a->>'eventId')::uuid and e.record_kind='external_event' and e.admin_scope=s and l.admin_scope=s and l.context_kind=k and l.context_id=root)then raise exception 'DIAGNOSTIC_DENIED';end if;
 if a?'operationId' then
  opstate:=crm_private.diagnostic_operation_reference((a->>'operationId')::uuid,crm_private.diagnostic_canonical_nodes(s,k,root));
  if opstate='incompatible' or(opstate='canonical' and a?'executionId' and not exists(
   select 1 from crm_private.b07_operations op join crm_private.b08_command_results result using(operation_id)
   where op.operation_id=(a->>'operationId')::uuid and op.result_ref=(a->>'executionId')::uuid
    and op.admin_scope=s and result.admin_scope=s))then raise exception 'DIAGNOSTIC_DENIED';end if;
 end if;
  insert into crm_private.b10_diagnostic_observations(observation_id,admin_scope,actor_id,context_kind,context_id,request_ref,operation_id,execution_id,event_id,outcome,issues)
   values((a->>'observationId')::uuid,s,h[12]::uuid,k,root,a->>'requestRef',(a->>'operationId')::uuid,(a->>'executionId')::uuid,(a->>'eventId')::uuid,a->>'outcome',a->'issues');
  r:=jsonb_build_object('id',a->>'observationId','replayed',false);
 end if;
 perform crm_f2.verify(f2p,f2s,q,'C03','human_evidence','write_evidence');perform crm_f1.verify_envelope(f1p,f1s,q,'C03','evidence','write_evidence');return r;
end$function$

CREATE OR REPLACE FUNCTION crm_api.h5_projection_read(f2p bytea, f2s bytea, f1p bytea, f1s bytea, q bytea)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare hf text[];tf text[];fs text[];a jsonb;s text;root uuid;k text;
 ctx uuid[];party_ids uuid[]:='{}';record_ids uuid[];task_ids uuid[];bids uuid[];opps uuid[];props uuid[];sids uuid[];schedules uuid[];determinations uuid[];
 item record;rows jsonb;facts jsonb:='[]';originals jsonb;commercial jsonb:='[]';calendar jsonb:='[]';r jsonb;
begin
 hf:=crm_f2.admit(f2p,f2s,q,'C01','read_evidence');
 tf:=crm_f1.verify_envelope(f1p,f1s,q,'C01','evidence','read_evidence');
 if hf[17] collate "C"<>tf[14] collate "C" then raise exception 'PROJECTION_DENIED' using errcode='42501';end if;
 fs:=crm_f1.fields(q);
 if cardinality(fs)<>2 or fs[1]<>'CRM-H5-PROJECTION-READ1' then raise exception 'PROJECTION_INPUT_INVALID';end if;
 a:=fs[2]::jsonb;s:=hf[17];root:=(a->>'contextId')::uuid;k:=a->>'contextKind';
 if a-array['contextId','contextKind','surface','destination','includeArchived','search','pageSize','after']<>'{}'::jsonb
  or not(a?&array['contextId','contextKind','surface','destination'])
  or k not in('booking','opportunity','contact','organization')
  or a->>'surface' not in('timeline','calendar','query','search','export','document','ai_context')
  or a->>'destination' not in('administrator','customer','provider','ai')
  or (a?'includeArchived' and jsonb_typeof(a->'includeArchived')<>'boolean')
 then raise exception 'PROJECTION_INPUT_INVALID';end if;
 -- A reference or party relationship is never an authority. F2 admits the sole
 -- current administrator; the requested root and every join remain in its scope.
 if k in('booking','opportunity') then
  if not exists(select 1 from crm_private.identity_contexts c where c.context_id=root and c.context_kind=k and c.admin_scope=s)
   then raise exception 'PROJECTION_DENIED' using errcode='42501';end if;
  ctx:=array[root];
 else
  if not exists(select 1 from crm_private.identity_entities e where e.identity_id=root and e.identity_kind=k and e.admin_scope=s)
   then raise exception 'PROJECTION_DENIED' using errcode='42501';end if;
  if not coalesce((a->>'includeArchived')::boolean,false) and exists(select 1 from crm_private.identity_entities e where e.identity_id=root and e.archived_at is not null)
   then return null;end if;
  -- A human merge retains its original identities and histories. It does not
  -- merge Opportunities/Bookings or grant authority through a shared party.
  with recursive lineage(id) as (
   select root union select e.identity_id from crm_private.identity_entities e
    join lineage l on e.merged_into_id=l.id where e.admin_scope=s and e.identity_kind=k
  ) select array_agg(id) into party_ids from lineage;
  select coalesce(array_agg(distinct d.context_id),'{}'::uuid[]) into ctx from crm_private.identity_designations d where d.party_id=any(party_ids) and d.admin_scope=s;
  ctx:=ctx||party_ids;
 end if;
 select coalesce(array_agg(b.booking_id),'{}'::uuid[]),coalesce(array_agg(b.opportunity_id),'{}'::uuid[]) into bids,opps
 from crm_private.b04_bookings b where b.admin_scope=s and
  (k='booking' and b.booking_id=root or k<>'booking' and b.opportunity_id=any(ctx));
 if k='opportunity' then opps:=opps||root;end if;
 ctx:=ctx||bids||opps;
 select coalesce(array_agg(p.proposal_id),'{}'::uuid[]) into props from crm_private.b03_proposals p where p.admin_scope=s and p.opportunity_id=any(opps);
 select coalesce(array_agg(v.service_id),'{}'::uuid[]) into sids from crm_private.b04_services v where v.admin_scope=s and v.booking_id=any(bids);
 ctx:=ctx||props||sids;
 select coalesce(array_agg(x.schedule_id),'{}'::uuid[]) into schedules from crm_private.b05_payment_schedules x where x.admin_scope=s and x.booking_id=any(bids);
 select coalesce(array_agg(x.determination_id),'{}'::uuid[]) into determinations from crm_private.b06_cancellation_determinations x where x.admin_scope=s and x.booking_id=any(bids);
 select coalesce(array_agg(r.record_id),'{}'::uuid[]) into record_ids from crm_private.b07_records r where r.admin_scope=s
  and exists(select 1 from crm_private.b07_links l where l.record_id=r.record_id and l.admin_scope=s and l.context_id=any(ctx));
 select coalesce(array_agg(t.task_id),'{}'::uuid[]) into task_ids from crm_private.b07_pending_tasks t where t.admin_scope=s and t.identity->>'contextId'=any(ctx::text[]);

 -- External outputs use the existing commercial semantics, with an explicit
 -- permitted list. No terms/free text, original bodies, economic histories,
 -- personal identities, provider costs or technical receipts leave this branch.
 select coalesce(jsonb_agg(jsonb_build_object('reference',pv.version_id,'finalPersonPrice',
  case when m.final_person_price is null then null else to_char(m.final_person_price,'FM9999999999999999999999999999990.00') end,
  'participants',m.participants,'included',(select coalesce(jsonb_agg(jsonb_build_object('service',cr.definition->>'name','quantity',l.quantity,'date',l.service_date) order by l.line_id),'[]')
   from crm_private.b03_proposal_lines l join crm_private.catalog_revisions cr on cr.revision_id=l.service_revision_id
   where l.version_id=pv.version_id and l.modality_id=m.modality_id and l.included))order by pv.version_id,m.modality_id),'[]') into commercial
 from crm_private.b03_proposal_versions pv join crm_private.b03_proposal_modalities m using(version_id)
 where pv.admin_scope=s and pv.proposal_id=any(props) and
 (k<>'booking' or pv.version_id in(select version_id from crm_private.b04_bookings where booking_id=any(bids)))
 and m.definitive;
 if a->>'destination'<>'administrator' then
  r:=jsonb_build_object('contextKind',k,'contextId',root,'commercial',commercial,'facts','[]'::jsonb,'calendar','[]'::jsonb);
 else
  -- This fixed catalogue is reviewed against the prior migrations. It does not
  -- discover new tables or expose private schemas automatically.
  for item in select * from (values
   ('identity_entities','identity_id',party_ids),('identity_contexts','context_id',ctx),('identity_designations','context_id',ctx),
   ('identity_operations','result_ref',ctx),('b07_operations','result_ref',record_ids||task_ids),
   ('b07_communication_work','record_id',record_ids),('b09_external_event_keys','context_id',ctx),
   ('b04_bookings','booking_id',bids),('b04_services','booking_id',bids),
   (case when a->>'surface'='calendar' then 'b04_current_nights' else 'b04_nights' end,'service_id',sids),
   ('b04_modalities','booking_id',bids),('b04_contributions','booking_id',bids),('b04_history','booking_id',bids),
   ('b03_opportunities','opportunity_id',opps),('b03_history','subject_id',opps),
   ('b03_proposals','proposal_id',props),('b03_proposal_versions','proposal_id',props),('b03_proposal_history','proposal_id',props),
   ('b03_acceptances','opportunity_id',opps),('b03_acceptance_verifications','acceptance_id',
    array(select acceptance_id from crm_private.b03_acceptances where admin_scope=s and opportunity_id=any(opps))),
   ('b03_acceptance_rectifications','acceptance_id',array(select acceptance_id from crm_private.b03_acceptances where admin_scope=s and opportunity_id=any(opps))),
   ('b05_payment_schedules','booking_id',bids),('b05_schedule_revisions','schedule_id',schedules),('b05_expected_payments','schedule_id',schedules),
   ('b05_obligation_history','booking_id',bids),('b05_allocations','booking_id',bids),('b05_reconciliations','booking_id',bids),
   ('b05_provider_invoices','booking_id',bids),('b05_suplidos','booking_id',bids),('b05_provider_payments','booking_id',bids),
   ('b05_own_economies','booking_id',bids),('b05_refunds','booking_id',bids),('b05_deposits','booking_id',bids),
   ('b04_availability','booking_id',bids),('b04_confirmations','booking_id',bids),
   ('b04_operational_versions','booking_id',bids),('b06_modifications','booking_id',bids),
   ('b06_cancellation_determinations','booking_id',bids),('b06_cancellation_revisions','determination_id',determinations),
   ('b06_cancellation_applications','booking_id',bids),('b04_preparation_evaluations','booking_id',bids),('b04_reality_events','booking_id',bids),
   ('b07_requirements','booking_id',bids),('b07_incidents','booking_id',bids),
   ('b04_holds','opportunity_id',opps),('identity_codes','target_id',ctx),
   ('b05_own_economic_revisions','economy_id',array(select economy_id from crm_private.b05_own_economies where admin_scope=s and booking_id=any(bids)))
  ) as catalogue(tab,key,ids) loop
   if item.tab='b04_current_nights' then
    -- The current-night view resolves dates into the accepted row type, which
    -- has no cancellation field. Preserve that projection and attach the
    -- existing canonical scope state; never infer cancellation across scopes.
    select coalesce(jsonb_agg(jsonb_build_object('kind','b04_current_nights','data',
     to_jsonb(n)||jsonb_build_object(
      'operational_source','crm_private.modification_scope',
      'operational',crm_private.modification_scope(jsonb_build_object('kind','night','id',n.night_id,'serviceId',n.service_id),v.booking_id,s),
      'service_operational',jsonb_build_object('id',v.service_id,'revision',sc.value->'revision','cancelled',sc.value->'cancelled'),
      'booking_operational',jsonb_build_object('id',v.booking_id,'revision',bc.value->'revision','cancelled',bc.value->'cancelled')
     )) order by n.night_id),'[]') into rows
     from crm_private.b04_current_nights n
     join crm_private.b04_services v on v.service_id=n.service_id and v.admin_scope=s
     cross join lateral(select crm_private.modification_scope(jsonb_build_object('kind','service','id',v.service_id),v.booking_id,s) value) sc
     cross join lateral(select crm_private.modification_scope(jsonb_build_object('kind','booking','id',v.booking_id),v.booking_id,s) value) bc
     where n.admin_scope=s and n.service_id=any(item.ids) and v.booking_id=any(bids);
   else
    execute format('select coalesce(jsonb_agg(jsonb_build_object(''kind'',%L,''data'',to_jsonb(x)) order by to_jsonb(x)::text),''[]'') from crm_private.%I x where x.admin_scope=$1 and (to_jsonb(x)->>%L)=any($2::text[])',item.tab,item.tab,item.key)
     into rows using s,item.ids;
   end if;
   facts:=facts||rows;
  end loop;
  select coalesce(jsonb_agg(jsonb_build_object('kind','identity_history','data',to_jsonb(x)) order by x.recorded_at,x.history_id),'[]') into rows
   from crm_private.identity_history x join crm_private.identity_operations o using(operation_id)
   where o.admin_scope=s and (x.subject_id=any(ctx) or x.related_id=any(ctx));facts:=facts||rows;
  select coalesce(jsonb_agg(jsonb_build_object('kind','b03_acceptance_history','data',to_jsonb(x)) order by x.recorded_at,x.history_id),'[]') into rows
   from crm_private.b03_acceptance_history x join crm_private.b03_acceptance_operations o on o.operation_id=x.history_id
   where x.admin_scope=s and o.admin_scope=s and o.proposal_id=any(props);facts:=facts||rows;
  -- F02: identity rows do not contain the operational state. Read the existing
  -- canonical revisions within the same authorized roots; calendar uses only
  -- the latest revision, while timeline retains every historical revision.
  select coalesce(jsonb_agg(jsonb_build_object('kind','b04_hold_revisions','data',to_jsonb(x)) order by x.hold_id,x.revision),'[]') into rows
   from crm_private.b04_hold_revisions x join crm_private.b04_holds h on h.hold_id=x.hold_id
   where x.admin_scope=s and h.admin_scope=s and h.opportunity_id=any(opps)
    and (a->>'surface'<>'calendar' or x.revision=(select max(y.revision) from crm_private.b04_hold_revisions y where y.hold_id=x.hold_id and y.admin_scope=s));
  facts:=facts||rows;
  select coalesce(jsonb_agg(jsonb_build_object('kind','b07_requirement_revisions','data',to_jsonb(x)) order by x.requirement_id,x.revision),'[]') into rows
   from crm_private.b07_requirement_revisions x join crm_private.b07_requirements h on h.requirement_id=x.requirement_id
   where x.admin_scope=s and h.admin_scope=s and h.booking_id=any(bids)
    and (a->>'surface'<>'calendar' or x.revision=(select max(y.revision) from crm_private.b07_requirement_revisions y where y.requirement_id=x.requirement_id and y.admin_scope=s));
  facts:=facts||rows;
  -- Links returned only for the explicit scope, never all contexts of a shared original.
  select coalesce(jsonb_agg(jsonb_build_object('kind','b07_records','data',to_jsonb(x),'links',
   (select jsonb_agg(to_jsonb(l)) from crm_private.b07_links l where l.record_id=x.record_id and l.admin_scope=s and l.context_id=any(ctx)))order by x.recorded_at,x.record_id),'[]') into originals
   from crm_private.b07_records x where x.admin_scope=s and exists(select 1 from crm_private.b07_links l where l.record_id=x.record_id and l.admin_scope=s and l.context_id=any(ctx));
  facts:=facts||originals;
  select coalesce(jsonb_agg(jsonb_build_object('kind','b07_history','data',to_jsonb(x))order by x.recorded_at,x.history_id),'[]') into rows
   from crm_private.b07_history x where x.admin_scope=s and x.subject_id=any(record_ids||task_ids);facts:=facts||rows;
  select coalesce(jsonb_agg(jsonb_build_object('kind','b09_event_receipts','data',to_jsonb(x))order by x.received_at,x.operation_id),'[]') into rows
   from crm_private.b09_event_receipts x where x.admin_scope=s and x.raw_event->>'context_id'=any(ctx::text[]);facts:=facts||rows;
  select coalesce(jsonb_agg(jsonb_build_object('kind','b07_pending_tasks','data',to_jsonb(x))order by task_id),'[]') into rows
   from crm_private.b07_pending_tasks x where x.admin_scope=s and x.identity->>'contextId'=any(ctx::text[]);facts:=facts||rows;
  select coalesce(jsonb_agg(jsonb_build_object('reference',v.service_id,'bookingId',v.booking_id,
   'source','crm_private.modification_scope','scope',crm_private.modification_scope(jsonb_build_object('kind','service','id',v.service_id),v.booking_id,s),
   'phase',crm_private.reality_phase(v.booking_id,s),
   'certainty',case when crm_private.modification_scope(jsonb_build_object('kind','service','id',v.service_id),v.booking_id,s)->>'date' is null
    or crm_private.modification_scope(jsonb_build_object('kind','service','id',v.service_id),v.booking_id,s)->'schedule'='null'::jsonb
    or crm_private.reality_phase(v.booking_id,s) is null then 'pending' else 'verified' end)order by v.service_id),'[]') into calendar
   from crm_private.b04_services v where v.booking_id=any(bids) and v.admin_scope=s;
  r:=jsonb_build_object('contextKind',k,'contextId',root,'commercial',commercial,'facts',facts,'calendar',calendar);
 end if;
 perform crm_f2.verify(f2p,f2s,q,'C01','human_evidence','read_evidence');
 perform crm_f1.verify_envelope(f1p,f1s,q,'C01','evidence','read_evidence');
 return r;
end $function$

CREATE OR REPLACE FUNCTION crm_api.hold_apply(f2p bytea, f2s bytea, f1p bytea, f1s bytea, q bytea, tf2p bytea, tf2s bytea, tf1p bytea, tf1s bytea, tq bytea)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare hf text[];tf text[];fs text[];a jsonb;op uuid;iid uuid;opp uuid;actor uuid;s text;action text;fp text;proofhash text;rev bigint;at_time timestamptz;
 prev crm_private.b04_hold_operations;root crm_private.b04_holds;old jsonb;state jsonb;r jsonb;data jsonb;p jsonb;v jsonb;parts jsonb;selection jsonb;amount numeric;remaining numeric;
 fact crm_private.b04_hold_revisions;known boolean:=false;follow boolean:=false;task jsonb;task_id uuid;entry jsonb;record crm_private.b07_records;
begin
 hf:=crm_f2.admit(f2p,f2s,q,'C03','write_evidence');tf:=crm_f1.verify_envelope(f1p,f1s,q,'C03','evidence','write_evidence');
 if hf[17] collate "C" is distinct from tf[14] collate "C" then raise exception 'HOLD_DENIED';end if;
 fs:=crm_f1.fields(q);if cardinality(fs)<>2 or fs[1]<>'CRM-H4-HOLD1' then raise exception 'HOLD_INPUT_INVALID';end if;a:=fs[2]::jsonb;
 if jsonb_typeof(a) is distinct from 'object' or not(a ?& array['action','operationId','holdId','opportunityId','expectedRevision','expectedOpportunityRevision','sourceRef','reason','at','evidenceId','data'])
 or a-array['action','operationId','holdId','opportunityId','expectedRevision','expectedOpportunityRevision','sourceRef','reason','at','evidenceId','data','origin']<>'{}'::jsonb
 or exists(select 1 from unnest(array['action','operationId','holdId','opportunityId','sourceRef','reason','evidenceId']) k where not coalesce(crm_private.invoice_text(a->k),false))
 or not coalesce(crm_private.availability_time(a->'at'),false) or jsonb_typeof(a->'data') is distinct from 'object'
 or coalesce(a->>'expectedRevision','')!~'^(0|[1-9][0-9]*)$' or coalesce(a->>'expectedOpportunityRevision','')!~'^[1-9][0-9]*$' or coalesce(a->>'origin','manual')<>'manual' then raise exception 'HOLD_INPUT_INVALID';end if;
 op:=(a->>'operationId')::uuid;iid:=(a->>'holdId')::uuid;opp:=(a->>'opportunityId')::uuid;actor:=hf[12]::uuid;s:=hf[17];action:=a->>'action';data:=a->'data';at_time:=(a->>'at')::timestamptz;
 if action not in ('grant','check','near','invalidate','request','release','extend','link') then raise exception 'HOLD_INPUT_INVALID';end if;
 if not exists(select 1 from crm_private.b03_opportunities where opportunity_id=opp and admin_scope=s) then raise exception 'HOLD_DENIED';end if;
 -- Same parent lock/order as real H2 conversion; protects first roots and link/conversion race.
 perform pg_advisory_xact_lock(hashtextextended(opp::text,31));
 perform pg_advisory_xact_lock(hashtextextended('hold:'||iid,0));
 select * into root from crm_private.b04_holds where hold_id=iid;
 if (action<>'grant' and root.hold_id is null) or (root.hold_id is not null and (root.opportunity_id<>opp or root.admin_scope<>s)) then raise exception 'HOLD_DENIED';end if;
 fp:=encode(crm_crypto.digest(convert_to(a::text,'UTF8'),'sha256'),'hex');perform pg_advisory_xact_lock(hashtextextended('hold-op:'||op,0));
 select * into prev from crm_private.b04_hold_operations where operation_id=op;
 if found then
  if prev.admin_scope<>s or prev.actor_id<>actor or prev.fingerprint<>fp then raise exception 'HOLD_REPLAY_CONFLICT:E2';end if;r:=prev.result||jsonb_build_object('replayed',true);
 else
  proofhash:=encode(crm_crypto.digest(convert_to((a-array['operationId','evidenceId'])::text,'UTF8'),'sha256'),'hex');
  if not crm_private.payment_evidence((a->>'evidenceId')::uuid,iid,s,'hold:'||action||':'||proofhash,at_time,true)
  or not exists(select 1 from crm_private.b07_records where record_id=(a->>'evidenceId')::uuid and recorded_by=actor) then raise exception 'HOLD_EVIDENCE_REQUIRED:E3';end if;
  if data?'factId' then
   perform (data->>'factId')::uuid;
   perform pg_advisory_xact_lock(hashtextextended('hold-fact:'||(data->>'factId'),0));
   select * into fact from crm_private.b04_hold_revisions where admin_scope=s and event->'data'->>'factId'=data->>'factId';
   if found then
    if fact.action_kind<>action or fact.event->'data' is distinct from data or not exists(select 1 from crm_private.b04_holds where hold_id=fact.hold_id and opportunity_id=opp and admin_scope=s) then raise exception 'HOLD_FACT_CONFLICT:E2';end if;
    if action<>'grant' and fact.hold_id<>iid then raise exception 'HOLD_FACT_CONFLICT:E2';end if;
    iid:=fact.hold_id;select * into root from crm_private.b04_holds where hold_id=iid;known:=true;
   end if;
  end if;
  if root.hold_id is not null then select revision,after_data into rev,old from crm_private.b04_hold_revisions where hold_id=iid order by revision desc limit 1;end if;
  if not known and action in ('check','near','invalidate','request','link') and exists(select 1 from crm_private.b04_hold_revisions where hold_id=iid and admin_scope=s and action_kind=action and event->'data'=data) then known:=true;end if;
  if known then state:=old;
  else
   if coalesce(rev,0)<>(a->>'expectedRevision')::bigint or not exists(select 1 from crm_private.b03_opportunities where opportunity_id=opp and admin_scope=s and revision=(a->>'expectedOpportunityRevision')::bigint) then raise exception 'HOLD_REVISION_CONFLICT:E2';end if;
   state:=old;
   if action='grant' then
    if root.hold_id is not null or data-array['providerRevisionId','externalRef','factId','recordId','happenedAt','certainty','parts','replacesHoldId']<>'{}'::jsonb
    or not(data ?& array['providerRevisionId','externalRef','factId','recordId','happenedAt','certainty','parts','replacesHoldId']) or data->>'certainty' is distinct from 'granted'
    or not coalesce(crm_private.invoice_text(data->'externalRef'),false) or not coalesce(crm_private.availability_time(data->'happenedAt'),false) or (data->>'happenedAt')::timestamptz>at_time
    or jsonb_typeof(data->'parts') is distinct from 'array' or jsonb_array_length(data->'parts')=0
    or exists(select 1 from jsonb_array_elements(data->'parts') x where not coalesce(crm_private.hold_part(x,opp,s),false))
    or (select count(*)<>count(distinct x->>'id') from jsonb_array_elements(data->'parts') x)
    or not exists(select 1 from crm_private.catalog_revisions r join crm_private.catalog_items i using(item_id) where r.revision_id=(data->>'providerRevisionId')::uuid and r.admin_scope=s and i.admin_scope=s and i.item_kind='provider')
    or not coalesce(crm_private.hold_record((data->>'recordId')::uuid,opp,s),false) then raise exception 'HOLD_GRANT_REQUIRED:E3';end if;
    perform pg_advisory_xact_lock(hashtextextended('hold-resource:'||(data->>'providerRevisionId')||':'||(data->>'externalRef'),0));
    if exists(select 1 from crm_private.b04_holds where admin_scope=s and provider_revision_id=(data->>'providerRevisionId')::uuid and external_ref=data->>'externalRef') then raise exception 'HOLD_IDENTITY_CONFLICT:E2';end if;
    if data->'replacesHoldId'<>'null'::jsonb and not exists(select 1 from crm_private.b04_holds where hold_id=(data->>'replacesHoldId')::uuid and opportunity_id=opp and admin_scope=s and provider_revision_id=(data->>'providerRevisionId')::uuid) then raise exception 'HOLD_SUBSTITUTION_REQUIRED:E3';end if;
    parts:='[]';for p in select value from jsonb_array_elements(data->'parts') loop
     if p->'expiresAt'<>'null'::jsonb and (p->>'expiresAt')::timestamptz<=(data->>'happenedAt')::timestamptz then raise exception 'HOLD_EXPIRY_REQUIRED:E3';end if;
     parts:=parts||jsonb_build_array(jsonb_build_object('terms',p,'remaining',p->>'quantity','validity','Creado','verified',null,'request',null,'review',null,'near',null,'link',null,'lastFactAt',data->'happenedAt'));
     if p->'expiresAt'='null'::jsonb then follow:=true;end if;
    end loop;
    state:=jsonb_build_object('id',iid,'opportunityId',opp,'providerRevisionId',data->'providerRevisionId','externalRef',data->'externalRef','grant',data,'parts',parts,'replacesHoldId',data->'replacesHoldId');
   else
    if old is null then raise exception 'HOLD_DENIED';end if;
    if action in ('release','extend') then
     if data-array['selections','factId','recordId','happenedAt','providerRevisionId','authority','unequivocal','certainty','basis']<>'{}'::jsonb
     or not(data ?& array['selections','factId','recordId','happenedAt','providerRevisionId','authority','unequivocal','certainty','basis'])
     or data->'providerRevisionId' is distinct from old->'providerRevisionId' or data->'authority' is distinct from 'true'::jsonb or data->'unequivocal' is distinct from 'true'::jsonb
     or data->>'certainty' is distinct from (case action when 'release' then 'released' else 'extended' end)
     or not coalesce(crm_private.invoice_text(data->'basis'),false) or not coalesce(crm_private.availability_time(data->'happenedAt'),false) or (data->>'happenedAt')::timestamptz>at_time
     or not coalesce(crm_private.hold_record((data->>'recordId')::uuid,opp,s),false) or jsonb_typeof(data->'selections') is distinct from 'array' or jsonb_array_length(data->'selections')=0
     or (select count(*)<>count(distinct x->>'partId') from jsonb_array_elements(data->'selections') x) then raise exception 'HOLD_RESPONSE_REQUIRED:E3';end if;
    else
     if jsonb_typeof(data->'partIds') is distinct from 'array' or jsonb_array_length(data->'partIds')=0 or (select count(*)<>count(distinct x) from jsonb_array_elements_text(data->'partIds') x) then raise exception 'HOLD_SCOPE_REQUIRED:E3';end if;
    end if;
    if exists(select 1 from jsonb_array_elements(case when action in ('release','extend') then data->'selections' else (select jsonb_agg(jsonb_build_object('partId',x)) from jsonb_array_elements_text(data->'partIds') x) end) x where not exists(select 1 from jsonb_array_elements(old->'parts') y where y->'terms'->>'id'=x->>'partId')) then raise exception 'HOLD_SCOPE_REQUIRED:E3';end if;
    parts:='[]';
    for p in select value from jsonb_array_elements(old->'parts') loop
     selection:=null;
     if action in ('release','extend') then select value into selection from jsonb_array_elements(data->'selections') where value->>'partId'=p->'terms'->>'id';end if;
     if selection is not null or data->'partIds' ? (p->'terms'->>'id') then
      remaining:=(p->>'remaining')::numeric;
      if remaining<=0 then raise exception 'HOLD_RELEASED:E3';end if;
      if action in ('release','extend') then
       if selection-array['partId','quantity','unitRevisionId','date','expiresAt','conditions','newPartId','newDate']<>'{}'::jsonb or not(selection ?& array['partId','quantity','unitRevisionId','date'])
       or coalesce(selection->>'quantity','')!~'^[0-9]+(\.[0-9]+)?$' or (selection->>'quantity')::numeric<=0 or (selection->>'quantity')::numeric>remaining
       or selection->'unitRevisionId' is distinct from p->'terms'->'unitRevisionId' or selection->'date' is distinct from p->'terms'->'date' then raise exception 'HOLD_PORTION_REQUIRED:E3';end if;
       if (data->>'happenedAt')::timestamptz<=(p->>'lastFactAt')::timestamptz then raise exception 'HOLD_PRECEDENCE_REQUIRED:E8';end if;
       amount:=(selection->>'quantity')::numeric;
       if action='release' then
        if selection-array['partId','quantity','unitRevisionId','date']<>'{}'::jsonb then raise exception 'HOLD_PORTION_REQUIRED:E3';end if;
        p:=p||jsonb_build_object('remaining',(remaining-amount)::text,'lastFactAt',data->'happenedAt','release',jsonb_build_object('fact',data,'selection',selection,'evidenceId',a->'evidenceId','actorId',actor,'at',at_time));
        if remaining=amount then p:=p||jsonb_build_object('validity','Liberado','verified',null,'near',null);else p:=p||jsonb_build_object('validity','No verificado','verified',null);follow:=true;end if;
       else
        if not(selection ?& array['expiresAt','conditions']) or not coalesce(crm_private.invoice_text(selection->'conditions'),false)
        or not coalesce(crm_private.availability_time(selection->'expiresAt'),false) or (selection->>'expiresAt')::timestamptz<=at_time then raise exception 'HOLD_EXTENSION_REQUIRED:E3';end if;
        if selection?'newDate' then
         if coalesce(selection->>'newDate','')!~'^[0-9]{4}-[0-9]{2}-[0-9]{2}$' then raise exception 'HOLD_EXTENSION_REQUIRED:E3';end if;perform (selection->>'newDate')::date;
        end if;
        if amount<remaining then
         if not coalesce(crm_private.invoice_text(selection->'newPartId'),false) then raise exception 'HOLD_SPLIT_REQUIRED:E3';end if;perform (selection->>'newPartId')::uuid;
         if exists(select 1 from jsonb_array_elements(old->'parts') x where x->'terms'->>'id'=selection->>'newPartId') then raise exception 'HOLD_SPLIT_REQUIRED:E3';end if;
         v:=p||jsonb_build_object('terms',(p->'terms')||jsonb_build_object('id',selection->'newPartId','quantity',amount::text,'expiresAt',selection->'expiresAt','conditions',selection->'conditions','date',coalesce(selection->'newDate',p->'terms'->'date')),'remaining',amount::text,'parentPartId',p->'terms'->'id','validity','No verificado','verified',null,'near',null,'review',jsonb_build_object('cause','Prórroga parcial acreditada','before',p,'after',selection,'result','new-scope','evidenceId',a->'evidenceId'),'lastFactAt',data->'happenedAt');
         if selection?'newDate' and selection->'newDate' is distinct from p->'terms'->'date' then v:=v||jsonb_build_object('link',null);end if;
         parts:=parts||jsonb_build_array(v);p:=p||jsonb_build_object('remaining',(remaining-amount)::text);
        else
         if selection?'newPartId' then raise exception 'HOLD_SPLIT_REQUIRED:E3';end if;
         p:=p||jsonb_build_object('terms',(p->'terms')||jsonb_build_object('expiresAt',selection->'expiresAt','conditions',selection->'conditions','date',coalesce(selection->'newDate',p->'terms'->'date')),'validity','No verificado','verified',null,'near',null,'review',jsonb_build_object('cause','Términos nuevos acreditados','before',p,'after',selection,'result','new-scope','evidenceId',a->'evidenceId'),'lastFactAt',data->'happenedAt');
         if selection?'newDate' then p:=p||jsonb_build_object('link',null);end if;
        end if;follow:=true;
       end if;
      elsif action='check' then
       if data-array['partIds','actionAt','actionUntil','happenedAt','recordId','providerRevisionId','authority','conditionsMet','basis']<>'{}'::jsonb or not(data ?& array['actionAt','actionUntil','happenedAt','recordId','providerRevisionId','authority','conditionsMet','basis'])
       or data->'providerRevisionId' is distinct from old->'providerRevisionId' or data->'authority' is distinct from 'true'::jsonb or data->'conditionsMet' is distinct from 'true'::jsonb or not coalesce(crm_private.invoice_text(data->'basis'),false)
       or not coalesce(crm_private.availability_time(data->'happenedAt'),false) or not coalesce(crm_private.availability_time(data->'actionAt'),false) or not coalesce(crm_private.availability_time(data->'actionUntil'),false)
       or (data->>'happenedAt')::timestamptz<(p->>'lastFactAt')::timestamptz or (data->>'happenedAt')::timestamptz>at_time or at_time>(data->>'actionAt')::timestamptz or (data->>'actionUntil')::timestamptz<(data->>'actionAt')::timestamptz
       or not coalesce(crm_private.hold_record((data->>'recordId')::uuid,opp,s),false) then raise exception 'HOLD_CHECK_REQUIRED:E3';end if;
       if p->'terms'->'expiresAt'<>'null'::jsonb and (data->>'actionUntil')::timestamptz>=(p->'terms'->>'expiresAt')::timestamptz then raise exception 'HOLD_EXPIRED:E3';end if;
       p:=p||jsonb_build_object('validity','Vigente','verified',data||jsonb_build_object('evidenceId',a->'evidenceId','actorId',actor,'at',at_time),'review',null);
       if p->'terms'->'expiresAt'='null'::jsonb then follow:=true;end if;
      elsif action='near' then
       if data-array['partIds','evaluatedAt','advance']<>'{}'::jsonb or p->>'validity'<>'Vigente' or not coalesce(crm_private.availability_time(data->'evaluatedAt'),false)
       or (data->>'evaluatedAt')::timestamptz<>at_time or p->'terms'->'expiresAt'='null'::jsonb or jsonb_typeof(data->'advance') is distinct from 'object' or (data->'advance')-array['seconds','sourceRef','version']<>'{}'::jsonb
       or coalesce(data->'advance'->>'seconds','')!~'^[1-9][0-9]*$' or not coalesce(crm_private.invoice_text(data->'advance'->'sourceRef'),false) or not coalesce(crm_private.invoice_text(data->'advance'->'version'),false)
       or (data->>'evaluatedAt')::timestamptz>=(p->'terms'->>'expiresAt')::timestamptz or (data->>'evaluatedAt')::timestamptz<(p->'terms'->>'expiresAt')::timestamptz-make_interval(secs=>(data->'advance'->>'seconds')::double precision) then raise exception 'HOLD_ADVANCE_REQUIRED:E3';end if;
       p:=p||jsonb_build_object('near',data||jsonb_build_object('evidenceId',a->'evidenceId'));follow:=true;
      elsif action='invalidate' then
       if data-array['partIds','cause','result','before','after','dependencies']<>'{}'::jsonb or not(data ?& array['cause','result','before','after','dependencies'])
       or not coalesce(crm_private.invoice_text(data->'cause'),false) or data->'before' is distinct from old->'parts' or data->'dependencies' is distinct from data->'partIds'
       or jsonb_typeof(data->'after') is distinct from 'object' or coalesce(data->>'result' not in ('expired','uncertain'),true) then raise exception 'HOLD_REVIEW_REQUIRED:E3';end if;
       if data->>'result'='expired' and (p->'terms'->'expiresAt'='null'::jsonb or at_time<(p->'terms'->>'expiresAt')::timestamptz) then raise exception 'HOLD_EXPIRY_REQUIRED:E3';end if;
       p:=p||jsonb_build_object('validity',case data->>'result' when 'expired' then 'Vencido' else 'No verificado' end,'review',data||jsonb_build_object('evidenceId',a->'evidenceId','actorId',actor,'at',at_time),'near',null);follow:=true;
      elsif action='request' then
       if data-array['partIds','decision','communicationFactId','sentAt','providerRevisionId','basis']<>'{}'::jsonb or not(data ?& array['decision','communicationFactId','sentAt','providerRevisionId','basis'])
       or not coalesce(crm_private.invoice_text(data->'decision'),false) or not coalesce(crm_private.invoice_text(data->'basis'),false) or data->'providerRevisionId' is distinct from old->'providerRevisionId'
       or not coalesce(crm_private.availability_time(data->'sentAt'),false) or (data->>'sentAt')::timestamptz>at_time then raise exception 'HOLD_REQUEST_REQUIRED:E3';end if;
       select * into record from crm_private.b07_records where record_id=(data->>'communicationFactId')::uuid and admin_scope=s and record_kind='communication_fact' and material->>'fact_kind'='sent'
       and material->>'party_ref'=old->>'providerRevisionId' and material->>'coverage'=iid::text and occurred_at=(data->>'sentAt')::timestamptz;
       if record.record_id is null or not coalesce(crm_private.hold_record(record.record_id,opp,s),false)
       or not exists(select 1 from crm_private.b07_records where record_id=record.original_id and admin_scope=s and record_kind='communication' and material->>'direction'='outgoing' and material->>'recipient_ref'=old->>'providerRevisionId') then raise exception 'HOLD_SENT_REQUIRED:E3';end if;
       p:=p||jsonb_build_object('request',data||jsonb_build_object('status','Liberación solicitada','evidenceId',a->'evidenceId','actorId',actor,'at',at_time));
      else
       if data-array['partIds','bookingId','serviceId','nightId','bookingRevision','serviceRevision','conditionsChecked','scopeRevision']<>'{}'::jsonb or not(data ?& array['bookingId','serviceId','nightId','bookingRevision','serviceRevision','conditionsChecked']) or data->'conditionsChecked' is distinct from 'true'::jsonb
       or p->>'validity'<>'Vigente' or p->'review'<>'null'::jsonb or (p->'verified'->>'actionAt')::timestamptz is distinct from at_time or (p->'terms'->'expiresAt'<>'null'::jsonb and at_time>=(p->'terms'->>'expiresAt')::timestamptz)
       or not exists(select 1 from crm_private.b04_bookings b join crm_private.b04_current_services bs using(booking_id) join crm_private.b04_contributions c on c.service_id=bs.service_id join crm_private.b03_proposal_lines pl on pl.version_id=c.version_id and pl.line_id=c.line_id
       where b.opportunity_id=opp and b.admin_scope=s and bs.admin_scope=s and b.booking_id=(data->>'bookingId')::uuid and bs.service_id=(data->>'serviceId')::uuid
       and b.revision::text=data->>'bookingRevision' and bs.revision::text=data->>'serviceRevision' and c.version_id=(p->'terms'->>'versionId')::uuid and c.line_id=(p->'terms'->>'lineId')::uuid and bs.service_revision_id=(p->'terms'->>'serviceRevisionId')::uuid and coalesce(bs.applied->'variant','null'::jsonb)=p->'terms'->'variantRevisionId' and (crm_private.modification_reference(jsonb_build_object('kind','service','id',bs.service_id),b.booking_id,s) is null or crm_private.modification_reference(jsonb_build_object('kind','service','id',bs.service_id),b.booking_id,s)=(p->'terms'->>'date')::date))
       or (data->'nightId'<>'null'::jsonb and not exists(select 1 from crm_private.b04_current_nights where night_id=(data->>'nightId')::uuid and service_id=(data->>'serviceId')::uuid and admin_scope=s and night_date=(p->'terms'->>'date')::date))
       or not crm_private.modification_hold_link(data,p->'terms',s) then raise exception 'HOLD_LINK_REQUIRED:E3';end if;
       if p->'link'<>'null'::jsonb and p->'link' is distinct from data and ((p->'link')-array['scopeRevision','serviceRevision'] is distinct from data-array['scopeRevision','serviceRevision'] or not crm_private.modification_hold_link(data,p->'terms',s)) then raise exception 'HOLD_LINK_CONFLICT:E2';end if;
       p:=p||jsonb_build_object('link',data);
      end if;
     end if;
     parts:=parts||jsonb_build_array(p);
    end loop;
    if (select count(*)<>count(distinct x->'terms'->>'id') from jsonb_array_elements(parts) x) then raise exception 'HOLD_SPLIT_REQUIRED:E3';end if;
    state:=state||jsonb_build_object('parts',parts);
   end if;
   rev:=coalesce(rev,0)+1;state:=state||jsonb_build_object('revision',rev);
  end if;
  r:=jsonb_build_object('id',iid,'replayed',known,'result',state);
  if root.hold_id is null then insert into crm_private.b04_holds values(iid,opp,s,(data->>'providerRevisionId')::uuid,data->>'externalRef',op);end if;
  if old is distinct from state then insert into crm_private.b04_hold_revisions values(iid,rev,s,op,action,a,old,state,actor,(a->>'evidenceId')::uuid,a->>'sourceRef',a->>'reason',at_time,clock_timestamp());end if;
  if follow then
   fs:=crm_f1.fields(tq);task:=fs[2]::jsonb;
   if fs[1]<>'CRM-H1-TASK-1' or task->>'taskId'<>iid::text or task->>'operationId'<>op::text or task->'identity' is distinct from jsonb_build_object('causeKind','block','causeId',iid,'contextKind','opportunity','contextId',opp,'scopeRef',iid,'effect','hold-review')
   or task->'material' is distinct from '{"title":"Revisar opción y cobertura del alcance","deadline":{"kind":"unknown","reason":"No consta fecha fijada para el seguimiento"},"priority":{"kind":"pending","reason":"Prioridad no configurada"},"sourceRef":"SM-HO","sourceVersion":"1","triggerRef":"BR-TASK-005","triggerVersion":"1"}'::jsonb then raise exception 'HOLD_TASK_REQUIRED';end if;
   select result_ref into task_id from crm_api.b07_task_apply(tf2p,tf2s,tf1p,tf1s,tq);
  end if;
  insert into crm_private.b04_hold_operations values(op,iid,s,actor,fp,r,rev,clock_timestamp());
 end if;
 perform crm_f2.verify(f2p,f2s,q,'C03','human_evidence','write_evidence');perform crm_f1.verify_envelope(f1p,f1s,q,'C03','evidence','write_evidence');return r;
end$function$

CREATE OR REPLACE FUNCTION crm_api.hold_read(f2p bytea, f2s bytea, f1p bytea, f1s bytea, q bytea)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare hf text[];tf text[];fs text[];a jsonb;s text;opp uuid;iid uuid;r jsonb;p jsonb;usable boolean;begin
 hf:=crm_f2.admit(f2p,f2s,q,'C01','read_evidence');tf:=crm_f1.verify_envelope(f1p,f1s,q,'C01','evidence','read_evidence');
 if hf[17] collate "C" is distinct from tf[14] collate "C" then raise exception 'HOLD_DENIED';end if;
 fs:=crm_f1.fields(q);if cardinality(fs)<>2 or fs[1]<>'CRM-H4-HOLD-READ1' then raise exception 'HOLD_INPUT_INVALID';end if;a:=fs[2]::jsonb;s:=hf[17];opp:=(a->>'opportunityId')::uuid;
 if a-array['holdId','opportunityId','projection']<>'{}'::jsonb or not(a ?& array['holdId','opportunityId']) then raise exception 'HOLD_INPUT_INVALID';end if;
 if not exists(select 1 from crm_private.b03_opportunities where opportunity_id=opp and admin_scope=s) then r:=null;
 else
  select hold_id into iid from crm_private.b04_holds where hold_id=(a->>'holdId')::uuid and opportunity_id=opp and admin_scope=s;
  select after_data into r from crm_private.b04_hold_revisions where hold_id=iid and admin_scope=s order by revision desc limit 1;
  if r is not null then
   if a?'projection' then
    if (a->'projection')-array['partId','actionAt','actionUntil','quantity','unitRevisionId','date']<>'{}'::jsonb or not(a->'projection' ?& array['partId','actionAt','actionUntil','quantity','unitRevisionId','date']) or not coalesce(crm_private.availability_time(a->'projection'->'actionAt'),false) or not coalesce(crm_private.availability_time(a->'projection'->'actionUntil'),false) or coalesce(a->'projection'->>'quantity','')!~'^[0-9]+(\.[0-9]+)?$' then raise exception 'HOLD_INPUT_INVALID';end if;
    select value into p from jsonb_array_elements(r->'parts') where value->'terms'->>'id'=a->'projection'->>'partId';
    usable:=coalesce(p->>'validity'='Vigente' and (p->>'remaining')::numeric>=(a->'projection'->>'quantity')::numeric and (a->'projection'->>'quantity')::numeric>0 and p->'terms'->'unitRevisionId'=a->'projection'->'unitRevisionId' and p->'terms'->'date'=a->'projection'->'date'
    and p->'review'='null'::jsonb and p->'verified'->'actionAt'=a->'projection'->'actionAt' and p->'verified'->'actionUntil'=a->'projection'->'actionUntil'
    and (p->'terms'->'expiresAt'='null'::jsonb or (a->'projection'->>'actionUntil')::timestamptz<(p->'terms'->>'expiresAt')::timestamptz),false);
    if p->'link'<>'null'::jsonb and (not crm_private.modification_hold_link(p->'link',p->'terms',s) or crm_private.modification_pending((p->'link'->>'bookingId')::uuid,(p->'link'->>'serviceId')::uuid,(select n.night_id from crm_private.b04_nights n where n.service_id=(p->'link'->>'serviceId')::uuid and n.night_date=(p->'terms'->>'date')::date limit 1),s)) then usable:=false;end if;r:=jsonb_build_object('id',iid,'revision',r->'revision','usable',usable,'remaining',p->'remaining','unitRevisionId',p->'terms'->'unitRevisionId','date',p->'terms'->'date','validity',p->'validity','expiresAt',p->'terms'->'expiresAt','releaseRequested',p->'request'<>'null'::jsonb,'revalidationNeeded',p->'terms'->'expiresAt'='null'::jsonb or p->'review'<>'null'::jsonb,'serviceState',case when p->'link'<>'null'::jsonb and usable then 'Opcionado / bloqueado' else null end,'serviceConfirmed',false,'firmReservation',false,'executed',false);
   else
    r:=r||jsonb_build_object('history',(select jsonb_agg(jsonb_build_object('revision',revision,'action',action_kind,'before',before_data,'after',after_data,'actorId',actor_id,'sourceRef',source_ref,'reason',reason,'evidenceId',evidence_id,'at',occurred_at,'recordedAt',recorded_at) order by revision) from crm_private.b04_hold_revisions where hold_id=iid and admin_scope=s));
   end if;
  end if;
 end if;
 perform crm_f2.verify(f2p,f2s,q,'C01','human_evidence','read_evidence');perform crm_f1.verify_envelope(f1p,f1s,q,'C01','evidence','read_evidence');return r;
end$function$

CREATE OR REPLACE FUNCTION crm_api.human_apply_probe_batch(f2p bytea, f2s bytea, f1p bytea, f1s bytea, q bytea)
 RETURNS text[]
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare hf text[]; tf text[]; result text[];
begin
  hf:=crm_f2.admit(f2p,f2s,q,'C03','apply_probe_batch');
  tf:=crm_f1.verify(f1p,f1s,q,'C03');
  if tf[14] collate "C"<>hf[17] collate "C" then
    raise exception 'F2_DENIED' using errcode='42501'; end if;
  perform crm_f2.verify(f2p,f2s,q,'C03','human_core_probe','apply_probe_batch');
  result:=crm_api.apply_probe_batch(f1p,f1s,q);
  perform crm_f2.verify(f2p,f2s,q,'C03','human_core_probe','apply_probe_batch');
  return result;
exception when others then raise exception 'F2_DENIED' using errcode='42501';
end $function$

CREATE OR REPLACE FUNCTION crm_api.human_read_probe(f2p bytea, f2s bytea, f1p bytea, f1s bytea, q bytea)
 RETURNS TABLE(probe_id text, public_value text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare hf text[]; tf text[];
begin
  hf:=crm_f2.admit(f2p,f2s,q,'C01','read_probe');
  tf:=crm_f1.verify(f1p,f1s,q,'C01');
  if tf[14] collate "C"<>hf[17] collate "C" then
    raise exception 'F2_DENIED' using errcode='42501'; end if;
  perform crm_f2.verify(f2p,f2s,q,'C01','human_core_probe','read_probe');
  return query select r.probe_id,r.public_value from crm_api.read_probe(f1p,f1s,q) r;
  perform crm_f2.verify(f2p,f2s,q,'C01','human_core_probe','read_probe');
exception when others then raise exception 'F2_DENIED' using errcode='42501';
end $function$

CREATE OR REPLACE FUNCTION crm_api.identity_apply(f2p bytea, f2s bytea, f1p bytea, f1s bytea, q bytea)
 RETURNS TABLE(result_ref uuid, result_version bigint, replayed boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare hf text[]; tf text[]; v text[]; op crm_private.identity_operations%rowtype;
  ent crm_private.identity_entities%rowtype; ctx crm_private.identity_contexts%rowtype;
  old_state jsonb; new_state jsonb; fingerprint text; target uuid; related uuid;
  context_ref uuid; history_context uuid; expected bigint; actor uuid; scope text; new_version bigint;
  candidate boolean; party_kind text; old_primary jsonb;
begin
  hf:=crm_f2.admit(f2p,f2s,q,'C03','write_identity');
  tf:=crm_f1.verify_envelope(f1p,f1s,q,'C03','identities','write_identity');
  if hf[17] collate "C" <> tf[14] collate "C" then
    raise exception 'IDENTITY_DENIED' using errcode='42501'; end if;
  v:=crm_f1.fields(q);
  if cardinality(v)<>22 or v[1]<>'CRM-H1-ID1' or v[2] not in
    ('create_context','create_entity','update_entity','link_organization_contact','designate')
    or v[3] is null or v[4] is null or v[9] is null or v[9]=''
    or v[11] is null or v[11]='' or v[12] !~ '^(0|[1-9][0-9]{0,18})$'
    or v[13] not in ('true','false')
  then raise exception 'IDENTITY_INPUT_INVALID' using errcode='22023'; end if;
  target:=v[4]::uuid; related:=nullif(v[5],'')::uuid;
  context_ref:=nullif(v[6],'')::uuid; expected:=v[12]::bigint;
  candidate:=v[13]='true'; actor:=hf[12]::uuid; scope:=hf[17];
  fingerprint:=encode(crm_crypto.digest(q,'sha256'),'hex');
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(v[3],0));
  select * into op from crm_private.identity_operations where operation_id=v[3]::uuid;
  if found then
    if op.actor_id<>actor or op.admin_scope<>scope or op.material_fingerprint<>fingerprint then
      raise exception 'IDENTITY_REPLAY_CONFLICT' using errcode='23505'; end if;
    perform crm_f2.verify(f2p,f2s,q,'C03','human_identities','write_identity');
    result_ref:=op.result_ref; result_version:=op.resulting_version;
    replayed:=true; return next; return;
  end if;
  old_state:=null;
  if v[2]='create_context' then
    if v[7] not in ('opportunity','booking') or related is not null or context_ref is not null
      or expected<>0 or not candidate or v[10]='' then
      raise exception 'IDENTITY_EVIDENCE_REQUIRED' using errcode='22023'; end if;
    insert into crm_private.identity_contexts(context_id,context_kind,admin_scope,source_ref,evidence_ref,verified)
      values(target,v[7],scope,v[9],v[10],true) returning version into new_version;
    history_context:=target;
    select to_jsonb(c) into new_state from crm_private.identity_contexts c where c.context_id=target;
  elsif v[2]='create_entity' then
    if v[7] not in ('contact','organization','group') or related is not null or expected<>0
      or (v[7]='group')<>(context_ref is not null) or (candidate and v[10]='') then
      raise exception 'IDENTITY_INPUT_INVALID' using errcode='22023'; end if;
    if context_ref is not null then
      select * into ctx from crm_private.identity_contexts where context_id=context_ref;
      if not found or ctx.admin_scope<>scope or not ctx.verified then
        raise exception 'IDENTITY_CONTEXT_UNVERIFIED' using errcode='22023'; end if;
    end if;
    insert into crm_private.identity_entities(identity_id,identity_kind,admin_scope,context_id,
      display_name,given_name,family_name,email,phone,group_type,estimated_size,
      confirmed_size,size_source,source_ref,evidence_ref,identity_verified)
      values(target,v[7],scope,context_ref,nullif(v[8],''),nullif(v[18],''),nullif(v[19],''),
        nullif(v[20],''),nullif(v[21],''),nullif(v[14],''),nullif(v[15],'')::integer,
        nullif(v[16],'')::integer,nullif(v[17],''),v[9],nullif(v[10],''),candidate)
      returning version into new_version;
    select to_jsonb(e) into new_state from crm_private.identity_entities e where e.identity_id=target;
  elsif v[2]='update_entity' then
    if related is not null or context_ref is not null then
      raise exception 'IDENTITY_INPUT_INVALID' using errcode='22023'; end if;
    select * into ent from crm_private.identity_entities where identity_id=target for update;
    if not found or ent.admin_scope<>scope or ent.identity_kind<>v[7] then
      raise exception 'IDENTITY_DENIED' using errcode='42501'; end if;
    if ent.version<>expected then raise exception 'IDENTITY_VERSION_CONFLICT' using errcode='40001'; end if;
    if candidate and (v[10]=chr(31) or (v[10]='' and ent.evidence_ref is null)) then
      raise exception 'IDENTITY_EVIDENCE_REQUIRED' using errcode='22023'; end if;
    if not candidate and exists(select 1 from crm_private.identity_designations d
      where d.party_id=target and d.role_kind='primary_contact' and d.ended_at is null) then
      raise exception 'IDENTITY_ACTIVE_DESIGNATION' using errcode='22023'; end if;
    old_state:=to_jsonb(ent);
    history_context:=ent.context_id;
    update crm_private.identity_entities set
      display_name=case when v[8]='' then ent.display_name when v[8]=chr(31) then null else v[8] end,
      given_name=case when v[18]='' then ent.given_name when v[18]=chr(31) then null else v[18] end,
      family_name=case when v[19]='' then ent.family_name when v[19]=chr(31) then null else v[19] end,
      email=case when v[20]='' then ent.email when v[20]=chr(31) then null else v[20] end,
      phone=case when v[21]='' then ent.phone when v[21]=chr(31) then null else v[21] end,
      group_type=case when v[14]='' then ent.group_type when v[14]=chr(31) then null else v[14] end,
      estimated_size=case when v[15]='' then ent.estimated_size when v[15]=chr(31) then null else v[15]::integer end,
      confirmed_size=case when v[16]='' then ent.confirmed_size when v[16]=chr(31) then null else v[16]::integer end,
      size_source=case when v[17]='' then ent.size_source when v[17]=chr(31) then null else v[17] end,
      source_ref=v[9],
      evidence_ref=case when v[10]='' then ent.evidence_ref when v[10]=chr(31) then null else v[10] end,
      identity_verified=candidate,version=version+1,
      updated_at=clock_timestamp() where identity_id=target returning version into new_version;
    select to_jsonb(e) into new_state from crm_private.identity_entities e where e.identity_id=target;
  elsif v[2]='link_organization_contact' then
    if related is null or context_ref is null or v[10]='' or not candidate or expected<>0 then
      raise exception 'IDENTITY_EVIDENCE_REQUIRED' using errcode='22023'; end if;
    if not exists(select 1 from crm_private.identity_entities e where e.identity_id=related
      and e.identity_kind='contact' and e.admin_scope=scope and e.identity_verified)
      or not exists(select 1 from crm_private.identity_entities e where e.identity_id=context_ref
      and e.identity_kind='organization' and e.admin_scope=scope and e.identity_verified)
    then raise exception 'IDENTITY_RELATION_UNVERIFIED' using errcode='22023'; end if;
    insert into crm_private.identity_organization_contacts
      (link_id,organization_id,contact_id,admin_scope,source_ref,evidence_ref)
      values(target,context_ref,related,scope,v[9],v[10]);
    new_version:=0;
    select to_jsonb(l) into new_state from crm_private.identity_organization_contacts l where l.link_id=target;
  else
    if related is null or context_ref is null or v[7] not in
      ('primary_contact','client','payer','participant') or (candidate and v[10]='') then
      raise exception 'IDENTITY_INPUT_INVALID' using errcode='22023'; end if;
    select * into ctx from crm_private.identity_contexts where context_id=context_ref for update;
    if not found or ctx.admin_scope<>scope or not ctx.verified then
      raise exception 'IDENTITY_CONTEXT_UNVERIFIED' using errcode='22023'; end if;
    if ctx.version<>expected then raise exception 'IDENTITY_VERSION_CONFLICT' using errcode='40001'; end if;
    select * into ent from crm_private.identity_entities where identity_id=related;
    if not found or ent.admin_scope<>scope or (candidate and not ent.identity_verified)
      or (ent.identity_kind='group' and ent.context_id<>context_ref)
      or (v[7]='primary_contact' and (not candidate or ent.identity_kind<>'contact')) then
      raise exception 'IDENTITY_RELATION_UNVERIFIED' using errcode='22023'; end if;
    party_kind:=ent.identity_kind;
    if v[7]='primary_contact' then
      select to_jsonb(d) into old_primary from crm_private.identity_designations d
        where d.context_id=context_ref and d.role_kind='primary_contact' and d.ended_at is null;
      update crm_private.identity_designations set ended_at=clock_timestamp()
        where context_id=context_ref and role_kind='primary_contact' and ended_at is null;
    end if;
    insert into crm_private.identity_designations
      (designation_id,context_id,party_id,party_kind,role_kind,admin_scope,source_ref,
       evidence_ref,verified,recorded_by,effective_at)
      values(target,context_ref,related,party_kind,v[7],scope,v[9],nullif(v[10],''),candidate,
        actor,nullif(v[22],'')::timestamptz);
    update crm_private.identity_contexts set version=version+1 where context_id=context_ref
      returning version into new_version;
    old_state:=old_primary;
    select to_jsonb(d) into new_state from crm_private.identity_designations d where d.designation_id=target;
    if old_primary is not null then
      new_state:=jsonb_build_object('current',new_state,'replaced',
        (select to_jsonb(d) from crm_private.identity_designations d
          where d.designation_id=(old_primary->>'designation_id')::uuid));
    end if;
  end if;
  insert into crm_private.identity_operations
    (operation_id,admin_scope,actor_id,material_fingerprint,action_kind,result_ref,resulting_version)
    values(v[3]::uuid,scope,actor,fingerprint,v[2],target,new_version);
  insert into crm_private.identity_history
    (history_id,operation_id,subject_id,context_id,related_id,subject_kind,before_state,after_state,
     source_ref,evidence_ref,reason,actor_id,happened_at)
    values(v[3]::uuid,v[3]::uuid,target,coalesce(history_context,context_ref),related,v[2],old_state,new_state,
      v[9],nullif(v[10],''),v[11],actor,nullif(v[22],'')::timestamptz);
  perform crm_f2.verify(f2p,f2s,q,'C03','human_identities','write_identity');
  perform crm_f1.verify_envelope(f1p,f1s,q,'C03','identities','write_identity');
  result_ref:=target; result_version:=new_version; replayed:=false;
  return next;
end $function$

CREATE OR REPLACE FUNCTION crm_api.identity_candidates(f2p bytea, f2s bytea, f1p bytea, f1s bytea, q bytea)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare hf text[]; tf text[]; v text[]; source_entity crm_private.identity_entities%rowtype;
  result jsonb;
begin
  hf:=crm_f2.admit(f2p,f2s,q,'C01','read_identity');
  tf:=crm_f1.verify_envelope(f1p,f1s,q,'C01','identities','read_identity');
  if hf[17] collate "C" <> tf[14] collate "C" then
    raise exception 'IDENTITY_DENIED' using errcode='42501'; end if;
  v:=crm_f1.fields(q);
  if cardinality(v)<>2 or v[1]<>'CRM-H1-CANDIDATES1' then
    raise exception 'IDENTITY_RESOLUTION_INPUT_INVALID' using errcode='22023'; end if;
  select * into source_entity from crm_private.identity_entities e
    where e.identity_id=v[2]::uuid and e.admin_scope=hf[17]
      and e.identity_kind in ('contact','organization') and e.archived_at is null;
  if not found then raise exception 'IDENTITY_RESOLUTION_TARGET_INVALID' using errcode='22023'; end if;
  select coalesce(jsonb_agg(jsonb_build_object('identity_id',e.identity_id,
      'identity_kind',e.identity_kind,'signals',jsonb_build_array(
        case when source_entity.email is not null and lower(trim(e.email))=lower(trim(source_entity.email))
          then 'email' end,
        case when source_entity.phone is not null and trim(e.phone)=trim(source_entity.phone)
          then 'phone' end,
        case when source_entity.display_name is not null and
          lower(trim(e.display_name))=lower(trim(source_entity.display_name))
          then 'name' end)) order by e.identity_id),'[]'::jsonb) into result
    from crm_private.identity_entities e
    where e.identity_id<>source_entity.identity_id and e.admin_scope=hf[17]
      and e.identity_kind=source_entity.identity_kind and e.archived_at is null
      and ((source_entity.email is not null and e.email is not null
            and lower(trim(e.email))=lower(trim(source_entity.email)))
        or (source_entity.phone is not null and e.phone is not null
            and trim(e.phone)=trim(source_entity.phone))
        or (source_entity.display_name is not null and e.display_name is not null
            and lower(trim(e.display_name))=lower(trim(source_entity.display_name))));
  perform crm_f2.verify(f2p,f2s,q,'C01','human_identities','read_identity');
  perform crm_f1.verify_envelope(f1p,f1s,q,'C01','identities','read_identity');
  return result;
end $function$

CREATE OR REPLACE FUNCTION crm_api.identity_code_lookup(f2p bytea, f2s bytea, f1p bytea, f1s bytea, q bytea)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare hf text[]; tf text[]; v text[]; result jsonb;
begin
  hf:=crm_f2.admit(f2p,f2s,q,'C01','read_identity');
  tf:=crm_f1.verify_envelope(f1p,f1s,q,'C01','identities','read_identity');
  if hf[17] collate "C" <> tf[14] collate "C" then
    raise exception 'IDENTITY_DENIED' using errcode='42501'; end if;
  v:=crm_f1.fields(q);
  if cardinality(v)<>4 or v[1]<>'CRM-H1-CODE-LOOKUP1'
    or v[2] not in ('code','target') or v[3] not in ('OP','PR','RES','INC')
    or (v[2]='code' and v[4] !~ '^(OP|PR|RES|INC)-[0-9]{4}-[0-9]{4,}$')
    or (v[2]='target' and v[4] !~
      '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$')
  then raise exception 'IDENTITY_RESOLUTION_INPUT_INVALID' using errcode='22023'; end if;
  if v[2]='code' then
    select jsonb_build_object('target_id',c.target_id,'code_kind',c.code_kind,
      'human_code',c.human_code,'assigned_at',c.assigned_at,'source_ref',c.source_ref)
      into result from crm_private.identity_codes c
      where c.human_code=v[4] and c.code_kind=v[3] and c.admin_scope=hf[17];
  else
    select jsonb_build_object('target_id',c.target_id,'code_kind',c.code_kind,
      'human_code',c.human_code,'assigned_at',c.assigned_at,'source_ref',c.source_ref)
      into result from crm_private.identity_codes c
      where c.target_id=v[4]::uuid and c.code_kind=v[3] and c.admin_scope=hf[17];
  end if;
  perform crm_f2.verify(f2p,f2s,q,'C01','human_identities','read_identity');
  perform crm_f1.verify_envelope(f1p,f1s,q,'C01','identities','read_identity');
  return result;
end $function$

CREATE OR REPLACE FUNCTION crm_api.identity_read(f2p bytea, f2s bytea, f1p bytea, f1s bytea, q bytea)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare hf text[]; tf text[]; v text[]; output jsonb; target uuid;
  page_limit integer; page_offset integer; total integer; next_page text;
begin
  hf:=crm_f2.admit(f2p,f2s,q,'C01','read_identity');
  tf:=crm_f1.verify_envelope(f1p,f1s,q,'C01','identities','read_identity');
  if hf[17] collate "C" <> tf[14] collate "C" then
    raise exception 'IDENTITY_DENIED' using errcode='42501'; end if;
  v:=crm_f1.fields(q);
  if cardinality(v)<>5 or v[1]<>'CRM-H1-ID-READ1'
    or v[2] not in ('entity','context','designations','history','organization_contacts')
    or v[4] !~ '^[1-9][0-9]{0,2}$' or v[5] !~ '^(0|[1-9][0-9]{0,8})$'
  then raise exception 'IDENTITY_INPUT_INVALID' using errcode='22023'; end if;
  target:=v[3]::uuid; page_limit:=v[4]::integer; page_offset:=v[5]::integer;
  if page_limit>100 then raise exception 'IDENTITY_INPUT_INVALID' using errcode='22023'; end if;
  if v[2]='entity' then
    select to_jsonb(e) into output from crm_private.identity_entities e
      where e.identity_id=target and e.admin_scope=hf[17];
  elsif v[2]='context' then
    select to_jsonb(c) into output from crm_private.identity_contexts c
      where c.context_id=target and c.admin_scope=hf[17];
  elsif v[2]='designations' then
    select coalesce(jsonb_agg(to_jsonb(d) order by d.recorded_at,d.designation_id),'[]'::jsonb)
      into output from crm_private.identity_designations d
      where d.context_id=target and d.admin_scope=hf[17];
  elsif v[2]='organization_contacts' then
    select coalesce(jsonb_agg(to_jsonb(l) order by l.recorded_at,l.link_id),'[]'::jsonb)
      into output from crm_private.identity_organization_contacts l
      where l.organization_id=target and l.admin_scope=hf[17];
  else
    select coalesce(jsonb_agg(to_jsonb(h) order by h.recorded_at,h.history_id),'[]'::jsonb)
      into output from crm_private.identity_history h
      join crm_private.identity_operations o on o.operation_id=h.operation_id
      where (h.subject_id=target or h.context_id=target or h.related_id=target)
        and o.admin_scope=hf[17];
  end if;
  if v[2] in ('designations','history','organization_contacts') then
    total:=jsonb_array_length(output);
    select coalesce(jsonb_agg(item.value order by item.ordinality),'[]'::jsonb) into output
      from jsonb_array_elements(output) with ordinality as item(value,ordinality)
      where item.ordinality>page_offset and item.ordinality<=page_offset+page_limit;
    next_page:=case when page_offset+page_limit<total then (page_offset+page_limit)::text else null end;
  else
    if page_offset<>0 then raise exception 'IDENTITY_INPUT_INVALID' using errcode='22023'; end if;
    next_page:=null;
  end if;
  perform crm_f2.verify(f2p,f2s,q,'C01','human_identities','read_identity');
  perform crm_f1.verify_envelope(f1p,f1s,q,'C01','identities','read_identity');
  return jsonb_build_object('data',output,'nextPage',next_page);
end $function$

CREATE OR REPLACE FUNCTION crm_api.identity_resolve(f2p bytea, f2s bytea, f1p bytea, f1s bytea, q bytea)
 RETURNS TABLE(result_ref uuid, result_version bigint, human_code text, replayed boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare hf text[]; tf text[]; v text[]; op crm_private.identity_operations%rowtype;
  source_entity crm_private.identity_entities%rowtype;
  destination crm_private.identity_entities%rowtype;
  before_state jsonb; after_state jsonb; fingerprint text;
  subject uuid; related uuid; actor uuid; scope text; expected bigint;
  next_version bigint; assigned timestamptz; annual_year integer; serial bigint;
  issued_code text;
begin
  hf:=crm_f2.admit(f2p,f2s,q,'C03','write_identity');
  tf:=crm_f1.verify_envelope(f1p,f1s,q,'C03','identities','write_identity');
  if hf[17] collate "C" <> tf[14] collate "C" then
    raise exception 'IDENTITY_DENIED' using errcode='42501'; end if;
  v:=crm_f1.fields(q);
  if cardinality(v)<>10 or v[1]<>'CRM-H1-RESOLVE1'
    or v[2] not in ('merge','archive','restore','assign_code')
    or v[3] is null or v[4] is null or v[7] is null or v[7]=''
    or v[8] is null or v[8]='' or v[9] is null or v[9]=''
    or v[10] !~ '^(0|[1-9][0-9]{0,18})$'
  then raise exception 'IDENTITY_RESOLUTION_INPUT_INVALID' using errcode='22023'; end if;
  subject:=v[4]::uuid; related:=nullif(v[5],'')::uuid;
  expected:=v[10]::bigint; actor:=hf[12]::uuid; scope:=hf[17];
  fingerprint:=encode(crm_crypto.digest(q,'sha256'),'hex');
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(v[3],0));
  select * into op from crm_private.identity_operations where operation_id=v[3]::uuid;
  if found then
    if op.actor_id<>actor or op.admin_scope<>scope or op.material_fingerprint<>fingerprint then
      raise exception 'IDENTITY_REPLAY_CONFLICT' using errcode='23505'; end if;
    select c.human_code into issued_code from crm_private.identity_codes c
      where c.operation_id=op.operation_id and c.admin_scope=scope;
    perform crm_f2.verify(f2p,f2s,q,'C03','human_identities','write_identity');
    result_ref:=op.result_ref; result_version:=op.resulting_version;
    human_code:=issued_code; replayed:=true; return next; return;
  end if;
  if v[2]='assign_code' then
    if related is not null or expected<>0 or v[6] not in ('OP','PR','RES','INC') then
      raise exception 'IDENTITY_RESOLUTION_INPUT_INVALID' using errcode='22023'; end if;
    if v[6] in ('OP','RES') and not exists(select 1 from crm_private.identity_contexts c
      where c.context_id=subject and c.context_kind=
        case v[6] when 'OP' then 'opportunity' else 'booking' end
        and c.admin_scope=scope and c.verified) then
      raise exception 'IDENTITY_RESOLUTION_TARGET_INVALID' using errcode='22023'; end if;
    -- PR/INC targets are stable IDs supplied by their later lifecycle.
    -- The H1 context is only a local reference, not a Booking or Opportunity.
    if exists(select 1 from crm_private.identity_codes c
      where c.code_kind=v[6] and c.target_id=subject) then
      raise exception 'IDENTITY_CODE_ALREADY_ASSIGNED' using errcode='23505'; end if;
    -- The assignment instant follows serialization, including a wait across midnight.
    perform pg_catalog.pg_advisory_xact_lock(
      pg_catalog.hashtextextended('H1-CODE-' || v[6],0));
    assigned:=clock_timestamp();
    annual_year:=crm_private.code_year_at(assigned);
    insert into crm_private.identity_code_counters(code_kind,code_year,last_serial)
      values(v[6],annual_year,1)
      on conflict(code_kind,code_year)
      do update set last_serial=crm_private.identity_code_counters.last_serial+1
      returning last_serial into serial;
    issued_code:=v[6] || '-' || annual_year::text || '-' ||
      lpad(serial::text,greatest(4,length(serial::text)),'0');
    next_version:=0;
    after_state:=jsonb_build_object('code_kind',v[6],'target_id',subject,
      'human_code',issued_code,'assigned_at',assigned,'code_year',annual_year);
  else
    if v[6] not in ('contact','organization') or
      (v[2]='merge' and (related is null or related=subject)) or
      (v[2]<>'merge' and related is not null) then
      raise exception 'IDENTITY_RESOLUTION_INPUT_INVALID' using errcode='22023'; end if;
    -- Lock both identities in stable UUID order, including the target of merge.
    perform 1 from crm_private.identity_entities e
      where e.identity_id in (subject,related) order by e.identity_id for update;
    select * into source_entity from crm_private.identity_entities e where e.identity_id=subject;
    if not found or source_entity.admin_scope<>scope or source_entity.identity_kind<>v[6] then
      raise exception 'IDENTITY_RESOLUTION_TARGET_INVALID' using errcode='22023'; end if;
    if source_entity.version<>expected then
      raise exception 'IDENTITY_VERSION_CONFLICT' using errcode='40001'; end if;
    before_state:=to_jsonb(source_entity);
    if v[2]='merge' then
      select * into destination from crm_private.identity_entities e where e.identity_id=related;
      if not found or destination.admin_scope<>scope
        or destination.identity_kind<>source_entity.identity_kind
        or not source_entity.identity_verified or not destination.identity_verified
        or source_entity.archived_at is not null or destination.archived_at is not null
        or source_entity.merged_into_id is not null or destination.merged_into_id is not null
      then raise exception 'IDENTITY_RESOLUTION_TARGET_INVALID' using errcode='22023'; end if;
      update crm_private.identity_entities set merged_into_id=related,
        archived_at=clock_timestamp(),version=version+1,updated_at=clock_timestamp()
        where identity_id=subject returning version into next_version;
      select jsonb_build_object('source',to_jsonb(e),'destination',to_jsonb(destination))
        into after_state from crm_private.identity_entities e where e.identity_id=subject;
    elsif v[2]='archive' then
      if source_entity.archived_at is not null then
        raise exception 'IDENTITY_RESOLUTION_TARGET_INVALID' using errcode='22023'; end if;
      update crm_private.identity_entities set archived_at=clock_timestamp(),
        version=version+1,updated_at=clock_timestamp()
        where identity_id=subject returning version into next_version;
      select to_jsonb(e) into after_state from crm_private.identity_entities e
        where e.identity_id=subject;
    else
      if source_entity.archived_at is null or source_entity.merged_into_id is not null then
        raise exception 'IDENTITY_RESOLUTION_TARGET_INVALID' using errcode='22023'; end if;
      update crm_private.identity_entities set archived_at=null,
        version=version+1,updated_at=clock_timestamp()
        where identity_id=subject returning version into next_version;
      select to_jsonb(e) into after_state from crm_private.identity_entities e
        where e.identity_id=subject;
    end if;
  end if;
  insert into crm_private.identity_operations
    (operation_id,admin_scope,actor_id,material_fingerprint,action_kind,result_ref,resulting_version)
    values(v[3]::uuid,scope,actor,fingerprint,v[2],subject,next_version);
  if v[2]='assign_code' then
    insert into crm_private.identity_codes
      (code_id,operation_id,code_kind,target_id,admin_scope,code_year,serial_number,
       human_code,assigned_at,source_ref,evidence_ref,actor_id)
      values(v[3]::uuid,v[3]::uuid,v[6],subject,scope,annual_year,serial,
        issued_code,assigned,v[7],v[8],actor);
  end if;
  insert into crm_private.identity_history
    (history_id,operation_id,subject_id,related_id,subject_kind,before_state,after_state,
     source_ref,evidence_ref,reason,actor_id)
    values(v[3]::uuid,v[3]::uuid,subject,related,v[2],before_state,after_state,
      v[7],v[8],v[9],actor);
  perform crm_f2.verify(f2p,f2s,q,'C03','human_identities','write_identity');
  perform crm_f1.verify_envelope(f1p,f1s,q,'C03','identities','write_identity');
  result_ref:=subject; result_version:=next_version;
  human_code:=issued_code; replayed:=false; return next;
end $function$

CREATE OR REPLACE FUNCTION crm_api.incident_apply(f2p bytea, f2s bytea, f1p bytea, f1s bytea, q bytea, cf2p bytea, cf2s bytea, cf1p bytea, cf1s bytea, cq bytea)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare hf text[];tf text[];fs text[];cs text[];a jsonb;op uuid;iid uuid;bid uuid;actor uuid;s text;action text;fp text;proofhash text;rev bigint;at_time timestamptz;
 prev crm_private.b07_incident_operations;root crm_private.b07_incidents;old jsonb;state jsonb;r jsonb;data jsonb;st text;code text;assigned timestamptz;
begin
 hf:=crm_f2.admit(f2p,f2s,q,'C03','write_evidence');tf:=crm_f1.verify_envelope(f1p,f1s,q,'C03','evidence','write_evidence');
 if hf[17] collate "C" is distinct from tf[14] collate "C" then raise exception 'INCIDENT_DENIED';end if;
