   if a ?| array['definition','computed','scheduleId','slot','amount','due','scope','scopeId','policy'] then raise exception 'OBLIGATION_INPUT_INVALID';end if;
   perform pg_advisory_xact_lock(hashtextextended(pid::text,51));
   select coalesce(max(version),0) into rev from crm_private.b05_payment_policies where policy_id=pid;
   if rev<>(a->>'expectedRevision')::bigint or exists(select 1 from crm_private.b05_payment_policies where policy_id=pid and admin_scope<>s)
   then raise exception 'OBLIGATION_REVISION_CONFLICT';end if;
   if jsonb_typeof(a->'policyVersion') is distinct from 'number' or (a->>'policyVersion')::bigint<>rev+1
    or jsonb_typeof(a->'selectors') is distinct from 'object' or (a->'selectors')-array['service','provider','type','case']<>'{}'::jsonb
    or exists(select 1 from jsonb_each(a->'selectors') x where jsonb_typeof(x.value) not in ('string','null')) then raise exception 'OBLIGATION_POLICY_REQUIRED';end if;
   insert into crm_private.b05_payment_policies values(pid,rev+1,s,'ordinary_50_50',a->'selectors',actor,a->>'sourceRef',a->>'reason',(a->>'evidenceId')::uuid,clock_timestamp());
   r:=jsonb_build_object('id',pid,'revision',rev+1,'rule','ordinary_50_50');
  else
   if not(a ?& array['scheduleId','scope','scopeId']) or a->>'scope' not in ('global','modality','service','night') then raise exception 'OBLIGATION_SCOPE_REQUIRED';end if;
   sid:=(a->>'scheduleId')::uuid;
   -- Root lock protects absent children and functional identity, including different keys.
   perform pg_advisory_xact_lock(hashtextextended(bid::text,52));
   if a->>'scope'='global' and a->>'scopeId'<>bid::text
    or a->>'scope'='modality' and not exists(select 1 from crm_private.b04_modalities where booking_id=bid and modality_id=(a->>'scopeId')::uuid)
    or a->>'scope'='service' and not exists(select 1 from crm_private.b04_services where booking_id=bid and service_id=(a->>'scopeId')::uuid)
    or a->>'scope'='night' and not exists(select 1 from crm_private.b04_nights n join crm_private.b04_services bs using(service_id) where bs.booking_id=bid and n.night_id=(a->>'scopeId')::uuid)
   then raise exception 'OBLIGATION_SCOPE_REQUIRED';end if;
   select * into ps from crm_private.b05_payment_schedules where booking_id=bid and scope_kind=a->>'scope' and scope_id=(a->>'scopeId')::uuid;
   if action='determine' then
    if a ?| array['slot','amount','due','policyVersion','selectors'] then raise exception 'OBLIGATION_INPUT_INVALID';end if;
    d:=a->'definition';c:=a->'computed';policy:=a->'policy';
    if jsonb_typeof(d) is distinct from 'object' or not(d ?& array['base','reference','at']) or d-array['base','reference','at','exception']<>'{}'::jsonb
     or jsonb_typeof(d->'base') is distinct from 'object' or (d->'base')-array['amount','sourceRef','version']<>'{}'::jsonb
     or not(d->'base' ?& array['amount','sourceRef','version']) or jsonb_typeof((d->'base')->'amount') is distinct from 'string' or (d->'base')->>'amount' !~ '^(0|[1-9][0-9]*)\.[0-9]{2}$'
     or coalesce((d->'base')->>'sourceRef','')='' or coalesce((d->'base')->>'version','')='' or d->>'at' is distinct from a->>'at'
     or policy-array['id','version','rule']<>'{}'::jsonb or policy->>'id' is distinct from pid::text or policy->>'rule' is distinct from 'ordinary_50_50'
    then raise exception 'OBLIGATION_MATERIAL_REQUIRED';end if;
    pv:=(policy->>'version')::bigint;
    select * into pol from crm_private.b05_payment_policies where policy_id=pid and version=pv and admin_scope=s;
    if not found then raise exception 'OBLIGATION_POLICY_REQUIRED';end if;
    -- Selectors are retained explicit application criteria, never an implicit new commercial rule.
    if pol.selectors->>'case' is not null and pol.selectors->>'case'<>bid::text
     or pol.selectors->>'service' is not null and (a->>'scope'<>'service' or pol.selectors->>'service'<>a->>'scopeId')
     or pol.selectors->>'provider' is not null and not exists(select 1 from crm_private.b04_services bs where bs.booking_id=bid and bs.service_id=(a->>'scopeId')::uuid and bs.applied->>'provider'=pol.selectors->>'provider')
     or pol.selectors->>'type' is not null and not exists(select 1 from crm_private.b04_services bs where bs.booking_id=bid and bs.service_id=(a->>'scopeId')::uuid and bs.nature=pol.selectors->>'type') then raise exception 'OBLIGATION_POLICY_SCOPE_REQUIRED';end if;
    if (d->'reference')->>'scope' is distinct from a->>'scope' or (d->'reference')->>'scopeId' is distinct from a->>'scopeId'
     or (d->'reference')->>'basis' not in ('default','express_contract') or coalesce((d->'reference')->>'sourceRef','')='' or coalesce((d->'reference')->>'version','')=''
     or coalesce((d->'reference'->'zone')->>'sourceRef','')='' or coalesce((d->'reference'->'zone')->>'version','')=''
     or not exists(select 1 from pg_timezone_names where name=(d->'reference'->'zone')->>'zone') or (d->'reference')->>'date' !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$'
    then raise exception 'OBLIGATION_REFERENCE_REQUIRED';end if;
    -- No default can be guessed if any date in its scope remains pending.
    select case when bool_or(l.service_date is null) then null else min(l.service_date) end into firstdate
    from crm_private.b04_contributions bc join crm_private.b03_proposal_lines l using(version_id,line_id)
    where bc.booking_id=bid and (a->>'scope'='global' or a->>'scope'='modality' and bc.modality_id=(a->>'scopeId')::uuid or a->>'scope'='service' and bc.service_id=(a->>'scopeId')::uuid
     or a->>'scope'='night' and exists(select 1 from crm_private.b04_night_occupancies n where n.night_id=(a->>'scopeId')::uuid and n.contribution_id=bc.contribution_id));
    if (d->'reference')->>'basis'='default' and (firstdate is null or firstdate is distinct from ((d->'reference')->>'date')::date) then raise exception 'OBLIGATION_REFERENCE_REQUIRED';end if;
    amt:=((d->'base')->>'amount')::numeric;
    -- Reproducible whole selected modalities use accepted H2 prices. Other scopes require
    -- explicit evidence-bound determination, never proration or silent alteration of H2.
    if a->>'scope' in ('global','modality') and not exists(select 1 from crm_private.b04_modalities bm join crm_private.b03_proposal_lines l on l.version_id=b.version_id and l.modality_id=bm.modality_id and l.included
     where bm.booking_id=bid and (a->>'scope'='global' or bm.modality_id=(a->>'scopeId')::uuid)
     and not exists(select 1 from crm_private.b04_contributions bc where bc.booking_id=bid and bc.line_id=l.line_id)) then
     select sum(m.final_person_price*m.participants) into accepted from crm_private.b04_modalities bm join crm_private.b03_proposal_modalities m on m.version_id=b.version_id and m.modality_id=bm.modality_id
     where bm.booking_id=bid and (a->>'scope'='global' or bm.modality_id=(a->>'scopeId')::uuid);
     if accepted is not null and accepted<>amt then raise exception 'OBLIGATION_BASE_CONFLICT';end if;
    end if;
    actdate:=((a->>'at')::timestamptz at time zone ((d->'reference'->'zone')->>'zone'))::date;days:=((d->'reference')->>'date')::date-actdate;due:=((d->'reference')->>'date')::date-7;
    -- Exact numeric invariant checks on H1 output; not a second money/calc engine.
    initial:=case when days<7 then amt else round(amt/2,2) end;balance:=amt-initial;
    parts:=c->'parts';
    if jsonb_typeof(c) is distinct from 'object' or c->'policy' is distinct from policy or c->'base' is distinct from d->'base' or c->'reference' is distinct from d->'reference' or c->>'at' is distinct from a->>'at'
     or c->>'moneyVersion' is distinct from 'h1-money-d023-d028-d029-v1' or c->>'civilVersion' is distinct from 'h1-civil-d020-v1'
     or (c->'calculation')->>'algorithmVersion' is distinct from 'h1-money-d023-d028-d029-v1'
     or (c->'calculation')->'input' is distinct from jsonb_build_object('kind','percentage','base',(d->'base')->>'amount','percent',case when days<7 then '100' else '50' end)
     or (c->'calculation'->'output'->'applied')->>'amount' is distinct from to_char(initial,'FM999999999999999999999999999999990.00')
     or (c->'calculation'->'output')->>'remainder' is distinct from to_char(balance,'FM999999999999999999999999999999990.00')
     or (c->'evaluation')->>'actDate' is distinct from actdate::text or ((c->'evaluation')->>'daysBefore')::integer is distinct from days
     or c->'ordinary' is distinct from (case when days<7 then jsonb_build_array(jsonb_build_object('slot','initial','amount',(d->'base')->>'amount','due',jsonb_build_object('kind','before_confirmation')))
      else jsonb_build_array(jsonb_build_object('slot','initial','amount',to_char(initial,'FM999999999999999999999999999999990.00'),'due',jsonb_build_object('kind','at_confirmation')),jsonb_build_object('slot','balance','amount',to_char(balance,'FM999999999999999999999999999999990.00'),'due',jsonb_build_object('kind','civil','date',due::text))) end)
    then raise exception 'OBLIGATION_CALCULATION_INVALID';end if;
    if jsonb_typeof(parts) is distinct from 'array' or jsonb_array_length(parts) not between 1 and 2
     or exists(select 1 from jsonb_array_elements(parts) x where not crm_private.obligation_part_valid(x))
     or (select count(distinct x->>'slot') from jsonb_array_elements(parts) x)<>jsonb_array_length(parts)
     or (select sum((x->>'amount')::numeric) from jsonb_array_elements(parts) x)<>amt then raise exception 'OBLIGATION_PART_INVALID';end if;
    if d ? 'exception' then
     if (d->'exception')-array['reason','parts']<>'{}'::jsonb or coalesce(btrim((d->'exception')->>'reason'),'')='' or c->'exception' is distinct from d->'exception' or parts is distinct from (d->'exception')->'parts'
     then raise exception 'OBLIGATION_EXCEPTION_REQUIRED';end if;
    elsif parts is distinct from c->'ordinary' or c ? 'exception' then raise exception 'OBLIGATION_EXCEPTION_REQUIRED';end if;
    efp:=encode(crm_crypto.digest(convert_to((a-array['operationId','scheduleId','expectedRevision','evidenceId','computed'])::text,'UTF8'),'sha256'),'hex');
    if ps.schedule_id is not null then
     if ps.effect_fingerprint<>efp then raise exception 'OBLIGATION_EXISTS_CONFLICT';end if;
     sid:=ps.schedule_id;r:=jsonb_build_object('id',sid,'revision',1,'existing',true);
    else
     if (a->>'expectedRevision')::bigint<>0 then raise exception 'OBLIGATION_REVISION_CONFLICT';end if;
     insert into crm_private.b05_payment_schedules values(sid,bid,s,a->>'scope',(a->>'scopeId')::uuid,pid,pv,actor,efp,clock_timestamp());
     c:=c||jsonb_build_object('policyApplied',to_jsonb(pol),'bookingChain',b.chain_snapshot,'bookingVersion',b.version_id,'evidenceId',a->>'evidenceId','actorId',actor,'reason',a->>'reason');
     insert into crm_private.b05_schedule_revisions values(sid,1,s,c,actor,clock_timestamp());
     for part in select value from jsonb_array_elements(parts) loop insert into crm_private.b05_expected_payments values(sid,part->>'slot',s,(part->>'amount')::numeric,part->'due');end loop;
     r:=jsonb_build_object('id',sid,'revision',1,'existing',false);
    end if;
   else
    if a ?| array['definition','computed','policy','policyVersion','selectors'] or ps.schedule_id is null or ps.schedule_id<>sid or ps.policy_id<>pid then raise exception 'OBLIGATION_ADJUSTMENT_REQUIRED';end if;
    select revision,snapshot into rev,before_state from crm_private.b05_schedule_revisions where schedule_id=sid order by revision desc limit 1;
    if rev<>(a->>'expectedRevision')::bigint then raise exception 'OBLIGATION_REVISION_CONFLICT';end if;
    part:=jsonb_build_object('slot',a->>'slot','amount',a->>'amount','due',a->'due');
    if not crm_private.obligation_part_valid(part) or not exists(select 1 from crm_private.b05_expected_payments where schedule_id=sid and slot=a->>'slot') then raise exception 'OBLIGATION_ADJUSTMENT_REQUIRED';end if;
    select value into d from jsonb_array_elements(before_state->'parts') where value->>'slot'=a->>'slot';
    select jsonb_agg(case when x->>'slot'=a->>'slot' then part else x end order by ord) into parts from jsonb_array_elements(before_state->'parts') with ordinality z(x,ord);
    c:=jsonb_set(before_state,'{parts}',parts);
    insert into crm_private.b05_schedule_revisions values(sid,rev+1,s,c,actor,clock_timestamp());
    insert into crm_private.b05_obligation_adjustments values(op,sid,a->>'slot',rev+1,s,d,part,(a->>'amount')::numeric-(d->>'amount')::numeric,actor,a->>'reason',a->>'sourceRef',(a->>'evidenceId')::uuid,clock_timestamp());
    r:=jsonb_build_object('id',sid,'revision',rev+1,'originalRetained',true);
   end if;
  end if;
  insert into crm_private.b05_obligation_operations values(op,bid,s,actor,fp,a,r,clock_timestamp());
  insert into crm_private.b05_obligation_history values(op,bid,s,actor,before_state,r,a->>'sourceRef',a->>'reason',(a->>'evidenceId')::uuid,(a->>'at')::timestamptz,clock_timestamp());
  r:=jsonb_build_object('id',r->>'id','replayed',false,'result',r);
 end if;
 perform crm_f2.verify(f2p,f2s,q,'C03','human_evidence','write_evidence');perform crm_f1.verify_envelope(f1p,f1s,q,'C03','evidence','write_evidence');return r;
end $function$

CREATE OR REPLACE FUNCTION crm_api.obligation_read(f2p bytea, f2s bytea, f1p bytea, f1s bytea, q bytea)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare hf text[];tf text[];fs text[];a jsonb;r jsonb;begin
 hf:=crm_f2.admit(f2p,f2s,q,'C01','read_evidence');tf:=crm_f1.verify_envelope(f1p,f1s,q,'C01','evidence','read_evidence');
 if hf[17] collate "C"<>tf[14] collate "C" then raise exception 'OBLIGATION_DENIED';end if;
 fs:=crm_f1.fields(q);if cardinality(fs)<>2 or fs[1]<>'CRM-H3-OBLIGATION-READ1' then raise exception 'OBLIGATION_INPUT_INVALID';end if;a:=fs[2]::jsonb;
 if jsonb_typeof(a) is distinct from 'object' or a-array['bookingId','scheduleId']<>'{}'::jsonb or not(a ?& array['bookingId','scheduleId']) then raise exception 'OBLIGATION_INPUT_INVALID';end if;
 select jsonb_build_object('coverage',crm_private.fund_coverage(ps.schedule_id,hf[17]),'current',(select to_jsonb(x) from crm_private.b05_schedule_revisions x where x.schedule_id=ps.schedule_id order by revision desc limit 1),
 'original',(select jsonb_agg(jsonb_build_object('slot',x.slot,'amount',to_char(x.amount,'FM999999999999999999999999999999990.00'),'due',x.due) order by x.slot) from crm_private.b05_expected_payments x where x.schedule_id=ps.schedule_id),
 'history',coalesce((select jsonb_agg(to_jsonb(x)||jsonb_build_object('difference',x.difference::text) order by x.revision) from crm_private.b05_obligation_adjustments x where x.schedule_id=ps.schedule_id),'[]')) into r
 from crm_private.b05_payment_schedules ps where ps.schedule_id=(a->>'scheduleId')::uuid and ps.booking_id=(a->>'bookingId')::uuid and ps.admin_scope=hf[17];
 perform crm_f2.verify(f2p,f2s,q,'C01','human_evidence','read_evidence');perform crm_f1.verify_envelope(f1p,f1s,q,'C01','evidence','read_evidence');return r;
end $function$

CREATE OR REPLACE FUNCTION crm_api.offer_apply(f2p bytea, f2s bytea, f1p bytea, f1s bytea, q bytea)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare hf text[];tf text[];fields text[];a jsonb;p crm_private.b03_proposals;o crm_private.b03_opportunities;
 v crm_private.b03_proposal_versions;i crm_private.b03_offer_issuances;prior crm_private.b03_offer_operations;
 com crm_private.b07_records;fact crm_private.b07_records;proof crm_private.b07_records;
 op uuid;root uuid;vid uuid;opp uuid;actor uuid;s text;action text;cov text;at_time timestamptz;
 fp text;res jsonb;norm jsonb;original jsonb;d integer;issued timestamptz;until_time timestamptz;l jsonb;
 reviewed boolean:=false;stale boolean:=false;pending boolean:=false;aspect text;part uuid;kind text;lo timestamptz;
begin
 hf:=crm_f2.admit(f2p,f2s,q,'C03','write_evidence');tf:=crm_f1.verify_envelope(f1p,f1s,q,'C03','evidence','write_evidence');
 if hf[17] collate "C"<>tf[14] collate "C" then raise exception 'OFFER_DENIED';end if;
 fields:=crm_f1.fields(q);if cardinality(fields)<>2 or fields[1]<>'CRM-H2-OFFER1' then raise exception 'OFFER_INPUT_INVALID';end if;a:=fields[2]::jsonb;
 if jsonb_typeof(a) is distinct from 'object' or a-array['action','operationId','proposalId','opportunityId','versionId','expectedRevision','expectedOpportunityRevision','sourceRef','reason','coverage','at','actId','actKind','issuance','evidenceId','reviewEvidence','communicationId','factId','recipientId','channel','partId','partKind','lossReason','origin']<>'{}'::jsonb
 or not(a ?& array['action','operationId','proposalId','opportunityId','versionId','expectedRevision','expectedOpportunityRevision','sourceRef','reason','coverage','at'])
 or a->>'action' not in ('issue','intent','evaluate','revalidate','send','reject')
 or jsonb_typeof(a->'expectedRevision') is distinct from 'number' or jsonb_typeof(a->'expectedOpportunityRevision') is distinct from 'number'
 or a->>'expectedRevision' !~ '^[0-9]+$' or a->>'expectedOpportunityRevision' !~ '^[0-9]+$'
 or exists(select 1 from jsonb_each(a) x where x.key in ('sourceRef','reason','coverage','at') and (jsonb_typeof(x.value)<>'string' or btrim(x.value#>>'{}')=''))
 or a->>'at' !~ '^\d{4}-\d\d-\d\dT\d\d:\d\d:\d\d(\.\d+)?(Z|[+-]\d\d:\d\d)$' then raise exception 'OFFER_INPUT_INVALID';end if;
 op:=(a->>'operationId')::uuid;root:=(a->>'proposalId')::uuid;vid:=(a->>'versionId')::uuid;opp:=(a->>'opportunityId')::uuid;
 actor:=hf[12]::uuid;s:=hf[17];action:=a->>'action';cov:=a->>'coverage';at_time:=(a->>'at')::timestamptz;
 if at_time>clock_timestamp() then raise exception 'OFFER_FUTURE_FACT';end if;
 fp:=encode(crm_crypto.digest(convert_to(a::text,'UTF8'),'sha256'),'hex');
 perform pg_advisory_xact_lock(hashtextextended(op::text,0));
 select * into prior from crm_private.b03_offer_operations where operation_id=op;
 if found then
  if prior.admin_scope<>s or prior.actor_id<>actor or prior.fingerprint<>fp then raise exception 'OFFER_REPLAY_CONFLICT';end if;
  res:=jsonb_build_object('id',op,'replayed',true,'result',prior.result);
 else
  perform pg_advisory_xact_lock(hashtextextended(opp::text,31));
  select * into o from crm_private.b03_opportunities where opportunity_id=opp and admin_scope=s for update;
  if not found then raise exception 'OFFER_RELATION_INVALID';end if;
  perform pg_advisory_xact_lock(hashtextextended(root::text,33));
  select * into p from crm_private.b03_proposals where proposal_id=root and opportunity_id=opp and admin_scope=s for update;
  if not found then raise exception 'OFFER_RELATION_INVALID';end if;
  select * into v from crm_private.b03_proposal_versions where version_id=vid and proposal_id=root and admin_scope=s;
  if not found or cov not in (v.scope) and not exists(select 1 from crm_private.b03_proposal_modalities where version_id=vid and modality_id::text=cov) and not exists(select 1 from crm_private.b03_proposal_lines where version_id=vid and line_id::text=cov) then raise exception 'OFFER_COVERAGE_INVALID';end if;
  if p.revision<>(a->>'expectedRevision')::bigint or o.revision<>(a->>'expectedOpportunityRevision')::bigint then raise exception 'OFFER_REVISION_CONFLICT';end if;
  original:=jsonb_build_object('proposalRevision',p.revision,'opportunity',to_jsonb(o));
  select * into i from crm_private.b03_offer_issuances where version_id=vid;
  select coalesce(max(z.occurred_at),'-infinity'::timestamptz) into lo from crm_private.b03_offer_operations z where z.version_id=vid and z.action in ('evaluate','reject') and crm_private.offer_overlap(vid,z.coverage,cov);
  lo:=greatest(lo,coalesce((select max(recorded_at) from crm_private.b03_proposal_versions where replaces_version_id=vid),'-infinity'::timestamptz));
  stale:=exists(select 1 from crm_private.b03_proposal_versions where replaces_version_id=vid)
   or exists(select 1 from crm_private.b03_offer_operations e where e.version_id=vid and e.action='reject' and crm_private.offer_overlap(vid,e.coverage,cov))
   or exists(select 1 from crm_private.b03_offer_operations e where e.version_id=vid and e.action='evaluate' and e.result->'pending'='true' and crm_private.offer_overlap(vid,e.coverage,cov));
  reviewed:=exists(select 1 from crm_private.b03_offer_operations e where e.version_id=vid and e.action='revalidate' and e.coverage=cov and e.event->>'actId'=a->>'actId' and e.event->>'actKind'=coalesce(a->>'actKind','send') and e.occurred_at=at_time and e.recorded_at>coalesce((select max(recorded_at) from crm_private.b03_offer_operations z where z.version_id=vid and z.action in ('reject','evaluate') and crm_private.offer_overlap(vid,z.coverage,cov)),'-infinity'::timestamptz));
  if action='issue' then
   if i.version_id is not null or cov<>v.scope or jsonb_typeof(a->'issuance') is distinct from 'object' or (a->'issuance')-array['issuedAt','days','limits']<>'{}'::jsonb then raise exception 'OFFER_NEW_VERSION_REQUIRED:SM-FORB-01';end if;
   if not((a->'issuance') ?& array['issuedAt','limits']) or jsonb_typeof(a->'issuance'->'limits') is distinct from 'array' then raise exception 'OFFER_INPUT_INVALID';end if;
   d:=coalesce((a->'issuance'->>'days')::integer,7);issued:=(a->'issuance'->>'issuedAt')::timestamptz;
   if d<=0 or issued<>at_time then raise exception 'OFFER_INPUT_INVALID';end if;
   until_time:=issued+make_interval(secs=>d::double precision*86400);
   if not crm_private.offer_evidence((a->>'evidenceId')::uuid,opp,s,'offer:issue:'||vid||':'||(a->'issuance'->>'issuedAt')||':'||d,cov,issued,issued) then raise exception 'OFFER_ISSUANCE_EVIDENCE_REQUIRED';end if;
   for l in select jsonb_array_elements(a->'issuance'->'limits') loop
    if l-array['aspect','until','evidenceId']<>'{}'::jsonb or l->>'aspect' not in ('prices','availability','conditions','capacity') or not crm_private.offer_evidence((l->>'evidenceId')::uuid,opp,s,'offer:limit:'||vid||':'||(l->>'aspect')||':'||(l->>'until'),cov,'-infinity',issued) then raise exception 'OFFER_LIMIT_EVIDENCE_REQUIRED';end if;
    until_time:=least(until_time,(l->>'until')::timestamptz);
   end loop;
   insert into crm_private.b03_offer_issuances(version_id,admin_scope,issued_at,effective_until,issuance,evidence_id,actor_id,source_ref) values(vid,s,issued,until_time,a->'issuance',(a->>'evidenceId')::uuid,actor,a->>'sourceRef');
   res:=jsonb_build_object('issuedAt',issued,'effectiveUntil',until_time,'days',d);norm:=jsonb_build_array('BR-PROP-004','DM-INV-011');
  elsif action='intent' then
   if nullif(a->>'recipientId','') is null or nullif(a->>'channel','') is null then raise exception 'OFFER_RECIPIENT_REQUIRED';end if;
   res:=jsonb_build_object('pendingExternal',true,'sent',false,'versionId',vid,'recipientId',a->>'recipientId','channel',a->>'channel');norm:=jsonb_build_array('PLAN-C05','BR-COMM-002');
  elsif action='evaluate' then
   if i.version_id is null or at_time<i.issued_at then raise exception 'OFFER_ISSUANCE_REQUIRED:SM-PV-04';end if;
   pending:=at_time>i.effective_until;
   if a ? 'evidenceId' then
    if not crm_private.offer_evidence((a->>'evidenceId')::uuid,opp,s,'offer:uncertain:'||vid,cov,'-infinity',at_time) then raise exception 'OFFER_UNCERTAINTY_EVIDENCE_REQUIRED';end if;pending:=true;
   end if;
   res:=jsonb_build_object('pending',pending,'expired',at_time>i.effective_until,'rejected',false,'effectiveUntil',i.effective_until);norm:=jsonb_build_array('SM-PV-04','SM-FORB-01');
  elsif action='revalidate' then
   if i.version_id is null or at_time<i.issued_at or nullif(a->>'actId','') is null or a->>'actKind' not in ('send','accept') or jsonb_typeof(a->'reviewEvidence') is distinct from 'object' or (a->'reviewEvidence')-array['prices','availability','conditions','capacity']<>'{}'::jsonb then raise exception 'OFFER_ACT_REVIEW_REQUIRED';end if;
   foreach aspect in array array['prices','availability','conditions','capacity'] loop
    if not crm_private.offer_evidence((a->'reviewEvidence'->>aspect)::uuid,opp,s,'offer:review:'||vid||':'||(a->>'actId')||':'||(a->>'actKind')||':'||aspect,cov,greatest(i.issued_at,lo),at_time) then raise exception 'OFFER_MATERIAL_REVIEW_REQUIRED:SM-PV-05';end if;
   end loop;
   res:=jsonb_build_object('reviewedForAct',a->>'actId','actKind',a->>'actKind','at',at_time,'coverage',cov,'originalEffectiveUntil',i.effective_until,'acceptanceCreated',false);norm:=jsonb_build_array('SM-PV-05','AC-008','AC-086');
  elsif action='send' then
   if coalesce(a->>'origin','manual')<>'manual' then raise exception 'OFFER_HA_TTE_REQUIRED:G3';end if;
   if i.version_id is null or at_time<i.issued_at or (at_time>i.effective_until or stale) and not reviewed then raise exception 'OFFER_ACT_REVIEW_REQUIRED:SM-PV-03';end if;
   if nullif(a->>'actId','') is null or coalesce(a->>'actKind','send')<>'send' then raise exception 'OFFER_ACT_REVIEW_REQUIRED';end if;
   if o.state not in ('Nueva','En contacto','Necesidad definida','Propuesta en preparación','Propuesta enviada','Negociación / cambios') then raise exception 'OFFER_COMMERCIAL_ORIGIN_REQUIRED:SM-OP-05';end if;
   -- Relevant definitive economics remain blocked; provisional work remains independent.
   if exists(select 1 from jsonb_array_elements(v.content->'modalities') m join lateral jsonb_array_elements(v.economics) e on e->>'modalityId'=m->>'id' where m->'definitive'='true' and (cov=v.scope or cov=m->>'id' or exists(select 1 from jsonb_array_elements(m->'lines') z where z->>'id'=cov)) and (e->'calculated'='null' or jsonb_array_length(e->'blockers')>0)) then raise exception 'OFFER_DEFINITIVE_DATA_REQUIRED:BR-ECON-001';end if;
   -- Current material checks are B07 reviews, not availability/provider confirmations.
   foreach aspect in array array['prices','availability','conditions','capacity'] loop
    if not crm_private.offer_evidence((a->'reviewEvidence'->>aspect)::uuid,opp,s,'offer:review:'||vid||':'||(a->>'actId')||':send:'||aspect,cov,greatest(i.issued_at,lo),at_time) then raise exception 'OFFER_MATERIAL_REVIEW_REQUIRED:SM-PV-03';end if;
   end loop;
   select * into com from crm_private.b07_records where record_id=(a->>'communicationId')::uuid and admin_scope=s;
   select * into fact from crm_private.b07_records where record_id=(a->>'factId')::uuid and admin_scope=s;
   select * into proof from crm_private.b07_records where record_id=(fact.material->>'evidence_id')::uuid and admin_scope=s;
   if com.record_kind is distinct from 'communication' or com.material->>'direction' is distinct from 'outgoing' or com.material->>'proposal_version_ref' is distinct from vid::text or com.material->>'recipient_ref' is distinct from a->>'recipientId' or com.material->>'channel' is distinct from a->>'channel' or com.material->>'coverage' is distinct from cov
    or fact.record_kind is distinct from 'communication_fact' or fact.original_id is distinct from com.record_id or fact.material->>'fact_kind' is distinct from 'sent' or fact.material->>'party_ref' is distinct from a->>'recipientId' or fact.material->>'coverage' is distinct from cov or fact.occurred_at is distinct from at_time
    or proof.record_kind is distinct from 'evidence' or not crm_private.offer_evidence(proof.record_id,opp,s,'offer:sent:'||vid||':'||(a->>'actId')||':'||(a->>'recipientId')||':'||(a->>'channel'),cov,at_time,at_time)
    or not exists(select 1 from crm_private.identity_entities where identity_id=(a->>'recipientId')::uuid and admin_scope=s and identity_kind='contact' and identity_verified and archived_at is null and merged_into_id is null)
    or not exists(select 1 from crm_private.b07_links bl where bl.record_id=com.record_id and bl.admin_scope=s and bl.context_kind='opportunity' and bl.context_id=opp and bl.coverage=a->>'coverage')
    or not exists(select 1 from crm_private.b07_links bl where bl.record_id=fact.record_id and bl.admin_scope=s and bl.context_kind='opportunity' and bl.context_id=opp and bl.coverage=a->>'coverage') then raise exception 'OFFER_REAL_SEND_REQUIRED:SM-CO-04';end if;
   insert into crm_private.b03_operations(operation_id,admin_scope,actor_id,fingerprint,result_ref) values(op,s,actor,fp,opp);
   insert into crm_private.b03_history(history_id,subject_id,admin_scope,before_state,after_state,event,normative_ids,reason,source_ref,actor_id)
    values(op,opp,s,to_jsonb(o),jsonb_set(jsonb_set(to_jsonb(o),'{state}','"Propuesta enviada"'),'{revision}',to_jsonb(o.revision+1)),a,jsonb_build_array('SM-OP-05'),a->>'reason',a->>'sourceRef',actor);
   update crm_private.b03_opportunities set state='Propuesta enviada',revision=revision+1,updated_at=clock_timestamp() where opportunity_id=opp;
   res:=jsonb_build_object('sent',true,'received',false,'acceptanceCreated',false,'versionId',vid,'communicationId',com.record_id,'factId',fact.record_id);norm:=jsonb_build_array('SM-PV-03','SM-OP-05','SM-CO-04');
  else
   part:=nullif(a->>'partId','')::uuid;kind:=a->>'partKind';
   if kind is null or kind not in ('version','modality','line') or nullif(btrim(a->>'lossReason'),'') is null
    or kind='version' and (part is distinct from vid or cov<>v.scope)
    or kind='modality' and not exists(select 1 from crm_private.b03_proposal_modalities where version_id=vid and modality_id=part and cov=part::text)
    or kind='line' and not exists(select 1 from crm_private.b03_proposal_lines where version_id=vid and line_id=part and cov=part::text) then raise exception 'OFFER_REJECTION_SCOPE_REQUIRED';end if;
   select * into com from crm_private.b07_records where record_id=(a->>'communicationId')::uuid and admin_scope=s;
   if com.record_kind is distinct from 'communication' or com.material->>'direction' is distinct from 'incoming' or com.material->>'proposal_version_ref' is distinct from vid::text or com.material->>'sender_ref' is distinct from a->>'recipientId' or com.material->>'coverage' is distinct from cov or com.material->>'channel' is distinct from a->>'channel' or com.occurred_at is distinct from at_time
    or not exists(select 1 from crm_private.identity_entities where identity_id=(a->>'recipientId')::uuid and admin_scope=s and identity_kind='contact' and identity_verified and archived_at is null and merged_into_id is null)
    or not exists(select 1 from crm_private.b07_links bl where bl.record_id=com.record_id and bl.admin_scope=s and bl.context_kind='opportunity' and bl.context_id=opp and bl.coverage=a->>'coverage')
    or not exists(select 1 from crm_private.identity_designations d where d.context_id=opp and d.party_id=(a->>'recipientId')::uuid and d.admin_scope=s and d.role_kind='primary_contact' and d.verified and coalesce(d.effective_at,d.recorded_at)<=at_time and (d.ended_at is null or d.ended_at>at_time))
    or not crm_private.offer_evidence((a->>'evidenceId')::uuid,opp,s,'offer:reject:'||vid||':'||part||':'||(a->>'recipientId')||':'||(a->>'lossReason'),cov,at_time,at_time) then raise exception 'OFFER_ATTRIBUTABLE_REJECTION_REQUIRED:SM-PV-08';end if;
   res:=jsonb_build_object('rejected',true,'partKind',kind,'partId',part,'reason',a->>'lossReason','opportunityLost',false,'acceptanceCreated',false);norm:=jsonb_build_array('SM-PV-08','AC-005','AC-086');
  end if;
  update crm_private.b03_proposals set revision=revision+1 where proposal_id=root;
  insert into crm_private.b03_offer_operations values(op,root,vid,s,actor,fp,action,cov,at_time,a,res,a->>'sourceRef',a->>'reason',clock_timestamp());
  insert into crm_private.b03_offer_history(history_id,admin_scope,before_data,after_data,normative_ids,actor_id) values(op,s,original,res,norm,actor);
  res:=jsonb_build_object('id',op,'replayed',false,'result',res);
 end if;
 perform crm_f2.verify(f2p,f2s,q,'C03','human_evidence','write_evidence');perform crm_f1.verify_envelope(f1p,f1s,q,'C03','evidence','write_evidence');return res;
end $function$

CREATE OR REPLACE FUNCTION crm_api.offer_read(f2p bytea, f2s bytea, f1p bytea, f1s bytea, q bytea)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare hf text[];tf text[];f text[];a jsonb;vid uuid;data jsonb;
begin
 hf:=crm_f2.admit(f2p,f2s,q,'C01','read_evidence');tf:=crm_f1.verify_envelope(f1p,f1s,q,'C01','evidence','read_evidence');
 if hf[17] collate "C"<>tf[14] collate "C" then raise exception 'OFFER_DENIED';end if;
 f:=crm_f1.fields(q);if cardinality(f)<>2 or f[1]<>'CRM-H2-OFFER-READ1' then raise exception 'OFFER_INPUT_INVALID';end if;a:=f[2]::jsonb;vid:=(a->>'versionId')::uuid;
 if not exists(select 1 from crm_private.b03_proposal_versions where version_id=vid and proposal_id=(a->>'proposalId')::uuid and admin_scope=hf[17]) then raise exception 'OFFER_DENIED';end if;
 select jsonb_build_object('issuance',(select to_jsonb(t) from crm_private.b03_offer_issuances t where version_id=vid),'events',coalesce((select jsonb_agg(to_jsonb(t) order by recorded_at,operation_id) from crm_private.b03_offer_operations t where version_id=vid),'[]')) into data;
 perform crm_f2.verify(f2p,f2s,q,'C01','human_evidence','read_evidence');perform crm_f1.verify_envelope(f1p,f1s,q,'C01','evidence','read_evidence');return data;
end $function$

CREATE OR REPLACE FUNCTION crm_api.own_economics_apply(f2p bytea, f2s bytea, f1p bytea, f1s bytea, q bytea)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare h text[];t text[];f text[];a jsonb;material jsonb;fp text;proofhash text;s text;actor uuid;bid uuid;eid uuid;op uuid;at_time timestamptz;
 root crm_private.b05_own_economies;prev crm_private.b05_own_economic_operations;old jsonb;state jsonb;r jsonb;rev bigint;comp jsonb;kind text;rulehash text;refs jsonb;sources jsonb;existing jsonb;
begin
 h:=crm_f2.admit(f2p,f2s,q,'C03','write_evidence');t:=crm_f1.verify_envelope(f1p,f1s,q,'C03','evidence','write_evidence');f:=crm_f1.fields(q);
 if h[17] collate "C" is distinct from t[14] collate "C" or cardinality(f)<2 or f[1]<>'CRM-H3-OWN1' then raise exception 'OWN_ECONOMICS_DENIED';end if;a:=array_to_string(f[2:cardinality(f)],'')::jsonb;
 if jsonb_typeof(a) is distinct from 'object' or a-array['operationId','economyId','bookingId','scope','expectedRevision','expectedBookingRevision','at','sourceRef','reason','evidenceId','input','sources','computed']<>'{}'::jsonb or not(a ?& array['operationId','economyId','bookingId','scope','expectedRevision','expectedBookingRevision','at','sourceRef','reason','evidenceId','input','sources','computed'])
 or exists(select 1 from unnest(array['operationId','economyId','bookingId','scope','at','sourceRef','reason','evidenceId']) k where not coalesce(crm_private.invoice_text(a->k),false))
 or jsonb_typeof(a->'expectedRevision') is distinct from 'number' or a->>'expectedRevision' !~ '^(0|[1-9][0-9]*)$' or jsonb_typeof(a->'expectedBookingRevision') is distinct from 'number' or a->>'expectedBookingRevision'<>'1'
 or a->'computed'->>'algorithmVersion' is distinct from 'h1-money-d023-d028-d029-v1' or a->'computed'->>'currency' is distinct from 'EUR' then raise exception 'OWN_ECONOMICS_INPUT_INVALID';end if;
 bid:=(a->>'bookingId')::uuid;eid:=(a->>'economyId')::uuid;op:=(a->>'operationId')::uuid;s:=h[17];actor:=h[12]::uuid;at_time:=(a->>'at')::timestamptz;
 if not exists(select 1 from crm_private.b04_bookings where booking_id=bid and admin_scope=s) then raise exception 'OWN_ECONOMICS_DENIED';end if;
 material:=a-array['computed','sources'];fp:=encode(crm_crypto.digest(convert_to(material::text,'UTF8'),'sha256'),'hex');perform pg_advisory_xact_lock(hashtextextended('own-economic-op:'||op,0));
 select * into prev from crm_private.b05_own_economic_operations where operation_id=op;
 if found then if prev.admin_scope<>s or prev.actor_id<>actor or prev.fingerprint<>fp then raise exception 'OWN_ECONOMICS_REPLAY_CONFLICT:E2';end if;r:=prev.result||jsonb_build_object('replayed',true);
 else
  proofhash:=encode(crm_crypto.digest(convert_to((material-array['operationId','evidenceId'])::text,'UTF8'),'sha256'),'hex');
  if not crm_private.payment_evidence((a->>'evidenceId')::uuid,eid,s,'own-economics:'||proofhash,at_time,true) or not exists(select 1 from crm_private.b07_records where record_id=(a->>'evidenceId')::uuid and recorded_by=actor) then raise exception 'OWN_ECONOMICS_EVIDENCE_REQUIRED';end if;
  for comp in select value from jsonb_array_elements(a->'input'->'fees') union all select value from jsonb_array_elements(a->'input'->'costs') loop
   rulehash:=encode(crm_crypto.digest(convert_to(((comp->'rule')-'approvalEvidenceId')::text,'UTF8'),'sha256'),'hex');
   if not crm_private.payment_evidence((comp->'rule'->>'approvalEvidenceId')::uuid,eid,s,'own-rule:'||rulehash,at_time,true) then raise exception 'OWN_ECONOMICS_APPROVED_RULE_REQUIRED';end if;
  end loop;
  perform pg_advisory_xact_lock(hashtextextended('own-economic-booking:'||s||':'||bid,0));
  if a->'computed'->'promotion'->>'status'='applied' and exists(select 1 from crm_private.b05_own_economies e join lateral(select after_data from crm_private.b05_own_economic_revisions v where v.economy_id=e.economy_id order by revision desc limit 1) v on true where e.booking_id=bid and e.admin_scope=s and e.economy_id<>eid and v.after_data->'computed'->'promotion'->>'status'='applied') then raise exception 'OWN_ECONOMICS_PROMOTION_ALREADY_APPLIED';end if;
  perform pg_advisory_xact_lock(hashtextextended('own-economic-scope:'||s||':'||bid||':'||(a->>'scope'),0));
  select * into root from crm_private.b05_own_economies where booking_id=bid and scope_ref=a->>'scope' and admin_scope=s;
  if not found then
   if (a->>'expectedRevision')::bigint<>0 then raise exception 'OWN_ECONOMICS_REVISION_CONFLICT:E2';end if;
   insert into crm_private.b05_own_economies values(eid,bid,a->>'scope',s,op);rev:=0;
  else
   if root.economy_id<>eid then raise exception 'OWN_ECONOMICS_IDENTITY_CONFLICT:E2';end if;
   select revision,after_data into rev,old from crm_private.b05_own_economic_revisions where economy_id=eid order by revision desc limit 1;
   if rev<>(a->>'expectedRevision')::bigint then raise exception 'OWN_ECONOMICS_REVISION_CONFLICT:E2';end if;
  end if;
  select coalesce(jsonb_agg(to_jsonb(x) order by x),'[]') into refs from(select distinct value x from (select value->>'unitRevisionId' value from jsonb_array_elements(a->'input'->'fees') union all select value->>'pricingFormRevisionId' from jsonb_array_elements(a->'input'->'fees') union all select value->>'unitRevisionId' from jsonb_array_elements(a->'input'->'costs') union all select value->>'pricingFormRevisionId' from jsonb_array_elements(a->'input'->'costs') union all select value->>'unitRevisionId' from jsonb_array_elements(a->'input'->'tarari') union all select value->>'pricingFormRevisionId' from jsonb_array_elements(a->'input'->'tarari') union all select a->'input'->'promotion'->>'revisionId' where a->'input'->'promotion'<>'null'::jsonb) allrefs where value is not null) distinctrefs;
  sources:=crm_private.own_economic_sources(bid,refs,s);if sources is distinct from a->'sources' then raise exception 'OWN_ECONOMICS_SOURCE_CHANGED:E2';end if;
  a:=jsonb_set(a,'{computed}',(a->'computed')||jsonb_build_object('bookingSource',sources->'booking','modalities',sources->'modalities'));
  if old is not null and old->'input'=a->'input' and old->'computed'=a->'computed' and old->>'reason'=a->>'reason' and old->>'sourceRef'=a->>'sourceRef' and old->>'actorId'=actor::text and (old->>'at')::timestamptz=at_time then
   r:=jsonb_build_object('id',eid,'replayed',true,'result',old);insert into crm_private.b05_own_economic_operations values(op,eid,s,actor,fp,material,r,rev,clock_timestamp());
  else
  rev:=rev+1;state:=jsonb_build_object('id',eid,'bookingId',bid,'scope',a->>'scope','revision',rev,'input',a->'input','computed',a->'computed','sources',sources,'actorId',actor,'at',at_time,'reason',a->>'reason','sourceRef',a->>'sourceRef','previousRevision',rev-1);
  insert into crm_private.b05_own_economic_operations values(op,eid,s,actor,fp,material,jsonb_build_object('id',eid,'replayed',false,'result',state),rev,clock_timestamp());
  foreach kind in array array['fee','cost','tarari','promotion'] loop
   if kind='promotion' then if a->'computed'->'promotion'<>'null'::jsonb then insert into crm_private.b05_own_economic_components values(eid,rev,'promotion',kind,s,a->'computed'->'promotion');end if;
   else for comp in select value from jsonb_array_elements(a->'computed'->(case kind when 'fee' then 'fees' when 'cost' then 'costs' else 'tarari' end)) loop
    insert into crm_private.b05_own_economic_components values(eid,rev,coalesce(comp->'component'->>'id',comp->>'id'),kind,s,comp);
   end loop;end if;
  end loop;
  insert into crm_private.b05_own_economic_revisions values(eid,rev,s,op,old,state,actor,(a->>'evidenceId')::uuid,a->>'reason',a->>'sourceRef',at_time,clock_timestamp());r:=jsonb_build_object('id',eid,'replayed',false,'result',state);
  end if;
 end if;
 perform crm_f2.verify(f2p,f2s,q,'C03','human_evidence','write_evidence');perform crm_f1.verify_envelope(f1p,f1s,q,'C03','evidence','write_evidence');return r;
end$function$

CREATE OR REPLACE FUNCTION crm_api.own_economics_read(f2p bytea, f2s bytea, f1p bytea, f1s bytea, q bytea)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare h text[];t text[];f text[];a jsonb;r jsonb;
begin
 h:=crm_f2.admit(f2p,f2s,q,'C01','read_evidence');t:=crm_f1.verify_envelope(f1p,f1s,q,'C01','evidence','read_evidence');f:=crm_f1.fields(q);
 if h[17] collate "C" is distinct from t[14] collate "C" or cardinality(f)<2 or f[1]<>'CRM-H3-OWN-READ1' then raise exception 'OWN_ECONOMICS_DENIED';end if;a:=array_to_string(f[2:cardinality(f)],'')::jsonb;
