 if hf[17] collate "C" is distinct from tf[14] collate "C" or fs[1]<>'CRM-H0-M04' or fs[2]<>'reserve' or a->>'action'<>'schedule' then raise exception 'PROVIDER_PAYMENT_TTE_REQUIRED';end if;
