CREATE OR REPLACE FUNCTION crm_api.record_global_auth_revocation_outcome(p bytea, s bytea, q bytea)
 RETURNS TABLE(auth_state text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
#variable_conflict use_column
declare f text[]; qf text[]; current_record crm_private.global_access_revocations%rowtype;
  requested_revocation uuid; requested_attempt uuid; requested_outcome text;
  at_time timestamptz; next_attempt integer;
begin
  f:=crm_f1.verify_envelope(p,s,q,'C03','global_access_revocation','record_auth_outcome');
  qf:=crm_f1.fields(q);
  if cardinality(qf)<>5 or qf[1]<>'CRM-H0-M05-AUTH1' or qf[2]<>'C03'
    or qf[5] not in ('revoked','failed','uncertain')
  then raise exception 'H0_M05_DENIED' using errcode='42501'; end if;
  requested_revocation:=qf[3]::uuid;
  requested_attempt:=qf[4]::uuid;
  requested_outcome:=qf[5];
  select * into strict current_record from crm_private.global_access_revocations
    where revocation_id=requested_revocation for update;
  if current_record.admin_scope collate "C"<>f[14] collate "C"
    or current_record.auth_state='revoked'
  then raise exception 'H0_M05_DENIED' using errcode='42501'; end if;
  at_time:=clock_timestamp();
  next_attempt:=current_record.auth_attempt_count+1;
  insert into crm_private.global_access_revocation_attempts(
    attempt_id,revocation_id,attempt_number,outcome,recorded_at
  ) values (requested_attempt,requested_revocation,next_attempt,requested_outcome,at_time);
  update crm_private.global_access_revocations set
    auth_state=requested_outcome,
    auth_attempt_count=next_attempt,
    last_auth_attempt_at=at_time,
    auth_revoked_at=case when requested_outcome='revoked' then at_time else null end
    where revocation_id=requested_revocation;
  perform crm_f1.verify_envelope(p,s,q,'C03','global_access_revocation','record_auth_outcome');
  return query select requested_outcome;
exception when others then raise exception 'H0_M05_DENIED' using errcode='42501';
end $function$

CREATE OR REPLACE FUNCTION crm_api.record_recovery_auth_outcome(p bytea, s bytea, q bytea)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare f text[]; v text[]; r crm_private.access_recoveries%rowtype;
  a crm_private.crm_actors%rowtype; rid uuid; outcome text;
begin
  f:=crm_f1.verify_envelope(p,s,q,'C03','access_recovery','record_auth_outcome');
  v:=crm_f1.fields(q);
  if cardinality(v)<>4 or v[1]<>'CRM-H0-M06-REC1' or v[2]<>'auth'
    or v[4] not in ('revoked','failed','uncertain')
  then raise exception 'H0_M06_DENIED' using errcode='42501'; end if;
  rid:=v[3]::uuid; outcome:=v[4];
  select * into strict r from crm_private.access_recoveries where recovery_id=rid;
  select * into strict a from crm_private.crm_actors where actor_id=r.actor_id for update;
  select * into strict r from crm_private.access_recoveries where recovery_id=rid for update;
  if r.admin_scope collate "C"<>f[14] collate "C"
    or a.access_generation<>r.access_generation or a.access_state<>'recovery_in_progress'
    or r.completed_at is not null or (r.auth_state<>'pending' and r.auth_state<>outcome)
  then raise exception 'H0_M06_DENIED' using errcode='42501'; end if;
  if r.auth_state='pending' then
    update crm_private.access_recoveries set auth_state=outcome,
      auth_recorded_at=clock_timestamp() where recovery_id=rid;
  end if;
  perform crm_f1.verify_envelope(p,s,q,'C03','access_recovery','record_auth_outcome');
  return outcome;
exception when others then raise exception 'H0_M06_DENIED' using errcode='42501';
end $function$

CREATE OR REPLACE FUNCTION crm_api.refund_apply(f2p bytea, f2s bytea, f1p bytea, f1s bytea, q bytea)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
