  if x->'components'->'payment' is distinct from r->'components'->'payment' or x->'pending' is distinct from r->'pending' then changed:=changed||'"provider_payment"'::jsonb;end if;
  current_components:=x->'components';
  r:=r||jsonb_build_object('currentComponents',current_components,'sourceRevalidationRequired',changed,'snapshotRevision',r->'revision');
  if changed<>'[]'::jsonb then r:=r||jsonb_build_object('status','Revisión','pending',(r->'pending')||jsonb_build_array('source_revalidation'),'currentDocumentaryResolved',false);end if;
 end if;
 if r is not null then r:=r||jsonb_build_object('history',(select jsonb_agg(jsonb_build_object('revision',revision,'action',action_kind,'before',before_data,'after',after_data,'actorId',actor_id,'reason',reason,'sourceRef',source_ref,'evidenceId',evidence_id,'at',occurred_at,'recordedAt',recorded_at) order by revision) from crm_private.b05_suplido_revisions where suplido_id=(a->>'suplidoId')::uuid and admin_scope=hf[17]));end if;
 perform crm_f2.verify(f2p,f2s,q,'C01','human_evidence','read_evidence');perform crm_f1.verify_envelope(f1p,f1s,q,'C01','evidence','read_evidence');return r;
end$function$

CREATE OR REPLACE FUNCTION crm_f1.fields(raw bytea)
 RETURNS text[]
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare pos integer := 0; size integer; part bigint; result text[] := '{}'; value text;
begin
  if raw is null or octet_length(raw) = 0 or octet_length(raw) > 65536 then
    raise exception 'F1_DENIED' using errcode = '42501';
  end if;
  size := octet_length(raw);
  while pos < size loop
    if pos + 4 > size then raise exception 'F1_DENIED' using errcode = '42501'; end if;
    part := get_byte(raw,pos)::bigint * 16777216 + get_byte(raw,pos+1) * 65536
      + get_byte(raw,pos+2) * 256 + get_byte(raw,pos+3);
    pos := pos + 4;
    if part > 16384 or pos + part > size then raise exception 'F1_DENIED' using errcode = '42501'; end if;
    value := convert_from(substring(raw from pos+1 for part::integer), 'UTF8');
    result := array_append(result,value);
    pos := pos + part::integer;
  end loop;
  return result;
exception when others then raise exception 'F1_DENIED' using errcode = '42501';
end $function$

CREATE OR REPLACE FUNCTION crm_f1.pack_fields(field_values text[])
 RETURNS bytea
 LANGUAGE plpgsql
 IMMUTABLE PARALLEL SAFE
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare result bytea := ''::bytea; value text; bytes bytea; size integer := 0;
begin
  if field_values is null or cardinality(field_values) = 0 then
    raise exception 'F1_DENIED' using errcode = '42501';
  end if;
  foreach value in array field_values loop
    if value is null then
      raise exception 'F1_DENIED' using errcode = '42501';
    end if;
    bytes := convert_to(value, 'UTF8');
    size := size + 4 + octet_length(bytes);
    if octet_length(bytes) > 16384 or size > 65536 then
      raise exception 'F1_DENIED' using errcode = '42501';
    end if;
    result := result || decode(lpad(to_hex(octet_length(bytes)),8,'0'),'hex') || bytes;
  end loop;
  return result;
exception when others then raise exception 'F1_DENIED' using errcode = '42501';
end $function$

CREATE OR REPLACE FUNCTION crm_f1.row_allows(scope_value text, id_value text, public_value text, op text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare f text[]; qf text[]; q bytea; i integer;
begin
  q := decode(current_setting('crm.f1_input',true),'hex');
  f := crm_f1.verify(decode(current_setting('crm.f1_payload',true),'hex'),
    decode(current_setting('crm.f1_mac',true),'hex'), q, op);
  if scope_value collate "C" <> f[14] collate "C" then return false; end if;
  qf := crm_f1.fields(q);
  if op = 'C01' then return id_value collate "C" = qf[3] collate "C"; end if;
  i := 6;
  while i <= cardinality(qf) loop
    if id_value collate "C" = qf[i+1] collate "C" and public_value collate "C" = qf[i+2] collate "C"
      then return true; end if;
    i := i+3;
  end loop;
  return false;
exception when others then return false;
end $function$

CREATE OR REPLACE FUNCTION crm_f1.unit_row_allows(scope_value text, root_value text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare f text[]; qf text[]; q bytea;
begin
  q := decode(current_setting('crm.f1_input',true),'hex');
  f := crm_f1.verify_unit(decode(current_setting('crm.f1_payload',true),'hex'),
    decode(current_setting('crm.f1_mac',true),'hex'),q);
  qf := crm_f1.fields(q);
  return scope_value collate "C" = f[14] collate "C"
    and root_value collate "C" = qf[4] collate "C";
exception when others then return false;
end $function$

CREATE OR REPLACE FUNCTION crm_f1.verify(p bytea, s bytea, q bytea, op text)
 RETURNS text[]
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare f text[]; qf text[]; i integer;
begin
  f := crm_f1.verify_envelope(p,s,q,op,'access_probe',
    case op when 'C01' then 'read_probe' else 'apply_probe_batch' end);
  qf := crm_f1.fields(q);
  if cardinality(qf) < 3 or qf[1] <> 'CRM-INP1' or qf[2] <> op then
    raise exception 'F1_DENIED' using errcode='42501';
  end if;
  if op = 'C01' then
    if cardinality(qf) <> 3 or qf[3] = '' then raise exception 'F1_DENIED' using errcode='42501'; end if;
  else
    if cardinality(qf) < 6 or qf[3] = '' or qf[4] <> 'true' or qf[5] <> 'true'
      or (cardinality(qf)-5) % 3 <> 0 then raise exception 'F1_DENIED' using errcode='42501'; end if;
    i := 6;
    while i <= cardinality(qf) loop
      if qf[i] <> 'record-technical-probe' or qf[i+1] = '' then
        raise exception 'F1_DENIED' using errcode='42501'; end if;
      i := i+3;
    end loop;
  end if;
  return f;
exception when others then raise exception 'F1_DENIED' using errcode='42501';
end $function$

CREATE OR REPLACE FUNCTION crm_f1.verify_unit(p bytea, s bytea, q bytea)
 RETURNS text[]
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare f text[]; qf text[]; expected_material text; expected_content text;
begin
  f := crm_f1.verify_envelope(p,s,q,'C03','internal_unit','commit_internal_unit');
  qf := crm_f1.fields(q);
  if cardinality(qf) <> 18 or qf[1] <> 'CRM-UNIT1'
    or qf[2] !~ '^[a-z][a-z0-9-]{0,127}$'
    or qf[3] <> 'technical-state-change'
    or qf[4] !~ '^[a-z][a-z0-9-]{0,127}$'
    or qf[5] !~ '^(0|[1-9][0-9]{0,18})$'
    or qf[6] !~ '^[0-9a-f]{64}$'
    or qf[7] = '' or qf[8] = '' or qf[9] !~ '^[a-z][a-z0-9-]{0,127}$'
    or qf[11] = '' or qf[12] not in ('none','candidate')
    or qf[13] not in ('true','false')
  then raise exception 'F1_DENIED' using errcode='42501'; end if;
  if qf[10] <> '' then perform qf[10]::timestamptz; end if;
  if qf[13] = 'false' then
    if qf[14] <> '' or qf[15] <> '' or qf[16] <> '' or qf[17] <> '' or qf[18] <> '' then
      raise exception 'F1_DENIED' using errcode='42501'; end if;
  else
    if qf[14] !~ '^[a-z][a-z0-9-]{0,127}$' or qf[15] !~ '^[a-z][a-z0-9-]{0,127}$'
      or qf[16] = '' or qf[17] = '' or qf[18] !~ '^[0-9a-f]{64}$' then
      raise exception 'F1_DENIED' using errcode='42501'; end if;
    expected_content := encode(crm_crypto.digest(crm_f1.pack_fields(array[
      'CRM-INTENT-MATERIAL1',qf[14],qf[16],qf[17]
    ]),'sha256'),'hex');
    if qf[18] <> expected_content then raise exception 'F1_DENIED' using errcode='42501'; end if;
  end if;
  expected_material := encode(crm_crypto.digest(crm_f1.pack_fields(array[
    'CRM-UNIT-MATERIAL1',qf[3],qf[4],qf[5],qf[11],qf[8],qf[9],qf[10],qf[12],
    f[11],f[12],f[13],f[14],qf[13],qf[14],qf[15],qf[16],qf[17],qf[18]
  ]),'sha256'),'hex');
  if qf[6] <> expected_material then raise exception 'F1_DENIED' using errcode='42501'; end if;
  return f;
exception when others then raise exception 'F1_DENIED' using errcode='42501';
end $function$

CREATE OR REPLACE FUNCTION crm_f2.verify(p bytea, s bytea, q bytea, expected_operation text, expected_resource text, expected_action text)
 RETURNS text[]
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare f text[]; k crm_f2.keys%rowtype; e bytea; b bytea; l bytea; r bytea;
  acc integer := 0; i integer; now_us bigint;
begin
  if p is null or q is null or octet_length(q)>65536 or s is null or octet_length(s)<>32
  then raise exception 'F2_DENIED' using errcode='42501'; end if;
  f := crm_f1.fields(p);
  if cardinality(f)<>25 or array_position(f,'') is not null
    or f[1]<>'CRM-H0F2' or f[2]<>'1' or f[10]<>session_user or not (
    (session_user='crm_h0_runtime' and (
      (f[16]='full-identification' and f[19]='human_session' and f[18]=f[20] and f[18] in ('establish','reidentify'))
      or (f[16]='session-revocation' and f[18]=f[20] and ((f[18]='revoke_one' and f[19]='human_session') or (f[18]='revoke_all' and f[19]='human_actor')))))
    or (session_user in ('crm_h0_runtime','crm_h0_ha_tx') and f[16]='core-human-access'
      and ((f[19]='human_core_probe' and ((f[18]='C01' and f[20]='read_probe') or (f[18]='C03' and f[20]='apply_probe_batch')))
        or (session_user='crm_h0_runtime' and f[19]='human_identities'
          and ((f[18]='C01' and f[20]='read_identity') or (f[18]='C03' and f[20]='write_identity')))
        or (session_user='crm_h0_runtime' and f[19]='human_catalog'
          and ((f[18]='C01' and f[20]='read_catalog') or (f[18]='C03' and f[20]='write_catalog')))
        or (session_user='crm_h0_runtime' and f[19]='human_evidence'
          and ((f[18]='C01' and f[20]='read_evidence') or (f[18]='C03' and f[20]='write_evidence'))))))
    or current_setting('transaction_isolation')<>'read committed'
    or f[18]<>expected_operation or f[19]<>expected_resource or f[20]<>expected_action
    or f[15] !~ '^[1-9][0-9]{0,18}$'
  then raise exception 'F2_DENIED' using errcode='42501'; end if;
  select * into strict k from crm_f2.keys where key_id=f[3] collate "C";
  if not k.enabled or clock_timestamp()<k.valid_from or clock_timestamp()>=k.valid_until
    or f[4] collate "C"<>k.audience collate "C"
    or f[5] collate "C"<>k.generation collate "C"
    or not (f[16]=any(k.purposes))
  then raise exception 'F2_DENIED' using errcode='42501'; end if;
  e := crm_crypto.hmac(p,k.secret,'sha256');
  b := crm_crypto.gen_random_bytes(32);
  l := crm_crypto.hmac(convert_to('CRM-H0F2-CMP-v1','UTF8') || e,b,'sha256');
  r := crm_crypto.hmac(convert_to('CRM-H0F2-CMP-v1','UTF8') || s,b,'sha256');
  if e is null or b is null or l is null or r is null
    or octet_length(e)<>32 or octet_length(b)<>32
    or octet_length(l)<>32 or octet_length(r)<>32
  then raise exception 'F2_DENIED' using errcode='42501'; end if;
  for i in 0..31 loop acc := acc | (get_byte(l,i) # get_byte(r,i)); end loop;
  if acc<>0 then raise exception 'F2_DENIED' using errcode='42501'; end if;
  now_us := floor(extract(epoch from clock_timestamp())*1000000)::bigint;
  if f[6]<>(select oid::text from pg_database where datname=current_database())
    or f[7]<>(extract(epoch from pg_postmaster_start_time())*1000000)::bigint::text
    or f[8]<>pg_current_xact_id()::text or f[9]<>pg_backend_pid()::text
    or f[22]<>encode(crm_crypto.digest(q,'sha256'),'hex')
    or f[23] !~ '^(0|[1-9][0-9]{0,18})$'
    or f[24] !~ '^(0|[1-9][0-9]{0,18})$'
    or f[24]::bigint-f[23]::bigint<>30000000
    or now_us<f[23]::bigint or now_us>=f[24]::bigint
  then raise exception 'F2_DENIED' using errcode='42501'; end if;
  return f;
exception when others then raise exception 'F2_DENIED' using errcode='42501';
end $function$
